window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["med:med-clinica-medica-med-clm-05"]={"block":"med:med-clinica-medica-med-clm-05","label":"MED · MED CLM 05","count":432,"questions":[{"id":"med-clinica-medica-med-clm-05-345467","number":"345467","sourceNumber":"345467","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Mulher de 65 anos apresenta quadro de fadiga e fraqueza nas últimas 2 semanas. Ela\ntem histórico de hipertensão, diabete tipo 2 e artrite reumatoide, em uso de metotrexato e\nprednisona. Por causa do controle inadequado, o etanercepte foi adicionado há 2 semanas,\nocasião em que ela decidiu descontinuar a prednisona devido ao aumento de hematomas em sua\npele. Além de metrotexato e etanercepte, ela está em uso de ácido fólico, metformina e aspirina em\nbaixas doses. Ao exame físico: pressão arterial: 110 x 68 mmHg sentada e 90 x 64 mmHg em pé;\nfrequência cardíaca: 102 bpm sentada e 110 bpm em pé; observa-se edema sinovial simétrico nas\narticulações metacarpofalângicas e punhos bilateralmente. Exames laboratoriais mostram um nível\nde cortisol às 8h00 de 2 µg/dL (normal: 5 a 25). O manejo inicial de escolha é:","options":{"A":"Tomografia de adrenais.","B":"Hidrocortisona.","C":"Teste de estimulação com ACTH após administração de dexametasona.","D":"Teste de estimulação de hormônio adrenocorticotrófico (ACTH)."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-345515","number":"345515","sourceNumber":"345515","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Em relação ao preparo do paciente com hipertireoidismo para uma cirurgia de urgência\nnão tireoidiana, assinale a alternativa\nINCORRETA:","options":{"A":"O metimazol inibe a conversão periférica de T4 (tiroxina) em T3 (triiodotironina).","B":"Iodo inorgânico impede a liberação de T4 e T3 da tireoide.","C":"O propiltiouracil inibe a síntese de hormônios tireoidianos.","D":"O uso de betabloqueadores beta-adrenérgicos visa antagonizar as manifestações periféricas da\ntereotoxicose."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-343853","number":"343853","sourceNumber":"343853","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Sobre a Hipercalcemia é CORRETO afirmar:","options":{"A":"Iatrogenia e efeitos colaterais medicamentosos são superiores na incidência desta alteração em\nrelação ao Hiperparatireoidismo primário e às neoplasias.","B":"O tratamento é focado no estímulo direto da excreção do cálcio pelo receptor específico na Alça\nde Henle, com a acidificação do fluído urinário.","C":"Entre os bifosfonados, o Clodronato é o que tem ação mais rápida, contudo é principal causa de\nnecrose de mandíbula.","D":"Hemodiálise é uma opção terapêutica avaliada."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-291765","number":"291765","sourceNumber":"291765","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Homem, 45 anos de idade, morador de zona rural, procurou atendimento médico por\nqueixa de úlcera dolorosa em dorso do pé esquerdo há seis meses. No interrogatório sistemático,\nqueixou-se, também, de astenia e tosse seca. Tabagista de 25 anos/maço, sem outras\ncomorbidades. Ao exame físico, regular estado geral, afebril. Apresentava úlcera com 20 mm de\ndiâmetro, com bordas elevadas, eritematosas e fundo com pontilhado hemático. Realizada biópsia\nda lesão, evidenciou processo granulomatoso, com presença de células leveduriformes com\nbrotamento em roda de leme. Radiografia de tórax com infiltrado retículo-nodular difuso. Paciente\nperdeu seguimento e, três meses depois, voltou a procurar atendimento médico com quadro de\nhipotensão, apresentando exames laboratoriais com Na = 119 mEq/L; e K = 6,1mEq/L,\nnecessitando de internação hospitalar. Diante do caso, Indique a hipótese diagnóstica principal\ndiante da complicação apresentada posteriormente.","options":{"A":"Doença de Addison.","B":"Síndrome de Cushing.","C":"Síndrome perdedora de sal.","D":"Síndrome de secreção inapropriada de hormônio antidiurético."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-283281","number":"283281","sourceNumber":"283281","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Mulher de 28 anos apresenta Síndrome de Cushing associada a carcinoma de adrenal\nsecretor de cortisol. Dos abaixo, os achados MENOS prováveis são:","options":{"A":"Osteopenia e fraqueza muscular.","B":"Hisurtismo e ganho de peso.","C":"Intolerância a glicose e acne.","D":"Hipercalemia e hiperpigmentação cutânea."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-281104","number":"281104","sourceNumber":"281104","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Das patologias endócrinas citadas nas alternativas abaixo, a que NÃO faz parte da\nNEM tipo 1 (neoplasia endócrina tipo 1) é:","options":{"A":"Hiperparatireoidismo primário.","B":"Gastrinoma.","C":"Insulinoma.","D":"Acromegalia.","E":"Carcinoma medular de tireoide."},"answer":"E","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-281109","number":"281109","sourceNumber":"281109","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente de 26 anos de idade é admitido na unidade de terapia intensiva em\npósoperatório de excisão transesfenoidal de\ntumor de hipófise. Evolui no pós-operatório imediato\ncom polidipsia e poliúria. Neste momento a glicemia capilar foi de 152mg/dl. Levando em\nconsideração a hipótese diagnóstica principal, o tratamento seria:","options":{"A":"insulina regular conforme a glicemia capilar.","B":"restrição de água oral.","C":"desmopressina.","D":"dexametasona.","E":"metformina."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-291777","number":"291777","sourceNumber":"291777","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente, sexo feminino, 45 anos de idade, é encaminhada ao ambulatório de cirurgia\npor apresentar nódulo palpável em região cervical\nanterior. A paciente nega comorbidades ou uso\nde medicações. Ao exame, bom estado geral, presença de nódulo palpável na topografia da\nglândula tireoide, medindo cerca de 1,2cm no maior diâmetro. Foi realizada uma ultrassonografia\nda região cervical. Caso indicado tratamento cirúrgico para o nódulo, determine, dentre as opções\napresentadas, a principal preocupação do cirurgião nas primeiras 48 horas do pós-operatório.","options":{"A":"Infecção do sítio cirúrgico.","B":"Hipotireoidismo.","C":"Hemorragia.","D":"Hipocalcemia."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-283293","number":"283293","sourceNumber":"283293","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"A triagem neonatal ou teste do pezinho é uma estratégia de prevenção, sendo o\nhipotireoidismo congênito uma das doenças triadas, considerando essa alteração marque a\nalternativa CORRETA:","options":{"A":"É a principal causa de déficit cognitivo tratável na infância.","B":"Não é uma condição grave na infância.","C":"Fazem parte da clínica no neonato letargia, constipação e queda de cabelo.","D":"O tratamento somente é indicado na presença do quadro clínico, geralmente, a partir do 2º mês\nde vida."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-283316","number":"283316","sourceNumber":"283316","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Durante a cirurgia de tireoidectomia a principal estrutura nervosa a ser identificada e\npreservada é o nervo laríngeo recorrente. Estes são responsáveis, entre outras, pela abertura\nglótica decorrente da inervação da seguinte estrutura muscular:","options":{"A":"mm. Tireohioideo.","B":"mm. Cricoaritenóideo.","C":"mm. Cricofaringeo.","D":"mm. Cricotireoideo."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-251859","number":"251859","sourceNumber":"251859","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente feminina com 65 anos apresenta fadiga, intolerância ao frio, ganho de peso,\ndepressão, menorragia, rouquidão, pele seca e áspera, bradicardia e reflexos tendinosos profundos\nlentos. Assinale as mais prováveis alterações laboratoriais encontradas:","options":{"A":"TSH diminuído e T4 elevado.","B":"TSH aumentado e T4 diminuído.","C":"TSH normal e T4 aumentado.","D":"TSH diminuído e T4 diminuído."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-247176","number":"247176","sourceNumber":"247176","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente do sexo feminino, 53 anos, apresenta queixa de pele seca, fadiga,\nconstipação e ganho de peso nos últimos seis\nmeses. Trabalha em mercado de frutos do mar,\nrelata internação prévia para realização de histerectomia há 18 meses e faz uso ocasional de\n\nanti-inflamatório para alívio de dorsalgia. A dosagem de TSH é de 39 uIU/L. Assinale a alternativa\nCORRETA, que apresenta o diagnóstico mais provável.","options":{"A":"Hipotireoidismo pós-cirúrgico.","B":"Hipotireoidismo terciário.","C":"Hipotireoidismo secundário à intoxicação por iodo.","D":"Hipotireoidismo medicamentoso.","E":"Hipotireoidismo primário."},"answer":"E","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-217681","number":"217681","sourceNumber":"217681","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente de 70 anos de idade, portadora de doença de Graves, em uso irregular de\nmetimazol, evoluiu no pós-operatório imediato de endarterectomia com dispneia súbita, associada à\ntaquicardia (FC de 128 bpm e pulso irregular), à febre (38 graus), à PA de 100 x 80 mmHg e à\nagitação psicomotora. O eletrocardiograma mostrou fibrilação atrial de alta resposta ventricular\n(prévio em ritmo sinusal) e o ecocardiograma transtorácico, o dímero D e a troponina estavam\nnormais. Com base nesse caso hipotético, assinale a alternativa que apresenta o diagnóstico mais\nprovável.","options":{"A":"Tempestade tireoidiana.","B":"Tromboembolismo pulmonar.","C":"Dissecção de carótida.","D":"Síndrome coronariana aguda."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-217673","number":"217673","sourceNumber":"217673","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente sexo masculino, 50 anos, há 2 meses com crises de confusão mental,\nsudorese fria e hipotensão, que melhoram com\na ingestão de alimentos. Numa das crises\napresentava glicemia de 40 mg/dl. Ao exame físico não apresenta alterações. A ultrassonografia de\nabdome foi normal e a ressonância nuclear magnética demonstrou uma lesão sólida de 2 cm de\ncauda de pâncreas. Qual hipótese diagnóstica?","options":{"A":"Tumor neuroendócrino de pâncreas.","B":"Adenocarcinoma de pâncreas.","C":"Tumor de Frantz.","D":"Neoplasia papilar intraductal."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-217683","number":"217683","sourceNumber":"217683","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente sexo feminino, 32 anos, refere que apresenta ataques de cefaleia,\npalpitações, tremores, palidez e sudorese com\nelevação da pressão arterial. Foi aventada a\nhipótese de feocromocitoma e confirmada com a dosagem elevada de metanefrinas urinárias e\ndetecção de nódulo de 2,5 cm em adrenal direita. Foi indicado adrenalectomia direita. Qual o\npreparo necessário no pré-operatório?","options":{"A":"Uso de bloqueador ?-1 adrenérgico para evitar crise hipertensiva no intraoperatório.","B":"Uso de bloqueador ?-1 adrenérgico para evitar crise hipertensiva no pós-operatório.","C":"Uso de bloqueador ß-1 adrenérgico para evitar crise hipertensiva no intraoperatório.","D":"Uso de bloqueador ?-1 e ß-1 adrenérgico para evitar crise hipertensiva no intraoperatório."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-217696","number":"217696","sourceNumber":"217696","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente de 43 anos foi submetida à Tireoidectomia total por nódulo suspeito de\ncarcinoma papilífero. No 1º dia de pós-operatório apresentou sintomas de parestesia de língua e\nperioral. O médico residente que está passando a visita observa que durante a conversa, a\npaciente apresenta espasmos da musculatura facial. Assinale a alternativa que corresponda ao\nprovável diagnóstico e a devida terapêutica a ser instituída.","options":{"A":"A paciente está evoluindo bem e pode receber alta.","B":"Hipoparatireoidismo. Tratar com cloreto de cálcio por via endovenosa.","C":"Pode ser um AVC. Devem ser instituídas medidas de suporte avançado de vida.","D":"Hipotireoidismo. Iniciar reposição de levotiroxina oral, imediatamente."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-183153","number":"183153","sourceNumber":"183153","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Das patologias endócrinas citadas nas alternativas abaixo, a que NÃO faz parte da\nNEM tipo 1 (Neoplasia Endócrina tipo 1) é:","options":{"A":"Acromegalia.","B":"Insulinoma.","C":"Gastrinoma.","D":"Carcinoma medular de tireoide.","E":"Hiperparatireoidismo primário."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-182629","number":"182629","sourceNumber":"182629","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente com diagnóstico de hipotireoidismo subclínico deve necessariamente ter as\nseguintes alterações nos exames de função da tireóide:","options":{"A":"T4 livre normal e TSH elevado.","B":"T4 livre baixo e TSH elevado.","C":"T4 livre baixo e TSH normal.","D":"T4 livre normal e TSH baixo."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-182628","number":"182628","sourceNumber":"182628","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente feminino, 63 anos, submetida à tireoidectomia total há 30 dias por bócio\nmultinodular, refere que ao cantar durante os cultos de sua igreja sua voz \"falha\". Qual a hipótese\ndiagnóstica?","options":{"A":"Lesão do nervo laríngeo superior.","B":"Lesão unilateral do nervo recorrente.","C":"Hipoparatireoidismo.","D":"Hipotireoidismo."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-159062","number":"159062","sourceNumber":"159062","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Não se considera como causa fisiológica da hiperprolactinemia:","options":{"A":"Sono.","B":"Ovulação.","C":"Coito.","D":"Manipulação mamária."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-159126","number":"159126","sourceNumber":"159126","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Para confirmar a principal causa de hipertireoidismo primário com captação aumentada\ne difusa na tireóide de Iodo radioativo na\ncintilografia, devemos solicitar:","options":{"A":"TSH.","B":"Anti TPO.","C":"Anti microssomal.","D":"TRAB."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-159075","number":"159075","sourceNumber":"159075","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"No 1° dia de pós-operatório de uma paciente submetida a tireoidectomia total, ela\napresenta formigamento perioral, parestesias em extremidades e sinais de Trousseau e Chvostek\npositivos. Qual o diagnóstico?","options":{"A":"Hipocalemia.","B":"Lesão do nervo laríngeo recorrente.","C":"Hipocalcemia.","D":"Lesão do nervo laríngeo superior."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-135954","number":"135954","sourceNumber":"135954","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente com aumento doloroso da tireóide, febre, calafrios, sudorese e mal estar geral.\nO exame da tireóide revela uma glândula\nextremamente sensível à palpação, modestamente\naumentada e dura como madeira, além de níveis de T4 livre e VHS aumentados no sangue. A\ncaptação de radioiodo tipicamente é menor do que 2% em 24 horas. Apresenta provavelmente o\ndiagnóstico de:","options":{"A":"Câncer de tireóide;","B":"Tireoidite de Hashimoto;","C":"Tireoidite Subaguda (de Quervain);","D":"Doença de Graves"},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-108659","number":"108659","sourceNumber":"108659","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente veio encaminhada sem queixas, mas com os seguintes exames: T4 e T3 total\nelevados, T3 e T4 livre normais, antitireoglobulina e anti-TPO normais. Qual a sua impressão sobre\na paciente e possível causa?","options":{"A":"Hipertireoidismo/doença de Graves.","B":"Hipotireoidismo/tireoidite Hashimoto.","C":"Eutireoidismo/aumento da TBG.","D":"Hipertireoidismo/uso de medicamentos."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-108749","number":"108749","sourceNumber":"108749","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"No 1º dia de pós-operatório de uma paciente submetida à tireoidectomia total ela\napresenta sensação de formigamento peri-oral e sinais de Trosseau e Chvostek positivos. Qual o\ndiagnóstico?","options":{"A":"Lesão do nervo laringeo recorrente;","B":"Hiponatremia;","C":"Hipocalcemia;","D":"Hipocalemia."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-84541","number":"84541","sourceNumber":"84541","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Neoplasia que deriva das células parafoliculares C da Tireoide. É responsável por\nmenos de 5% de todos os cânceres de\ntireoide. Pode ocorrer como um componente das síndromes\nNEM 2a ou NEM 2b. Qual o câncer de tireoide possui as características descritas acima?","options":{"A":"Carcinoma papilar.","B":"Carcinoma medular.","C":"Carcinoma anaplásico.","D":"Linfoma.","E":"Carcinoma pequenas células."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-66929","number":"66929","sourceNumber":"66929","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"CASO CLÍNICO 3 - Em uma unidade básica de saúde você atende um lactente de seis\nmeses de idade que foi levado à unidade por apresentar uma virose, febre baixa há um dia e coriza\nnasal. Durante o exame foi constatado que a criança se encontrava em bom estado geral, porém\nera hipotônica, sustentou a cabeça com cinco meses e ainda não rolava. Apresentava ainda uma\nfácies, infiltrada, mixedema, pele seca, obstipação e déficit de crescimento que foram notados pela\nmãe desde os dois meses de vida. As vacinas estavam em dia e a criança não realizou a triagem\nneonatal. Qual a MELHOR CONDUTA neste caso?","options":{"A":"Tranquilizar a mãe dizendo que se trata de uma virose e logo a criança melhora;","B":"Realizar orientações com relação ao quadro viral e investigar os demais sintomas com exames\ncomplementares: hemograma, eletrólitos, função renal e função tireoidiana;","C":"Solicitar exames: hemograma, eletrólitos e encaminhar para internação;","D":"Realizar orientações com relação ao quadro viral e encaminhar para avaliação com especialista;"},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-66941","number":"66941","sourceNumber":"66941","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Em uma unidade básica de saúde você atende um lactente de seis meses de idade que\nfoi levado à unidade por apresentar uma virose, febre baixa há um dia e coriza nasal. Durante o\nexame foi constatado que a criança se encontrava em bom estado geral, porém era hipotônica,\nsustentou a cabeça com cinco meses e ainda não rolava. Apresentava ainda uma fácies, infiltrada,\nmixedema, pele seca, obstipação e déficit de crescimento que foram notados pela mãe desde os\ndois meses de vida. As vacinas estavam em dia e a criança não realizou a triagem neonatal. Qual a\nhipótese diagnóstica mais provável?","options":{"A":"Desnutrição proteicocalórica.","B":"Síndrome Nefrótica.","C":"Fenilcetonúria.","D":"Hipotireoidismo congênito."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-66989","number":"66989","sourceNumber":"66989","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente do sexo feminino com hiperglicemia, obesidade, gibosidade, hipertensão\narterial, estrias violáceas, acne, libido\ndiminuída, hipocalemia e fácies de lua \"cheia\". Tem como\nprincipal e mais prevalente etiologia:","options":{"A":"Adenoma de hipófise.","B":"Uso crônico de glicocorticoides.","C":"Adenoma de suprarrenal.","D":"Tumor ectópico produtor de cortisol."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-66995","number":"66995","sourceNumber":"66995","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente com nódulo tireoidiano de 12 mm, níveis diminuídos de TSH e cintilografia\ncom área localizada de hipercaptação de\nsubstância radioativa. A conduta preferencial a ser\ntomada será:","options":{"A":"Levotiroxina;","B":"Observação e US seriados;","C":"PAAF (Punção Aspirativa com Agulha Fina);","D":"Ablação com radioiodo."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-29384","number":"29384","sourceNumber":"29384","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"No 1° dia de pós-operatório de uma paciente submetida a tireoidectomia total ela\napresenta sensação de formigamento peri-oral,\nparestesias em extremidades e sinais de Trosseau\ne Chvostek positivos. Qual a melhor conduta:","options":{"A":"reposição oral de cálcio","B":"reposição parenteral de cálcio","C":"reposição de vitamina D parenteral","D":"reposição de vitamina D por via oral","E":"reposição parenteral de cálcio e vitamina D"},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-372069","number":"372069","sourceNumber":"372069","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente feminina, 32 anos, procura atendimento médico queixando de palpitações há\n60 dias. Relata que se iniciam em repouso,\nsubitamente, sem relação com esforços físicos ou\nalterações emocionais. Nega dor torácica, nega dispneia. Nega perda de consciência. Associa as\ncrises de palpitações com cefaleia importante e aumento da pressão arterial. Tem antecedentes de\ntireoidectomia total com esvaziamento cervical por câncer de tireoide na infância. Exame físico\nrealizado durante uma crise: estável hemodinamicamente, em bom estado geral, sudoreica, corada,\nhidratada, eupneica, anictérica, acianótica, afebril. Bulhas cardíacas rítmicas, taquicárdicas, sem\nsopros. Ausculta pulmonar normal. Abdome sem alterações. Cicatriz cervical prévia sem alterações\ndignas de nota. Ausência de linfonodomegalias atípicas. Pulsos cheios, amplos, simétricos.\n\nAusência de edema de membros inferiores. Foi submetida aos exames abaixo. Assinale a principal\nhipótese diagnóstica.","options":{"A":"Fibrilação atrial de alta resposta.","B":"Neoplasia endócrina múltipla.","C":"Síndrome coronariana aguda.","D":"Transtorno de ansiedade generalizada."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-372048","number":"372048","sourceNumber":"372048","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente feminina, 32 anos, procura atendimento médico queixando de palpitações há\n60 dias. Relata que se iniciam em repouso,\nsubitamente, sem relação com esforços físicos ou\nalterações emocionais. Nega dor torácica, nega dispneia. Nega perda de consciência. Associa as\ncrises de palpitações com cefaleia importante e aumento da pressão arterial. Tem antecedentes de\ntireoidectomia total com esvaziamento cervical por câncer de tireoide na infância. Exame físico\nrealizado durante uma crise: estável hemodinamicamente, em bom estado geral, sudoreica, corada,\nhidratada, eupneica, anictérica, acianótica, afebril. Bulhas cardíacas rítmicas, taquicárdicas, sem\nsopros. Ausculta pulmonar normal. Abdome sem alterações. Cicatriz cervical prévia sem alterações\ndignas de nota. Ausência de linfonodomegalias atípicas. Pulsos cheios, amplos, simétricos.\n\nAusência de edema de membros inferiores. Foi submetida aos exames abaixo. Assinale a opção\nterapêutica mais adequada para o caso.","options":{"A":"Devido a estabilidade hemodinâmica e quadro não agudo, o objetivo é controle da frequência\ncardíaca com alfa-bloqueadores e\nanticoagulação sistêmica.","B":"Solicitar marcadores de injúria miocárdica e trombólise.","C":"Acompanhamento psicoterápico e inibidores da recaptação de serotonina.","D":"Adrenalectomia esquerda."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-343192","number":"343192","sourceNumber":"343192","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Lesões eritematosas, migratórias, com vesículas e bolhas na superfície, evoluindo para\ncura com hiperpigmentação são típicas de\neritema necrolítico. Tal condição tem elevada\nassociação com qual alternativa abaixo?","options":{"A":"Sarcoma estromas gastrointestinal","B":"VIPoma","C":"Insulinoma","D":"Glucagonoma"},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-315205","number":"315205","sourceNumber":"315205","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Os principais sintomas do feocromocitoma são:","options":{"A":"Bradicardia, hipotensão e tremor.","B":"Bradicardia, hipertensão e sonolência.","C":"Taquicardia, hipotensão e sonolência.","D":"Taquicardia, hipertensão e ansiedade.","E":"Bradicardia, hipotensão e ansiedade."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-283732","number":"283732","sourceNumber":"283732","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente, sexo feminino, 45 anos de idade, é encaminhada ao ambulatório de cirurgia\npor apresentar nódulo palpável em região cervical\nanterior. A paciente nega comorbidades ou uso\nde medicações. Ao exame, bom estado geral, presença de nódulo palpável na topografia da\nglândula tireoide, medindo cerca de 1,2 cm no maior diâmetro. Foi realizada uma ultrassonografia\nda região cervical. Caso indicado tratamento cirúrgico para o nódulo, determine, dentre as opções\napresentadas, a principal preocupação do cirurgião nas primeiras 48 horas do pós-operatório.","options":{"A":"Infecção do sítio cirúrgico.","B":"Hipotireoidismo.","C":"Hemorragia.","D":"Hipocalcemia."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-278116","number":"278116","sourceNumber":"278116","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"O sítio mais comum de drenagem venosa da glândula adrenal esquerda é para:","options":{"A":"Veia renal.","B":"Veia gonadal esquerda.","C":"Veia ilíaca comum.","D":"Veia cava inferior."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-249418","number":"249418","sourceNumber":"249418","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente de 26 anos procura pronto-socorro queixando-se de forte mialgia e cãibras\nconstantes que pioraram há 1 semana. Nega febre. Nega trauma. Vem apresentando crises\nhipertensivas recorrentes, já em uso de losartana 100 mg/dia, anlodipino 10 mg/dia e bisoprolol 5\nmg/dia, sem melhora. Após coleta de rotina laboratorial em pronto-socorro foi internada por\nhipocalemia. Submeteu-se à tomografia de abdome abaixo. O provável diagnóstico é:","options":{"A":"Leptospirose.","B":"Paraganglioma.","C":"Adenoma adrenal.","D":"Hipoaldosteronismo ? NEM 1."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-249423","number":"249423","sourceNumber":"249423","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Mulher de 56 anos procura atendimento médico ambulatorial queixando-se de diarreia\nde início há 3 meses, perda de peso,\ncalafrios e tremores sem causa aparente. Nega febre aferida.\nQueixa-se também de baixa acuidade visual. Nega alteração de hábitos rotineiros, alimentares e\nintrodução/suspensão de drogas de uso contínuo. Notou que há aumento de seu pescoço, relatado\ncomo ?inchaço?. Na investigação apresentou tireóide aumentada difusamente à palpação, níveis\nde T4 elevado, TSH suprimido e anticorpos anti-tireoideanos não detectáveis. Ecografia de tireóide\nevidenciou glândula difusamente aumentada. A cintilografia com iodo 131 evidenciou uma área\nautônoma funcional bem localizada e restante da glândula suprimida (não captante). A principal\nhipótese diagnóstica é:","options":{"A":"Doença de Plummer.","B":"Doença de Graves.","C":"Doença de Paget.","D":"Arterite de Takayasu."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-219853","number":"219853","sourceNumber":"219853","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"VBK, 42 anos, sexo masculino, morador de rua, foi submetido a cirurgia para\ntratamento de trauma abdominal por arma\nbranca. À admissão no pronto-socorro apresentava\nhálito etílico e sinais indiscutíveis de alcoolismo crônico. No segundo dia de pós operatório\ncomeçou com tremores acompanhado de taquicardia, rubor facial e hiperreflexia. Evoluiu com\nataxia, confusão mental e oftalmoplegia. Em relação a este caso assinale a alternativa\nINCORRETA:","options":{"A":"Tem indicação de uso contínuo de benzodiazepínico.","B":"Tem risco aumentado de apresentar arritmias e isquemia miocárdica.","C":"Tem risco elevado de apresentar insuficiência suprarrenal, com diminuição dos níveis séricos e\nurinários de catecolaminas","D":"Tinha indicação do uso de tiamina na tentativa de prevenção deste quadro."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-219863","number":"219863","sourceNumber":"219863","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"FSP, sexo masculino, 47 anos, casado, eletricista, queixa-se de cefaleia, sudorese e\npalpitações que surgiram há cerca de 6 meses e que vêm se tornando mais intensas. Informa\nhipertensão arterial de difícil controle com administração de losartana e anlodipino. Ao exame,\napresentava PA de 160 x 100 mmHg e pulso de 96 bpm. Exames laboratoriais de rotina estavam\nnormais. Foi solicitada a dosagem plasmática de metanefrinas livres, que se mostrava elevada.\nProsseguindo na propedêutica foi realizada a dosagem do nível sérico de catecolaminas e seus\nmetabólitos na urina de 24 horas, ambas elevadas. Exames de imagem revelaram nódulo solitário\nem suprarrenal direita (figura abaixo), sendo indicado tratamento cirúrgico. Sobre o perioperatório\nem pacientes nesta situação, assinale alternativa INCORRETA:","options":{"A":"Deve ser realizada biópsia de congelação no peroperatório, pois o critério de malignidade é\nessencialmente histopatológico.","B":"Deve-se administrar bloqueador alfa-adrenérgico logo após estabelecido o diagnóstico.","C":"Na presença de taquicardia persistente pode-se administrar betabloqueadores após bloqueio\nalfa-adrenérgico adequado.","D":"Pode ocorrer hipotensão grave no período pós-operatório devido à vasodilatação arteriolar\nperiférica e aumento da capacitância venosa, após a remoção do tumor."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-219851","number":"219851","sourceNumber":"219851","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"FDR, 61 anos, sexo feminino, secretária aposentada, relata fraqueza muscular, fadiga,\ndepressão, náuseas e poliúria. O exame físico detectou linfonodos aumentados nas cadeias\ncervicais à esquerda. A dosagem de PTHi foi bem elevada, assim como a de cálcio (15 mg/dl).\n\nOcorreu captação significativa à cintilografia com sestamibi na região cervical anterior esquerda. A\nultrassonografia mostrou perda de planos de clivagem entre as paratireoides e a glândula tireoide,\nque estava normal. Em relação à doença desta paciente e seu tratamento cirúrgico, assinale\nalternativa INCORRETA:","options":{"A":"A abordagem cirúrgica deve envolver o tumor em bloco associado a lobectomia da tireoide\nipsilateral e tecidos moles adjacentes com suspeita de invasão.","B":"A biopsia de congelação para confirmação de malignidade não deve ser realizada antes da\nressecção em bloco.","C":"A grande maioria se deve à malignização de um adenoma.","D":"Esta paciente tem maior risco de desenvolver doença óssea ou renal associada do que os\nportadores de adenomas."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-216284","number":"216284","sourceNumber":"216284","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Sobre o Hiperparatiroidismo Primário, é INCORRETO que","options":{"A":"a causa mais comum é a doença uniglandular, denominada Adenoma de Paratireoide.","B":"o Carcinoma de Paratireoide é raro.","C":"nas formas familiares têm maior associação com a NEM tipo 2.","D":"são manifestações clínicas: dor óssea, nefrolitíase, anorexia e depressão."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-216289","number":"216289","sourceNumber":"216289","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"São manifestações clínicas encontradas no Hiperparatiroidismo Primário, EXCETO","options":{"A":"fraqueza muscular.","B":"osteoporose.","C":"coma.","D":"hipervolemia"},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-215257","number":"215257","sourceNumber":"215257","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"São causas de Hipocalcemia, EXCETO:","options":{"A":"Hiperparatiroidismo.","B":"Múltiplas transfusões sanguíneas.","C":"Pancreatite aguda.","D":"Sepse."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-219893","number":"219893","sourceNumber":"219893","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Com relação ao hipotireoidismo é INCORRETO afirmar que:","options":{"A":"A presença de lesão nodular na hipófise, aos métodos de imagem, favorece o diagnóstico de\nhipotireoidismo secundário.","B":"Hipotireoidismo subclínico é definido pelo encontro de concentrações séricas elevadas de TSH,\nna presença de concentrações séricas reduzidas\nde T4 livre e de T3.","C":"Pacientes eutireoidianos com doença sistêmica podem apresentar elevação transitória do TSH\ndurante a recuperação da doença não tireoidiana.","D":"Tireoidite crônica autoimune (tireoidite de Hashimoto) é a causa mais comum de hipotireoidismo\nprimário nas áreas onde não há deficiência de\niodo."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-181412","number":"181412","sourceNumber":"181412","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"A história natural do bócio é crescimento progressivo. Os tratamentos não cirúrgicos\nsão muitas vezes imperfeitos e incompletos. A\nsupressão hormonal tireoidiana tem eficácia variável,\nespecialmente em grandes bócios. Também requer tratamento vitalício porque está associado a\ntaxas de recaída muito altas após a descontinuação, e seus efeitos podem apresentar recaída pelo\nseu descumprimento. Com relação ao bócio, é correto afirmar:","options":{"A":"o bócio subesternal suscita preocupação com a compressão progressiva das estruturas\nvasculares e das vias aéreas e torna a glândula menos acessível à vigilância. Assim, é um\nproblema comum que requer regularmente tratamento cirúrgico.","B":"o iodo radioativo normalmente está indicado na maioria dos casos e não tem relação com outras\ncomplicações, resolvendo o problema de forma diferente do tratamento cirúrgico.","C":"a história natural do bócio é de crescimento com pouco aumento do volume da glândula e,\nsendo assim, sem repercussões locais importantes.","D":"o tratamento cirúrgico não controla efetivamente os sintomas regionais, porém fornece tecido\npara análises histológicas.","E":"a avaliação pré-operatória não necessita de estudo da função da laringe e de imagem da região\ncervical."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-181408","number":"181408","sourceNumber":"181408","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente do sexo feminino refere que há 4 meses apresenta um quadro de fraqueza,\npele seca, cabelos secos e quebradiços, rarefação\ndo terço distal das sobrancelhas, ganho de\npeso, intolerância ao frio e constipação intestinal. Em relação à principal hipótese diagnóstica,\nassinale a alternativa CORRETA.","options":{"A":"TSH suprimido associado à elevação de T4 livre.","B":"A forma secundária representa a maioria dos casos.","C":"A tireoidite de Hashimoto não é uma causa comum em nosso meio.","D":"A hipercolesterolemia e a hipertrigliceridemia são achados clássicos.","E":"Pode ocorrer em qualquer idade, mais comum em mulheres mais jovens."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-182763","number":"182763","sourceNumber":"182763","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"O manejo da crise hipercalcêmica envolve medidas clínicas e cirúrgicas em caráter de\nurgência. São condutas adequadas, EXCETO","options":{"A":"hidratação com cristaloides.","B":"diuréticos de alça..","C":"bifosfonados","D":"bloqueador da angiotensina."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-161379","number":"161379","sourceNumber":"161379","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"O Hiperparatiroidismo é a terceira alteração endócrina mais comum após diabetes e\ndoença tireoidea. Assinale a alternativa CORRETA\nem relação ao metabolismo do cálcio.","options":{"A":"São diagnósticos diferenciais de hipercalcemia-hiperparatiroidismo primário, tireotoxicose,\ninsuficiência adrenal aguda, feocromocitoma, tumores,\nhistoplasmose, sarcoidose, hanseníase,\nmedicamentos como diuréticos tiazídicos e lítio, nutrição parenteral.","B":"Para o manejo da crise hipercalcêmica é indicado hiper-hidratação com solução salina\nhipertônica e diuréticos de alça.","C":"As manifestações clínicas mais comuns do hiperparatiroidismo são adormecimento perioral,\ntremores, ansiedade, confusão mental, alcalose respiratória, tetania, convulsões.","D":"Os bifosfonados apresentam ação rápida (24 à 48h) para reduzir os níveis séricos de cálcio,\nsendo mais efetivas quando associados aos glicorticoides e tem atividade potente contra os\nosteoclastos, em média, por 1 semana."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-161403","number":"161403","sourceNumber":"161403","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"As glândulas adrenais foram primeiramente descritas pelo anatomista italiano\nBartolomeo Eustachi em 1563. Thomas Addison\ndescreveu as características clínicas da\ninsuficiência adrenal primária em 1855, somente quase um século mais tarde os hormônios\nadrenais foram totalmente isolados e caracterizados. Sobre a Insuficiência Adrenal, marque a\nopção CORRETA.","options":{"A":"A Insuficiência Adrenal Primária se apresenta com fraqueza, fadiga, anorexia, náuseas ou\nvômitos, perda de peso, hiperpigmentação, hipotensão, hipernatremia e hipocalemia.","B":"A Insuficiência Adrenal Secundária é um distúrbio relativamente comum, resultante da\ndeficiência do ACTH e muitas vezes causada pela\nretirada de esteroides farmacológicos. Outras\ncausas menos comuns incluem o pan-hipopituitarismo secundário à lesão neoplásica, doenças\ngranulomatosas e hemorragia ou infarto hipofisário.","C":"A Insuficiência Adrenal Aguda, ou crise adrenal, é uma condição potencialmente fatal, os\nachados clínicos incluem dor abdominal,\nchoque, febre, náuseas, hipoglicemia. A Síndrome de\nWaterhouse-Friederichsen é caracterizada pelo infarto adrenal em casos de hemorragia puerperal\ngrave.","D":"O diagnóstico se baseia na concentração de cortisol sérico matinal maior que 15 µg/dL ou\nconcentração salivar de cortisol maior que 5,8 µg/dL."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-161408","number":"161408","sourceNumber":"161408","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"No Hiperaldosteronismo Primário ocorre a liberação desregulada de aldosterona, de\numa ou ambas glândulas adrenais. Indique a\nalternativa INCORRETA.","options":{"A":"O hiperaldosteronismo primário apresenta-se classicamente por hipercalemia e hipertensão\narterial resistente.","B":"As causas mais comuns de hiperaldosteronismo primário são adenomas unilaterais produtores\nde aldosterona e hiperplasia adrenal bilateral.","C":"Uma boa resposta à espironolactona é considerada uma característica preditiva de boa resposta\nao tratamento cirúrgico.","D":"As taxas de cura globais pós-tratamento cirúrgico variam de 75 a 95%."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-161339","number":"161339","sourceNumber":"161339","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Durante a primeira metade do século XX, a taxa de mortalidade perioperatória no\ntratamento do feocromocitoma variava de 26\na 50%. Atualmente, a taxa de mortalidade em centros\nespecializados é de aproximadamente 1%. Em relação aos cuidados operatórios nos pacientes\nportadores de feocromocitoma, assinale a alternativa INCORRETA:","options":{"A":"As alterações hemodinâmicas adversas mais comuns são hipertensão intraoperatória e\nhipotensão pós-operatória.","B":"Entre os princípios dos cuidados perioperatórios está o bloqueio alfa-adrenérgico por pelo menos\nduas semanas.","C":"Os betabloqueadores podem ser utilizados como monoterapia para os pacientes com taquicardia\npersistente.","D":"A expansão do volume pré-operatório com fluidos isotônicos é reduzida significativamente\nquando o bloqueio alfa pré-operatório é atingido."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-161298","number":"161298","sourceNumber":"161298","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Sobre as alterações nos níveis de hormônios tireoidianos na doença aguda grave,\nassinale a alternativa INCORRETA.","options":{"A":"Na fase aguda da doença, os níveis de T3 e de T3 livre diminuem as concentrações\nextremamente baixas.","B":"A diminuição nos níveis circulantes de T3 resulta de um aumento na conversão de T3 para T4,\nao passo que a depuração do T3 permanece preservada.","C":"Em contraste com os baixos níveis de T3, os níveis de rT3 aumentam na fase aguda da doença\ndevido à redução na depuração e a um aumento na atividade da via deiodinase iodotironina tipo III.","D":"Durante a fase tardia da doença grave, a secreção hipofisária de TSH está diminuída, com o\ndeclínio concomitante das concentrações séricas de T4."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-161334","number":"161334","sourceNumber":"161334","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Os efeitos adversos dos corticosteroides surgem por uso prolongado e/ou doses\nelevadas, ou seja, são doses dependentes. Entre os principais efeitos adversos destacam-se,\nEXCETO:","options":{"A":"o ganho de peso.","B":"a hipotensão arterial.","C":"a osteoporose.","D":"a miopatia aguda."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-161376","number":"161376","sourceNumber":"161376","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"A dexametasona tem potente atividade glicocorticoide com mínima a nenhuma\natividade mineralocorticoide. Além disso, ela é\nresponsável por todas as ações a seguir, com\nEXCEÇÃO de:","options":{"A":"estabilizar membranas celulares e lisossomais.","B":"aumentar a síntese de surfactante.","C":"Melhorar a imunidade em altas doses.","D":"Inibir prostaglandinas e citocinas pró-inflamatórias."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-134837","number":"134837","sourceNumber":"134837","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Durante tratamento de tireotoxicose, qual medicação poderá ser utilizada para diminuir\na conversão de T4 a T3 na periferia?","options":{"A":"IECA.","B":"Propranolol.","C":"Anlodipina.","D":"Furosemida."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-109972","number":"109972","sourceNumber":"109972","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Em qual dos tipos de carcinomas citados abaixo, o carcinoma papilífero pode se\ntransformar?","options":{"A":"Medular.","B":"Linfocítico.","C":"Hürtle.","D":"Anaplásico."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-86802","number":"86802","sourceNumber":"86802","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"São causas de hipocalcemia, exceto:","options":{"A":"Sepse;","B":"Pós-operatório;","C":"Pancreatite aguda;","D":"Hiperparatireoidismo;","E":"Lise tumoral."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-86682","number":"86682","sourceNumber":"86682","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Analise as afirmativas abaixo e marque a alternativa que melhor define o quadro de\ncrise tireotóxica. I ? TSH suprimido, T4 livre\nbastante elevado, taquicardia, hipertensão, dor\nabdominal e sudorese excessiva. II ? TSH elevado, T4 livre diminuído, taquiarritmia, febre,\ntaquicardia, e febre. III ? disfunção termorregulatória grave, alteração de estado mental,\nevidências\nde disfunção de múltiplos órgãos, crise adrenérgica, hipermotilidade intestinal.","options":{"A":"Somente afirmativa I está correta.","B":"Somente afirmativa II está correta.","C":"Somente afirmativa II e III estão corretas.","D":"Somente afirmativa III está correta.","E":"Todas as afirmativas estão erradas."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-86861","number":"86861","sourceNumber":"86861","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente 57 anos, sexo masculino, realizou uma glicemia de jejum em dois dias\ndiferentes com resultados de 101 mg/dl e 100 mg/dl. Foi solicitado um TOTG (Teste Oral de\nTolerância à Glicose), resultado 196 mg/dl. Conclui-se que: I. Intolerante à glicose; II. Diabetes\nMellitus; III. Com a glicemia de 101 mg/dl, poderíamos afirmar que ele é intolerante à glicose.","options":{"A":"Apenas alternativa I está correta;","B":"Apenas Alternativa II está correta;","C":"Apenas Alternativa III está correta;","D":"Todas alternativas estão corretas;","E":"Todas alternativas estão erradas."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-86681","number":"86681","sourceNumber":"86681","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente do sexo masculino apresenta nódulo tireóideo único, de aproximadamente 2\ncm, acompanhado por adenomegalia cervical, ipsilateral. Calcitonina normal. Qual dos diagnósticos\nabaixo é o mais compatível?","options":{"A":"Adenocarcinoma papilífero.","B":"Adenocarcinoma folicular.","C":"Adenocarcinoma medular.","D":"Adenocarcinoma anaplásico.","E":"Metástase em tireoide."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-158411","number":"158411","sourceNumber":"158411","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Homem de 43 anos vem com queixa de anorexia, náusea, perda de 8 kg e fadiga\nintensa há 2 anos. Refere tratamento para\ntuberculose pulmonar há 5 anos com esquema tríplice\npor 6 meses. Exame clínico: letárgico; PA = 90 x 50 mmHg; FC = 98 bpm; peso = 63 kg (IMC = 21\nkg/m²) com hiperpigmentação cutânea e em mucosa oral. Exames laboratoriais: hemoglobina =\n10,2 g/dl; sódio = 129 mEq/L; potássio = 5,7 mEq/L; creatinina = 0,9 mg/dl; ureia = 60 mg/dl;\nalbumina = 3,1 g/dl. Qual a principal hipótese diagnóstica?","options":{"A":"Hipotireoidismo.","B":"Síndrome de Cushing.","C":"Insuficiência Adrenal.","D":"Tuberculose miliar.","E":"Paracoccidioidomicose."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-158437","number":"158437","sourceNumber":"158437","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Um recém-nascido foi convocado ao serviço médico por apresentar teste do pezinho\nalterado. O exame mostra TSH = 30 ?g/ml. Qual a conduta indicada?","options":{"A":"Iniciar imediatamente tratamento de reposição hormonal com tiroxina.","B":"Repetir teste do pezinho e reavaliar clinicamente em 1 semana.","C":"Dosar TSH sérico e reavaliar clinicamente em 1 semana.","D":"Dosar T4 sérico e reavaliar clinicamente em 1 semana.","E":"Dosar TSH sérico e iniciar tratamento com tiroxina enquanto aguarda o resultado."},"answer":"E","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-362478","number":"362478","sourceNumber":"362478","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente de 34 anos, sexo feminino, apresentou-se ao Departamento de Emergência\ncom confusão mental, letargia e episódios de\nsíncope ao permanecer de pé. Ela também teve\nepisódios de vômitos ao longo do dia. Glicemia capilar mensurada na entrada do Hospital era de\n55mg/dl, porém seu estado mental não melhorou após administração de glicose hipertônica EV\n(endovenosa) em bolus. Recentemente ficou sem usar certas medicações das quais fazia uso\ncrônico e não conseguia lembrar de nada da sua história patológica pregressa. Pa: 80/40mmhg\napesar do uso de 2 litros de solução isotônica EV, Fc: 80bpm, Fr: 12 ipm, Tax: 38,2ºc e saturação\nde O2 de 99% em ar ambiente. Sem rigidez de nuca. A pele das palmas das mãos e da mucosa\nbucal se mostravam escurecidas. Laboratório: Na+:128mmol/l, K+:5,8mmol/l, Cl:96mmol/l,\nBicarbonato: 20mmol/l, Glicose: 120mg/dl, Ca++: 10,4mg/dl, U: 38mg/dl, Cr: 1mg/dl. A análise de\nlíquido cefalorraquidiano após punção lombar revelou: WBC:03/mm³ (<5), RBC: 0/mm³ (0),\nProteínas: 30mg/dl (15- 45) e Glicose:75mg/dl (40-80). Qual a terapêutica poderia ser iniciada nesta\npaciente precocemente?","options":{"A":"Difenidramina.","B":"Hidrocortisona.","C":"Vancomicina.","D":"Propiltiouracil."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-362477","number":"362477","sourceNumber":"362477","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente, sexo feminino, 36 anos de idade, recebeu diagnóstico de Doença de Graves\nhá dois anos. Na ocasião, apresentava\norbitopatia de Graves, proptose unilateral, bócio difuso,\ntaquicardia e tremor de extremidades. O laboratório revelava TSH suprimido e T4 livre três vezes o\nlimite superior da normalidade. Foi optado por iniciar tratamento com metimazol. Durante os últimos\n18 meses, a paciente vem em desmame da tionamida e, atualmente, está em uso de 5 mg/dia. Os\núltimos exames demonstraram função tireoidiana normal e TRAb 12,0 UI/L (VR: < 1,75). US de\ntireoide: glândula heterogênea, com volume total de 32,7 mL. Tabagista há oito anos; nega etilismo.\nAo exame: eupneica, FC 75 bpm e PA: 120 x 80 mmHg. Tireoide: bócio difuso. Ausculta cardíaca e\npulmonar sem alterações. Olhos: presença de orbitopatia de Graves, sem sinais de atividade,\nproptose unilateral. Em relação ao caso clínico, assinale a alternativa CORRETA:","options":{"A":"As tionamidas inibem a captação de iodo pela tireoide e afetam a liberação dos hormônios já\nsintetizados e estocados dentro da glândula.","B":"A paciente apresenta TRAb em títulos baixos, portanto, o uso do metimazol deve ser suspenso\ndevido à alta possibilidade de cura.","C":"A realização da tireoidectomia total levaria à resolução da doença de base, contribuindo para\nredução dos níveis do TRAb.","D":"A exoftalmia na Doença de Graves é unilateral em 10% dos casos e no contexto de um quadro\nclássico de hipertireoidismo torna- se desnecessário o diagnóstico diferencial com outras\npatologias."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-362476","number":"362476","sourceNumber":"362476","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Mulher, 55 anos de idade, em amenorreia há 2 anos, foi encaminhada pelo clínico ao\nambulatório de endocrinologia por alteração da função tireoidiana e perda de campo visual.\n\nApresentava TSH 0,85 mUI/mL (VR: 0,4 a 4,0) e T4 livre 0,55 ng/dL (VR: 0,9 a 1,8). Foram\nsolicitados então os seguintes exames: T4\nlivre: 0,72 ng/dL TSH: 0,94 mUI/mL; FSH: 2,5 mUI/mL\n(VR: 3,6 a 16,6); LH: 2,0 mUI/mL (VR: 1,1 a 11,1); Cortisol: 7,0 mcg/dL (VR: 5,0 a 25); ACTH: 13,1\n\npg/mL (VR: < 46); IGF-1: 62 ng/mL (VR: 83 a 241); Prolactina: 88 ng/dL (VR: 5 a 25). Prosseguindo\na investigação, a ressonância magnética da sela\ntúrcica evidenciou lesão hipofisária de 4,0 x 2,5 x\n2,9 cm em região selar compatível com adenoma hipofisário. Assinale a alternativa CORRETA\nsobre o caso acima:","options":{"A":"A dosagem de prolactina diluída é obrigatória neste caso para a exclusão do efeito gancho.","B":"Trata-se de um caso de amenorreia secundária, quando há ausência de menstruação por 4\nmeses consecutivos ou mais em mulheres que já tenham menstruado previamente.","C":"A paciente apresenta macroprolactinemia e deve ser encaminhada para tratamento cirúrgico.","D":"Podemos excluir o diagnóstico de hipotireoidismo devido aos níveis normais de TSH."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-327238","number":"327238","sourceNumber":"327238","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"A hiperprolactinemia pode ser resultado de causas fisiológicas, farmacológicas e\npatológicas. Dessa forma, as alternativas a seguir figuram como possíveis causas de\nhiperprolactinemia, EXCETO:","options":{"A":"Hipertireoidismo","B":"Cirrose hepática","C":"Herpes zoster acometendo parede torácica","D":"Uso de domperidona e metoclopramida"},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-327293","number":"327293","sourceNumber":"327293","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Recém-nascido apresenta ambiguidade genital caracterizada por hipospádia e\ncriptorquidia. O nível sérico de 17 hidroxiprogesterona encontra-se elevado. Qual a principal\ncomplicação?","options":{"A":"Infecção urinaria","B":"Esterilidade","C":"Distúrbio hidroeletrolítico Sódio e Potássio","D":"Malformação renal"},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-298200","number":"298200","sourceNumber":"298200","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Sobre o tratamento do hipertireoidismo, é CORRETO afirmar:","options":{"A":"O metimazol age inibindo a liberação de hormônios tireoidianos já sintetizados e estocados na\ntireoide; com isso, seu efeito terapêutico é mais rápido que o propiltiouracil, o que faz com que\nseja\na droga de escolha para tratamento do hipertireoidismo.","B":"No paciente em uso de metimazol que evolui com agranulocitose, a recomendação é a troca\nimediata da medicação pelo propiltiouracil.","C":"Na paciente com doença de Graves que engravida, a recomendação é suspender a tionamida\nem uso e submeter a paciente a terapia com\nI131, com o intuito de promover a remissão da doença\nde forma mais precoce possível.","D":"Por ser administrado por via oral, o iodo radioativo é considerado um método de fácil execução,\npodendo até mesmo ser empregado como\nterapia inicial nos pacientes com hipertireoidismo."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-252210","number":"252210","sourceNumber":"252210","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Em relação ao tratamento da doença de Graves, assinale a alternativa INCORRETA:","options":{"A":"Nos casos de doença de Graves associada a nódulos suspeitos, a tireoidectomia deve ser\nindicada como tratamento.","B":"A agranulocitose é um raro efeito colateral e está relacionada tanto ao propiltiouracil quanto ao\nmetimazol.","C":"As tionamidas utilizadas no tratamento da doença de Graves podem apresentar reações\nalérgicas de forma cruzada.","D":"No tratamento da doença de Graves, a indicação para o emprego terapêutico do iodo 131 deve\nsempre ser precedido do preparo prévio do paciente com betabloqueador e tionamidas."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-252213","number":"252213","sourceNumber":"252213","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"São considerados sinais e sintomas devido as alterações cardiovasculares do\nhipertireoidismo:","options":{"A":"Palpitações e dor torácica tipicamente muscular.","B":"Dispnéia e edema periférico.","C":"Bradicardia e dispneia.","D":"Bradicardia e hipertensão diastólica."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-252242","number":"252242","sourceNumber":"252242","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Qual tumor descrito por Verner e Morrison em uma síndrome caracterizada por diarreia\nliquida, hipocalemia e tumor em pâncreas?","options":{"A":"Insulinoma","B":"Somatostatinoma","C":"Glucagonoma","D":"Vipoma"},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-208453","number":"208453","sourceNumber":"208453","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Em relação ao hipertireoidismo, assinale a resposta INCORRETA.","options":{"A":"A investigação do hipertireoidismo em idosos que apresentam Fibrilação Atrial (FA) sempre se\nfaz necessária ao diagnóstico diferencial, pelo fato de bócios nodulares tóxicos ocorrerem com\nrelativa frequência nessa faixa etária da população.","B":"A tireoidectomia total na doença de Graves é reservada aos casos que se associam a nódulos\nda tireoide ou na presença de exoftalmia\nacentuada.","C":"Na grávida com hipertireoidismo, a decisão pela droga de escolha sempre recai pelo metimazol,\nindependentemente do período gestacional, pois é a droga mais segura para a condição, pelo fato\nde não transpor a barreira transplacentária.","D":"Na exoftalmia decorrente da doença de Graves, são encontrados infiltrados de\nglicosaminoglicanos ou mucopolissacarídeos na\nmusculatura extrínseca do olho devido a ativação\nde fibroblastos, e consequente espessamento dessa musculatura."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-176065","number":"176065","sourceNumber":"176065","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Feminino, 43 anos, submetida a tireoidectomia total devido bócio multinodular atóxico,\nevoluindo no pós-operatório imediato com astenia, cãibras musculares, parestesias, mialgia. Qual a\nprovável causa do quadro clínico apresentado?","options":{"A":"Hiperparatireoidismo pós-cirúrgico.","B":"Hipoparatireoidismo pós-cirúrgico.","C":"Hipotireoidismo pós-cirúrgico.","D":"Hipertireoidismo pós-cirúrgico."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-176082","number":"176082","sourceNumber":"176082","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Mãe relata que criança do sexo feminino tem 6 meses de idade e está em sua primeira\nconsulta com pediatra, nunca realizou exames e vacinas, nasceu com peso e altura normais, porém\nficou ??amarelinho?? por quase dois meses, dificuldade para alimentar, sonolência e engasgos\ndurante alimentação já presente no primeiro mês de vida. Ao exame físico: língua espessa,\nhipotonia, hérnia umbilical, bradicardia, pele seca, atraso no desenvolvimento neuropsicomotor, não\nsustenta a cabeça, pega objetos, e não sorri quando estimulado. Diante deste caso, qual a\npatologia a ser investigada?","options":{"A":"Infecção congênita.","B":"Fenilcetonúria.","C":"Hipotireoidismo.","D":"Doença de xarope de bordo (MSUD)."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-151950","number":"151950","sourceNumber":"151950","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente de 57 anos foi internada para investigação de ascite referida há mais de seis\nmeses. Após avaliação clínica e depois de vários exames complementares, foram evidenciadas\nalterações nos exames de tireoide, com elevação de TSH e redução nos níveis de T4 e T3,\ncaracterizando ascite mixedematosa, manifestação incomum de apresentação clínica. Das\nmanifestações clínicas descritas abaixo, assinale a que não está ligada ao hipotireoidismo:","options":{"A":"Bradicardia, derrame pericárdico e redução no débito cardíaco.","B":"Anorexia, absorção intestinal aumentada devido à constipação intestinal.","C":"Hiporreflexia profunda, parestesias e alopecia.","D":"Ataxia cerebelar, depressão e apneia do sono."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-151957","number":"151957","sourceNumber":"151957","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Adolescente de 14 anos, sexo feminino, procura o Ambulatório Araújo Lima com história\nde perda de peso, apetite voraz, tremor dos\ndedos, aceleração na velocidade do crescimento,\nchora com facilidade devido labilidade emocional, tem sono agitado, os trabalhos escolares estão\nprejudicados pelo deficit de atenção e pouco sono. Ao exame físico, apresenta exoftalmia leve,\nretração de pálpebras, acuidade visual diminuída, pele lisa ruborizada, suor excessivo, taquicardia\ne palpitações. O diagnóstico provável:","options":{"A":"Transtorno de conversão.","B":"Hipertireoidismo.","C":"Tumor cerebral.","D":"Bulimia."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-152010","number":"152010","sourceNumber":"152010","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Recém-nascido, no 10º dia de vida, sexo masculino, nascido de parto a termo, pesando\n\n= 3.500 g, evolui com perda progressiva de peso, vômito, desidratação, fraqueza, hipotensão,\nhipoglicemia, hiponatremia, hipercalemia e\nhemograma sem alterações. Ausculta pulmonar:\nmurmúrio vesicular fisiológico, sem ruídos adventícios; FR = 48 irpm. Ausculta cardíaca: RCR 2T\nBNF. Abdome sem visceromegalia. O diagnóstico provável é:","options":{"A":"Hiperplasia adrenal congênita.","B":"Estenose hipertrófica do piloro.","C":"Refluxo gastroesofágico.","D":"Sepse neonatal."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-129769","number":"129769","sourceNumber":"129769","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"No hiperparatireoidismo primário encontramos:","options":{"A":"Níveis aumentados de cálcio associado a níveis aumentados ou inapropriadamente normais do\nhormônio paratireóideo (PTH).","B":"Níveis aumentados de hormônio paratireóideo (PTH) e níveis baixos de cálcio sérico.","C":"Níveis baixos de hormônio paratireóideo (PTH) associado a níveis baixos de cálcio.","D":"Níveis baixos de hormônio paratireóideo (PTH) associado a níveis elevados de cálcio sérico."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-103836","number":"103836","sourceNumber":"103836","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente do sexo masculino, 26 anos de idade com diagnóstico de LES (Lupus\nEritematoso Sistêmico) há 10 anos. Encontra-se\ncom doença controlada, usando prednisona em\nbaixas doses (7,5 mg/dia) e cloroquina (150 mg/dia). Tem história de litíase renal e precisa fazer\nreposição de cálcio para prevenção de osteoporose. Qual o cálcio deveria ser prescrito?","options":{"A":"Colecalciferol","B":"Citrato de cálcio","C":"Carbonato de cálcio","D":"Alendronato de sódio"},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-80958","number":"80958","sourceNumber":"80958","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Doença de Graves, a forma mais comum de hipertireoidismo, quando acomete\nmulheres grávidas apresenta características e\ncuidados específicos. Assinale abaixo a resposta\nINCORRETA:","options":{"A":"A crise tireotóxica, decorrente do hipertireoidismo na gravidez, exige cuidados intensivos devido\nà extrema gravidade.","B":"O Propranolol pode ser usado, porém em baixas doses e por um curto período de tempo, para\nevitar efeitos prolongados sobre o feto, como bradicardia ou retardo de crescimento intrauterino.","C":"Propiltiouracil não deve ser indicado para o tratamento no primeiro trimestre, devido ao risco de\nembriopatia acentuada.","D":"A administração de Iodo 131, como forma definitiva de tratamento do hipertireoidismo, é\ncontraindicada durante a gravidez.","E":"hipertireoidismo materno não tratado pode causar prematuridade, baixo peso para a idade\ngestacional, retardo do crescimento intrauterino e aumento da morbimortalidade perinatal."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-61554","number":"61554","sourceNumber":"61554","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"No Hipertireoidismo, assinale a alternativa ERRADA:","options":{"A":"A arritmia frequentemente encontrada é a Fibrilação Atrial.","B":"A terapia com Iodo 131 pode ser indicada na Doença de Graves e nos Adenomas tóxicos.","C":"Na presença de TSH suprimido e nódulo tireoidiano solitário, a cintilografia da tireoide deve ser\nefetuada.","D":"O Metimazol deve ser a droga de escolha no tratamento do hipertireoidismo grave ou\ntempestade tireoidiana, visto que em altas doses inibe a conversão de T4 para T3.","E":"Algumas alterações hematológicas e químicas são frequentes, como a leucopenia,\nhipercalciúria, hipercalcemia, hiperbilirrubinemia e redução do colesterol total."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-49805","number":"49805","sourceNumber":"49805","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Taquicardia, arritmia, sudorese, pele quente, intolerância ao calor, emagrecimento,\nexoftalmia são achados frequentes em:","options":{"A":"Feocromocitoma;","B":"Sindrome de Sheehan;","C":"Ovários policísticos;","D":"Klinefelter;","E":"Basedow-Graves."},"answer":"E","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-46695","number":"46695","sourceNumber":"46695","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Uma mulher de 40 anos de idade, não fumante e sem histórico familiar de doenças\ncoronarianas, submeteu-se a exames de rotina que revelaram os seguintes resultados: Colesterol\ntotal = 290 mg/dl; Colesterol LDL = 210 mg/dl; Colesterol HDL = 45 mg/dl; Triglicerideos = 160\nmg/dl e Glicemia de jejum = 98 mg/dl. A paciente, cujo Índice de Massa Corpórea (IMC) era de 26\nkg/cm², foi orientada a seguir uma dieta hipolipídica e a aumentar sua atividade física. Três meses\napós, seu IMC era de 24,8 kg/cm² e novos exames mostraram: Colesterol total = 253 mg/dl;\nColesterol LDL = 180 mg/dl; Colesterol HDL = 45 mg/dl e Triglicerídeos = 140 mg/dl. Foi também\navaliada a função tireoidiana que mostra um TSH = 16 mcUI/ml (VN = 0,3-5) e T4 livre = 0,6 ng/dl\n(VN = 0,8-1,9). Qual a melhor conduta para este caso?","options":{"A":"Iniciar fenofibrato ou ciprofibrato.","B":"Iniciar L-tiroxina.","C":"Iniciar L-tiroxina + uma estatina.","D":"Apenas insistir nas medidas não farmacológicas.","E":"Iniciar uma estatina."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-46682","number":"46682","sourceNumber":"46682","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Recém-nascido apresenta genitália ambígua, destaca-se a possibilidade de tratar-se de\numa menina virilizada, devido hipoplasia\ncongênita de suprarrenal. O nível sério de 17 - hidróxido\nprogesterona encontra-se elevado. Neste caso, espera-se como principal complicação:","options":{"A":"Esterilidade","B":"Desidratação","C":"Tumor hipófise","D":"Infecção urinária","E":"Malformação renal"},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-26443","number":"26443","sourceNumber":"26443","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Assinale a alternativa CORRETA:","options":{"A":"As drogas antitireoidianas (propiltiouracil e metimazol), agem inibindo a tireoperoxidase\ntireoidiana e a conversão de T4 em T3","B":"A agranulocitose é efeito colateral muito comum das drogas antitireoidianas e ocorre em cerca\nde 20% dos pacientes que a utilizam","C":"O diagnóstico de hipertireoidismo subclínico é confirmado pela presença de concentrações\nbaixas ou suprimidas de TSH associada a valores\nnormais dos hormônios tireoidianos","D":"Caso o paciente apresente agranulocitose com uma das drogas antitireoidianas, esta deverá ser\ntrocada pela outra","E":"Na gestação a droga de escolha é o metimazol"},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-26597","number":"26597","sourceNumber":"26597","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Todas as patologias abaixo são causas de tireotoxicose, exceto:","options":{"A":"Tireoide de Riedel","B":"Tireoide subaguda","C":"Doença trofoblástica","D":"Ingesta excessiva de hormônio tireoidiano","E":"Doença de Basedow-Graves"},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-26599","number":"26599","sourceNumber":"26599","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"No hiperparatireoidismo primário, qual o sítio esquelético que usualmente exibe maior\nperda mineral?","options":{"A":"Fêmur total","B":"Porção distal do rádio","C":"Colo do fêmur","D":"Terço proximal do rádio","E":"Coluna vertebral"},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-26620","number":"26620","sourceNumber":"26620","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Qual hormônio NÃO é liberado pelo hipotálamo?","options":{"A":"FSH","B":"GnRH","C":"CRH","D":"GHRH","E":"TRH"},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-7469","number":"7469","sourceNumber":"7469","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Entre as alterações laboratoriais abaixo, assinale aquela que NÂO ocorre em\nportadores de hipotireoidismo primário:","options":{"A":"TSH elevado.","B":"TSH baixo.","C":"Anticorpo anti-tireoperoxidase positivo.","D":"T4 livre baixo.","E":"Anemia."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-10000","number":"10000","sourceNumber":"10000","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Criança 2 anos de idade, com retardo psicomotor (não anda, fala mal), prisão de ventre\nconstante, hérnia inguinal, fácies inexpressivas, com protrusão de língua, cabelos secos e\nquebradiços, pele seca e áspera.","options":{"A":"Hipotireoidismo congênito avançado.","B":"Hipotireoidismo adquirido com bócio.","C":"Hipotireoidismo congênito.","D":"Hipotireoidismo sem bócio.","E":"Hipotireoidismo juvenil."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-9979","number":"9979","sourceNumber":"9979","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Qual dos tumores da adrenal se apresenta clinicamente por: cefaleia, sudorese,\npalpitações e hipertensão arterial de\ndifícil controle assim como estudo de imagem por Ressonância\nMagnética do Abdome demonstrando nódulo tumoral com hipersinal em T2?","options":{"A":"Feocromocitoma.","B":"Adenoma da adrenal.","C":"Tumor metastático para adrenal.","D":"Tumor adrenal produtor de cortisol.","E":"Tumor de adrenal produtor de aldosterona."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-7457","number":"7457","sourceNumber":"7457","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"A fadiga vocal e a perda do timbre da voz após uma tireoidectomia levam à suspeição\nde:","options":{"A":"traqueomalácia.","B":"lesão do nervo recurrente.","C":"secção da cartilagem cricoide.","D":"lesão do nervo laríngeo superior.","E":"pólipo de cordas vocais associado."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-10017","number":"10017","sourceNumber":"10017","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Num paciente com sintomas de tireotoxicose, resultante de uma tireoidite sub-aguda,\nqual das medidas terapêuticas estaria indicada?","options":{"A":"Tireoidectomia sub-total.","B":"Propranolol 20-40mg, 2-3X/ dia.","C":"Propiltíouracil, 100-200mg, 2-3X/ dia.","D":"Terapia com Iodo radioativo.","E":"Solução saturada de iodeto de potássio, 5 gts, 3X/ dia."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-354406","number":"354406","sourceNumber":"354406","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Mulher, 45 anos de idade, apresenta-se na UBS com queixas de fadiga, ganho de peso\nnão intencional, constipação e pele seca, há 3\nmeses. Refere sentir-se mais sensível ao frio nos\núltimos meses. Ao exame físico, observa-se FC: 50bpm, PA: 140x100mmHg. A palpação da\ntireoide revela aumento difuso da glândula, com textura granular e ausência de nódulos palpáveis.\nDemais exames segmentares sem alterações. Diante do quadro clínico, indique os níveis\nhormonais, mais provavelmente, encontrados neste caso:","options":{"A":"T4 livre baixo e TSH baixo.","B":"TSH elevado e T4 livre baixo.","C":"T3 reverso elevado e TSH baixo.","D":"TSH baixo e T3 total baixo."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-354407","number":"354407","sourceNumber":"354407","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Mulher, 45 anos de idade, apresenta-se na UBS com queixas de fadiga, ganho de peso\nnão intencional, constipação e pele seca, há 3\nmeses. Refere sentir-se mais sensível ao frio nos\núltimos meses. Ao exame físico, observa-se FC: 50bpm, PA: 140x100mmHg. A palpação da\ntireoide revela aumento difuso da glândula, com textura granular e ausência de nódulos palpáveis.\nDemais exames segmentares sem alterações. Indique o exame complementar mais adequado para\no diagnóstico etiológico do quadro de base:","options":{"A":"Dosagem de anticorpos antiperoxidase tireoidiana (anti-TPO).","B":"Teste de supressão com levotiroxina.","C":"Ultrassonografia de tireoide.","D":"Dosagem de T3 total."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-354408","number":"354408","sourceNumber":"354408","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Mulher, 45 anos de idade, apresenta-se na UBS com queixas de fadiga, ganho de peso\nnão intencional, constipação e pele seca, há 3\nmeses. Refere sentir-se mais sensível ao frio nos\núltimos meses. Ao exame físico, observa-se FC: 50bpm, PA: 140x100mmHg. A palpação da\ntireoide revela aumento difuso da glândula, com textura granular e ausência de nódulos palpáveis.\nDemais exames segmentares sem alterações. Indique a conduta terapêutica inicial mais apropriada\npara esta paciente:","options":{"A":"Iniciar levotiroxina em dose padrão e avaliar com exames laboratoriais após 6 semanas.","B":"Encaminhar para avaliação endocrinológica antes de iniciar qualquer intervenção terapêutica.","C":"Administrar levotiroxina em dose agressiva para normalizar os níveis hormonais em até uma\nsemana.","D":"Realizar biópsia da tireoide para confirmar o diagnóstico antes de iniciar o tratamento."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-62812","number":"62812","sourceNumber":"62812","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente, sexo masculino, 25 anos de idade, com história de perda de peso, astenia e\nquadro depressivo, há cerca de 3 anos. Admitido em hospital com quadro de vômitos e dor\nabdominal. Familiares relatam quadro de alteração do comportamento e fraqueza de membros\ninferiores (paraparesia) associado à disfunção esfincteriana. Avaliação laboratorial evidenciou\nglicose: 65 mg/dl; sódio: 124 mEq/L; potássio: 5,8 mEq/L. A principal suspeita diagnóstica para\njustificar a admissão hospitalar é:","options":{"A":"Síndrome carcinoide.","B":"Porfiria intermitente aguda.","C":"HIV agudo.","D":"Hipertireoidismo.","E":"Insuficiência adrenal."},"answer":"E","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-62817","number":"62817","sourceNumber":"62817","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente, sexo masculino, 25 anos de idade, com história de perda de peso, astenia e\nquadro depressivo, há cerca de três anos. Admitido em hospital com quadro de vômitos e dor\nabdominal. Familiares relatam quadro de alteração do comportamento e fraqueza de membros\ninferiores (paraparesia) associado à disfunção esfincteriana. Avaliação laboratorial evidenciou\nglicose: 65 mg/dl, sódio: 124 mEq/L, potássio: 5,8 mEq/L. A principal suspeita diagnóstica para\njustificar a admissão hospitalar é:","options":{"A":"adrenoleucodistrofia.","B":"infecção do sistema nervoso central.","C":"mielite transversa.","D":"compressão medular.","E":"neuropatia periférica."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-35003","number":"35003","sourceNumber":"35003","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente, sexo feminino, 45 anos de idade, refere episódios de inquietação,\nnervosismo, tremor, palpitações, taquicardia,\ntranspiração, sensação de calor, palidez, irritabilidade,\nfraqueza, confusão mental, amnésia e tontura há seis meses. Realizou ultrassonografia abdominal\nque foi normal. Tomografia axial computadorizada de abdome revelou nódulo sólido de 1,8 cm na\ncabeça pancreática. Nega história familiar de neoplasias. Sobre a principal suspeita diagnóstica, é\nincorreto afirmar:","options":{"A":"É representada clinicamente pela tríade de Whipple.","B":"O método laboratorial diagnóstico de escolha é a dosagem dos níveis de peptídeo C no plasma.","C":"O exame de imagem pré-operatório de escolha é a ultrassonografia endoscópica.","D":"O método diagnóstico mais sensível isoladamente é a ultrassonografia intraoperatória.","E":"É o tumor neuroendócrino pancreático mais comum."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-35006","number":"35006","sourceNumber":"35006","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente, sexo feminino, 45 anos de idade, refere episódios de inquietação,\nnervosismo, tremor, palpitações, taquicardia,\ntranspiração, sensação de calor, palidez, irritabilidade,\nfraqueza, confusão mental, amnésia e tontura há seis meses. Realizou ultrassonografia abdominal,\nque foi normal. Tomografia axial computadorizada de abdome revelou nódulo sólido de 1,8 cm na\ncabeça pancreática. Nega história familiar de neoplasias. O paciente foi levado à laparotomia\nexploradora, que evidenciou nódulo subcapsular na cabeça pancreática. Realizando biópsia de\ncongelação, sem evidências de malignidade na lesão. Diante de tais achados, o tratamento de\nescolha é:","options":{"A":"gastroduodenopancreatectomia.","B":"cirurgia de Whipple modificada por Longmire-Traverso.","C":"enucleação do nódulo.","D":"pancreatectomia total.","E":"expectante, visto que se trata de lesão benigna."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-27476","number":"27476","sourceNumber":"27476","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente, 17 anos de idade, vem à consulta de rotina, quando se evidencia o aumento\nda tireoide. O bócio é de volume moderado,\nsuperfície irregular, indolor. A punção aspirativa por\nagulha fina (PAAF) revelou a presença de infiltrado inflamatório linfocitário e hiperplasia de\nfolículos. O diagnóstico mais provável é:","options":{"A":"disormonogêneses.","B":"tireoidite de Hashimoto.","C":"carcinoma anaplásico.","D":"bócio endêmico.","E":"adenopatia cervical."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-11138","number":"11138","sourceNumber":"11138","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Com o uso prolongado de corticosteroides, são efeitos colaterais esperados, exceto:","options":{"A":"perda de massa óssea","B":"doença aterosclerótica periférica","C":"amenorreia","D":"atrofia muscular","E":"leucopenia"},"answer":"E","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-343352","number":"343352","sourceNumber":"343352","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Um dado do exame físico que levanta a suspeita de puberdade precoce periférica em\num menino de 4 anos com virilização é a\npresença de:","options":{"A":"Pubarca","B":"Ginecomastia","C":"Quadro neurológico","D":"Testículos de volume infantil"},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-249998","number":"249998","sourceNumber":"249998","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Fazem parte da Neoplasia Endócrina Múltipla tipo 1:","options":{"A":"Hiperparatireoidismo primário, lesão pancreática e hipofisária.","B":"Hiperparatireoidismo primário, tumor estromal e hipofisário.","C":"Hipoparatireoidismo primário, tumor estromal e adrenal.","D":"Hipoparatireoidismo primário, gastrinoma e hábito marfanoide."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-181148","number":"181148","sourceNumber":"181148","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Uma jovem de 19 anos deu entrada na sala de emergência com quadro de\nrebaixamento do nível de consciência e grande\ndispneia, associada a tudo isso, uma desidratação\nimportante e grave. Dentre os achados iniciais, uma elevada glicemia capilar e uma intensa\nacidose, além de alterações urinárias levaram ao diagnóstico de Cetoacidose Diabética (CAD).\n\nDentre os desequilíbrios decorrentes da desordem metabólica, somente não podemos considerar\nque:","options":{"A":"A hipofosfatemia leve é um achado raro e geralmente grave durante a terapia da CAD.","B":"Não está indicada a reposição de sais de fosfato de rotina.","C":"Não está indicada a reposição de sais de fosfato em parte devido ao risco de hipocalcemia, na\nhipofosfatemia leve.","D":"Na hipofosfatemia leve, não há evidências suficientes que demonstrem a melhora do\nprognóstico quando em comparação com o não uso."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-181151","number":"181151","sourceNumber":"181151","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Dentro da abordagem das complicações relacionada às Crises Hiperglicêmicas Agudas,\no edema cerebral é uma complicação que somente\nNÃO é correto afirmar que:","options":{"A":"É rara no adulto.","B":"Eventualmente pode evoluir com herniação de tronco cerebral.","C":"Nunca pode ser causa de parada cardiorrespiratória.","D":"Deve ser tratado prontamente com infusão intravascular de manitol a 20%."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-181156","number":"181156","sourceNumber":"181156","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"O diagnóstico correto e o tratamento rápido e eficaz das Crises Hiperglicêmicas Agudas\nsão essenciais para diminuir a morbidade e a\nmortalidade. Muitos desses episódios podem ser\nprevenidos com diversas medidas preventivas, somente não se aplica o exposto na alternativa:","options":{"A":"Bom controle metabólico do diabetes mellitus por meio de tratamento adequado com insulinas\nou análogos de Insulina.","B":"O auto-monitoramento aumenta o risco de complicações.","C":"Orientação educacional aos familiares e ao próprio paciente.","D":"A facilidade de comunicação com o especialista ou com o grupo multidisciplinar que acompanha\no paciente é fundamental."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-181162","number":"181162","sourceNumber":"181162","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Devido à importante associação dos antipsicóticos atípicos com os componentes da\nsíndrome metabólica, é importante o conhecimento acerca da relação entre substâncias\nantipsicóticas e diabetes, somente não sendo recomendado o seguinte:","options":{"A":"Avaliação do risco-benefício.","B":"Dentro da avaliação dos efeitos adversos, vários fatores devem ser valorizados, tais como\nnatureza da condição psiquiátrica do paciente,\nmetas, histórico do fármaco, adesão, efetividade da\nmedicação, comorbidades e custo.","C":"Os riscos das implicações clínicas dos componentes da síndrome metabólica não devem\ninfluenciar a escolha do fármaco.","D":"O monitoramento deve ocorrer se possível, antes da prescrição dos antipsicóticos atípicos,\ndeterminando altura e peso, calculando o Índice De Massa Corporal (IMC), medindo a\ncircunferência da cintura e a pressão arterial, e também dosando a glicemia de jejum e o perfil\nlipídico."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-181176","number":"181176","sourceNumber":"181176","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"A quiroartropatia decorrente do diabetes, caracteriza-se pela deformidade em dedos\ndas mãos, com alterações externas da pele, do\ntecido conjuntivo periarticular e da fáscia palmar,\nresultando em limitação de movimentos das articulações. Somente não sendo adequada a seguinte\ndescrição de suas características clínicas e de fisiopatologia:","options":{"A":"O termo artropatia não é adequado porque o processo fisiopatológico envolve estruturas\nperiarticulares, e não a articulação periférica.","B":"Seu aparecimento deve ser visto como um sinal de alarme, apontando para maior risco de\ndesenvolvimento de microangiopatia e microalbuminúria.","C":"Tem como causa a glicação de colágeno, que altera suas características funcionais e\nestruturais.","D":"A quiroartropatia, em geral, muito dolorida, com contraturas que dificultam a execução de\nmovimentos finos das mãos."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-181180","number":"181180","sourceNumber":"181180","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Um querido familiar estava bastante preocupado com a necessidade de realizar uma\ncirurgia ortopédica devido ao fato de ser\ndiabético, sendo que o Ortopedista o havia alertado sobre\nrelação entre a doença óssea e o diabetes. Quando a pele se mostra brilhante, espessada e\nenrijecida relacionada com Limitação Da Mobilidade Articular (LMA), no diabético. Podemos apenas\nconsiderar como INCORRETO o seguinte item:","options":{"A":"A LMA pode acometer também outras articulações, como punho, cotovelo, quadril e coluna.","B":"Idosos com diabetes podem ter, além de redução do movimento do tornozelo, quadril e ombro,\nanormalidades de tendões observadas por métodos ultrassonográficos.","C":"O acometimento da articulação atlanto-occipital não altera capacidade de intubação traqueal no\nmomento de anestesia.","D":"O acometimento da articulação atlanto-occipital é um sinal preditor de dificuldade para a\nintubação."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-181174","number":"181174","sourceNumber":"181174","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"A Crise Tiroidiana é uma emergência médica que ocorre em pacientes com\ntireotoxicose. Aponte a alternativa INCORRETA sobre esta síndrome:","options":{"A":"A mortalidade da crise tiroidiana é alta, variando de 20% para 50% se a crise não for\nreconhecida e tratada.","B":"Ocorre aumento dos níveis de TSH e aumento dos hormônios T3 e T4 circulantes.","C":"Clinicamente é caracterizada por hiperpirexia, taquicardia desproporcional a febre, desidratação,\nchoque e manifestações cardiovasculares,\ndisfunção do sistema nervoso central.","D":"O tratamento envolve inibição da síntese, diminuição da conversão periférica de T4 em T3 e\nbloqueio da ação dor hormônios tiroideanos, além da remoção extracorpórea destes hormônios."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-157616","number":"157616","sourceNumber":"157616","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Sobre o Hiperparatiroidismo Primário, marque a alternativa INCORRETA.","options":{"A":"Dentre as manifestações clínicas do Hiperparatiroidismo Primário, podemos destacar: dor óssea,\npolidpsia, anorexia, depressão, coma.","B":"Indicações cirúrgicas para Hiperparatiroidismo Primário incluem indivíduos menores que 50\nanos, avaliação densitométrica com perda óssea\nsuperior a 2,5 desvios-padrão em relação ao pico\nde massa óssea, redução do clearance de creatinina em 30%, excreção urinária de cálcio superior\na 400 mg, nível de calcemia total de 1,0 mg/dL acima do limite superior da normalidade.","C":"O tratamento cirúrgico é a única terapêutica definitiva para o hiperparatiroidismo primário,\nembora haja alguma perspectiva de tratamento clínico no futuro com agonistas do receptor\nextracelular de cálcio.","D":"Em geral, o doente com Hiperparatiroidismo Primário que vai ser submetido a tratamento\ncirúrgico não requer preparo pré-operatório\nespecífico. Se os níveis de cálcio estiveram maior que\n14mg/dl, podem requerer preparo com hiper-hidratação, diuréticos e Fósforo."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-157675","number":"157675","sourceNumber":"157675","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"É indicação relativa de Tiroidectomia:","options":{"A":"a suspeita de malignidade pelo exame físico, ultrassonográfico e citológico.","B":"Os bócios pequenos com alteração estética importante.","C":"O bócio tóxico.","D":"O bócio de grande volume."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-350900","number":"350900","sourceNumber":"350900","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Mulher de 55 anos foi investigada por ganho de peso e astenia, tendo sido constatadas\nas seguintes alterações laboratoriais:\nTSH=30mU/L, T4l=0,1ng/dL, Colesterol total=340mg/dL,\nHDL=30mg/dL, LDL=232mg/dL, Triglicerídeos=390mg/dL, Cr=1,1mg/dL. Foi prescrita levotiroxina\n50mcg pela manhã com reavaliação após 6 semanas. No retorno, a paciente relatou que ficou\npreocupada com o colesterol e optou por tomar remédio de sua mãe (rosuvastatina 20mg todos os\ndias), antes de iniciar o tratamento proposto inicialmente. Agora, relata intensas dores em\npanturrilhas e coxas e episódios de urina avermelhada. Novos exames mostram hemograma\nnormal, CPK=1.200U/L, Cr=2,5mg/dL, sumário de urina com Hb (++), sem hemácias no sedimento.\nOptou-se pelo internamento com hidratação e monitorização. Após 5 dias, exames normalizaram.\nQual deve ser a conduta medicamentosa após a alta desta paciente?","options":{"A":"Suspender rosuvastatina e iniciar levotiroxina.","B":"Reduzir dose de rosuvastatina e iniciar levotiroxina.","C":"Postergar início de levotiroxina e suspender rosuvastatina.","D":"Postergar início de levotiroxina e reduzir dose de rosuvastatina."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-350825","number":"350825","sourceNumber":"350825","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"RNT, sem intercorrências ao nascimento, encontra-se no 10º dia de vida, estável em ar\nambiente e apresentando icterícia por aumento de bilirrubina indireta. Ao exame físico, além da\nicterícia, apresentava abdome globoso sem megalias palpáveis e sem outras alterações ao exame\nfísico. Mãe com tipagem sanguínea \"O positiva\" e RN \"O\" positivo também. A que doença a icterícia\npoderia estar associada?","options":{"A":"Hepatite.","B":"Obstrução de vias biliares.","C":"Hipotireoidismo congênito.","D":"Hipoatividade da medula óssea."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-321283","number":"321283","sourceNumber":"321283","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Mulher de 19 anos apresenta episódios de diarreia profusa com rubor facial e queixa de\nperda de 8 kg, atualmente seu peso é 43 kg, IMC 16. Na investigação, foi detectada uma elevação\nde cálcio sérico e calcitonina. Qual exame de imagem, inicialmente, deve ser solicitado para\nesclarecimento dessa condição?","options":{"A":"Colonoscopia.","B":"Radiografia do tórax.","C":"Ultrassonografia cervical.","D":"Tomografia do abdome."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-292806","number":"292806","sourceNumber":"292806","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Uma paciente de 47 anos é investigada por \"desmaios\". Ela refere pouca tolerância ao\njejum e sente necessidade de alimentar-se com frequência de alimentos doces. Na avaliação, foi\ndetectada somente insulina alta e um nódulo no pâncreas de 1 cm, vista a tomografia. Demais\nexames sem alterações. Durante laparotomia, identifica-se um nódulo avermelhado na superfície\npancreática de 1 cm à esquerda dos vasos mesentéricos sem relação com o ducto pancreático\nprincipal. Qual deve ser a estratégia cirúrgica?","options":{"A":"Enucleação do nódulo.","B":"Pancreatectomia central.","C":"Duodenopancreatectomia.","D":"Pancreatectomia corpo-caudal."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-234012","number":"234012","sourceNumber":"234012","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente masculino, 66 anos, procura atendimento com um cirurgião geral para uma\n\"segunda opinião\". Informa que há um mês\nprocurou atendimento de emergência por um quadro de\ndor abdominal inespeci?fica. Foi solicitada uma tomografia computadorizada do abdômen que\nevidenciou como único achado positivo uma lesão homogênea bem delimitada e com aparente\nbaixa captação de contraste em glândula adrenal esquerda, medindo 4 cm. O paciente nega\nhipertensão, doenças cardíacas e outras comorbidades. No momento da consulta, nega uso de\nmedicações regulares, está assintomático e apresenta exame fi?sico normal. Qual deve ser a\nconduta?","options":{"A":"Solicitar punc?a?o guiada por tomografia para coleta de amostra citolo?gica da massa.","B":"Encaminhar para a ressecc?a?o da massa (adrenalectomia) em decorre?ncia de alto risco de\nmalignizac?a?o.","C":"Por se tratar de lesa?o com aspecto tomogra?fico benigno, observar e realizar exames\ntomogra?ficos semestrais.","D":"Solicitar dosagem de catecolaminas urina?rias em 24h e teste de supressa?o com dose baixa de\ndexametasona."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-234034","number":"234034","sourceNumber":"234034","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Mulher de 38 anos com evacuações frequentes há 3 meses, em qualquer hora do dia\nou da noite, volumosas, aquosas, sem\nsangue, dor, febre ou relação com as refeições. Relata\nperda de 2 kg, redução do apetite, náuseas e tonturas matinais. Nega etilismo, medicamentos de\nuso crônico ou habitual. Ao exame, apresenta hiperpigmentação cutânea e algumas lesões\nhipocrômicas sugestivas de vitiligo. Normocorada, anictérica e afebril, apresenta hipotensão\npostural e desidratação leve. IMC: 26 kg/m². Exame do abdome e demais sistemas sem\nanormalidades. Exames prévios: hemograma normal, sódio: 132 mEq/L (VR: 135?145 mEq/L),\npotássio: 5,6 mEq/L (VR: 3,5?5,0 mEq/L), pesquisa de sangue oculto nas fezes negativo, pesquisa\nde gordura fecal 3 g/dia (VR: 1,8?6 g/dia). LEGENDA: VR: Valor de Referência; IMC: Índice de\nMassa Corporal. Qual conduta mais apropriada e o diagnóstico provável?","options":{"A":"Pesquisar o antígeno da Giardia lamblia e tratar com metronidazol ? giardíase.","B":"Dosar cortisol e ACTH basal e repor glico e mineralocorticoide ? doença de Addison.","C":"Realizar teste terapêutico com antidepressivos tricíclicos ? síndrome do intestino irritável.","D":"Realizar teste terapêutico com restrição de leite e derivados na dieta ? intolerância à lactose."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-199773","number":"199773","sourceNumber":"199773","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Mulher de 28 anos compareceu em consulta ambulatorial referindo ganho de peso há 8\nmeses, associado ao surgimento de acne, hirsutismo, irregularidade menstrual e fraqueza\nmuscular. Há 2 meses, refere sintomas depressivos e nega uso de outros medicamentos. Ao\nexame, PA = 150 x 100 mmHg, pulso = 92 bpm. Índice de massa corporal = 32 kg/m²; cintura = 98\ncm. Face arredondada e pletórica. Pele fina, com acne em face e dorso, estrias largas e arroxeadas\nabdominais e equimoses em membros. Fraqueza muscular proximal. Qual exame está indicado no\ninício da investigação para confirmar o diagnóstico clínico?","options":{"A":"Cortisol plasmático basal.","B":"Cortisol salivar domiciliar às 23:00.","C":"Cortisol livre urinário em amostra isolada.","D":"Cortisol pós-8 mg dexametasona às 23:00."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-172958","number":"172958","sourceNumber":"172958","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Mulher de 29 anos procurou assistência médica referindo há 3 meses perda de peso (3\nkg), irritabilidade, calor excessivo e palpitações. A paciente refere ainda amenorreia há 2 meses,\nnáuseas e vômitos. Ao exame, apresentava proptose ocular bilateral, bócio difuso e indolor, tremor\nfino de extremidades e taquicardia. Exames laboratoriais: TSH < 0,02 mUI/L (VR = 0,3-4,0 mUI/L);\nT4 livre = 2,17 ng/dl (VR = 0,7-1,5 ng/dl); TRAb = 5,4 U/L (positivo > 1,75 U/L); hCG = positivo.\n\nLegenda: TSH ? hormônio tireoestimulante; T4 ? tiroxina; TRAb ? anticorpo antirreceptor de TSH;\nhCG ? gonadotrofina coriônica humana; VR ? Valor de Referência. Qual a conduta terapêutica mais\nindicada?","options":{"A":"Hidratar.","B":"Iniciar metimazol.","C":"Iniciar propiltiouracila.","D":"Realizar tireoidectomia total."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-127010","number":"127010","sourceNumber":"127010","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente feminina, primeiro pós-operatório de tireoidectomia por suspeita de câncer de\ntireoide, encontra-se bastante ansiosa e referindo adormecimento perioral. O médico faz o sinal de\nChvostek que é francamente positivo. Qual o diagnóstico dessa paciente?","options":{"A":"Hipocalcemia devido a hipoparatireoidismo iatrogênico.","B":"Crise tireotóxica devido manipulação da glândula tireoide.","C":"Transtorno de ansiedade generalizado com alcalose devido hiperventilação.","D":"Hipotireoidismo agudo devido a reposição ineficiente dos hormônios tireoideanos."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-126974","number":"126974","sourceNumber":"126974","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Mulher de 25 anos, IMC 30 kg/m2, chega ao seu consultório referindo episódios de\nsudorese, agitação com obnubilação e desmaios\nquando foram constatados baixos níveis\nglicêmicos. Refere esses sintomas há bastante tempo, mas eram atribuídos à \"crise nervosa\". Nos\nepisódios de desmaios, houve necessidade da administração de glicose EV que reverteu a\nsintomatologia. Ao exame: obesidade grau 1, certo grau de déficit cognitivo. Nega uso de\nmedicações. Quais os resultados prováveis dos exames dessa paciente em jejum prolongado?","options":{"A":"Glicose sérica inferior a 60 mg/dL e níveis elevados de sulfonilureia na urina.","B":"Glicose sérica inferior a 50 mg/dL, com baixo nível de proinsulina sérica e alta dosagem de\npeptídeo C.","C":"Glicose sérica superior a 120 mg/dL, com alto nível de insulina sérica e baixa dosagem de\npeptídeo C.","D":"Glicose sérica inferior a 50 mg/dL, com alto nível de insulina sérica e relação insulina/ glicose\nmaior que 0,4."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-126994","number":"126994","sourceNumber":"126994","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Mulher de 35 anos comparece para avaliação com história de febre não mensurada,\nperda de peso com apetite preservado,\nsudorese e palpitações. No exame físico, você observa\nfrequência cardíaca de 108 bpm, Pressão arterial 150x60 mmHg, mãos quentes e úmidas e leve\ntremor de extremidades. Qual dos itens abaixo representa a combinação de exames esperada\nnesse caso?","options":{"A":"TSH baixo e T4 livre baixo.","B":"TSH alto e T4 livre baixo.","C":"TSH alto e T4 livre alto.","D":"TSH baixo e T4 livre alto."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-81290","number":"81290","sourceNumber":"81290","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente feminina, 70 anos, em tratamento quimioterápico para carcinoma escamoso\nde pulmão com metástases ósseas e pulmonares,\nprocura atendimento por apresentar\ndesorientação, anorexia e vômitos com início há uma semana. Está desidratada 2+/4+.\n\nNormotensa. Considerando uma síndrome paraneoplásica como causa provável do quadro clínico\nda paciente, qual dosagem sérica tem maiores\nchances de estabelecer o diagnóstico?","options":{"A":"Sódio.","B":"Cálcio.","C":"Cortisol.","D":"Glicemia."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-81245","number":"81245","sourceNumber":"81245","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Criança com 30 dias de vida comparece à consulta e evidencia-se teste do pezinho\nalterado (positivo) para hipotireoidismo. Qual a\nCORRETA abordagem clínica para essa criança?","options":{"A":"Solicitar dosagens séricas de TSH e T4 livre.","B":"Repetir o teste do pezinho antes de novos exames.","C":"Iniciar tratamento e referenciar para centro especializado.","D":"Solicitar dosagem do T4 livre em amostra de papel de filtro."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-65766","number":"65766","sourceNumber":"65766","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente de 60 anos é internado na UTI, no pós-operatório de necrosectomia por\npancreatite necro-hemorrágica. Apresenta estado geral\ngrave, taquicardia, hipotensão responsiva à\nadministração de fármacos vasoativos, fraqueza muscular que impede desmame de ventilador\npulmonar mecânico, náusea, vômitos e febre. As culturas são negativas para crescimento\nbacteriano. Os exames laboratoriais indicam: hipoglicemia, hiponatremia e hipercalemia. Dentre as\nalterações hormonais que ocorrem no período perioperatório de pacientes graves, assinale a\nalternativa que justifica os achados clínicos e laboratoriais descritos no caso acima.","options":{"A":"Insuficiência adrenal.","B":"Resistência à insulina.","C":"Excesso de catecolaminas.","D":"Resistência adquirida ao GH.","E":"Insuficiência de produção de TSH."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-65771","number":"65771","sourceNumber":"65771","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Homem de 47 anos comparece com dispneia aos moderados esforços e parestesias\nnas mãos. Tem diagnóstico de diabetes e\nhipertensão há 5 anos. Durante o interrogatório por\nórgãos, o médico descobre crescimento dos pés e mãos, hiper-hidrose, ronco e mudança da voz.\nNo exame físico, há quarta bulha, prognatismo e macroglossia. Qual dos exames abaixo deve ser\nusado como screening para o diagnóstico desse paciente?","options":{"A":"Imunofixação sérica e urinária.","B":"Dosagem do hormônio do crescimento (GH).","C":"Dosagem do índice de saturação da transferrina.","D":"Dosagem do hormônio estimulante da tireoide (TSH).","E":"Dosagem do fator de crescimento ?insulina-like? 1 (IGF-1)."},"answer":"E","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-51164","number":"51164","sourceNumber":"51164","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Mulher de 38 anos comparece para consulta com quadro de redução da libido, atrofia\nmamária, ganho de peso, fala arrastada e astenia intensa. Exame físico: mamas atróficas, anasarca\n(+/4+) e redução da pilificação genital. Uma avaliação laboratorial mostra T4 livre baixo; TSH no\nlimite inferior; cortisol basal = 05 mcg/dl após estimulação com ACTH (valor de referência > 18\nmcg/dl); testosterona baixa e FSH e LH nos limites inferiores. Qual o exame mais provavelmente\nrevelará a causa da sua doença?","options":{"A":"Tomografia de abdome.","B":"Cintilografia de tireoide.","C":"Teste combinado da pituitária anterior.","D":"Ressonância nuclear magnética de encéfalo."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-51280","number":"51280","sourceNumber":"51280","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Mulher jovem apresenta aumento homogêneo da porção anterior do pescoço, labilidade\nemocional, tremor de extremidades, taquicardia, sudorese profusa e perda de peso. Após\nconfirmação diagnóstica, a cirurgia deverá ser indicada se a paciente apresentar qual das\ncondições associadas?","options":{"A":"Gravidez.","B":"Exoftalmia.","C":"Rouquidão.","D":"Tireotoxicose."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-51287","number":"51287","sourceNumber":"51287","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente de 56 anos comparece para consulta com queixa de piora do quadro prévio de\nAngina pectoris. Vinha em uso de sinvastatina, aspirina e metoprolol. Exame físico: cabelos\nressecados, fala arrastada e edema facial (+/4+). Peso: 75 kg; pulso: 92 bpm. Além da doença\ncoronariana (para a qual se vale de Sinvastatina, Aspirina e Metoprolol), tem hipotireoidismo de\ndiagnóstico recente, em uso de 75 mcg de levotiroxina. Foi iniciado tratamento com isossorbida.\n\nCom relação ao tratamento do hipotireoidismo desse paciente, que conduta é recomendável?","options":{"A":"Suspender a levotiroxina.","B":"Manter a dose de levotiroxina.","C":"Reduzir a dose da levotiroxina para 25 mcg/dia.","D":"Aumentar a dose de levotiroxina para 112,5 mcg/dia."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-51234","number":"51234","sourceNumber":"51234","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Mulher de 60 anos, em primeiro dia pós-operatório de tiroidectomia total, apresenta\nagitação na enfermaria. Ao ser abordada, a\npaciente encontra-se alerta, porém com desorientação\nespacial e alucinações visuais (descrevia animais e monstros circulando seu leito). A cicatriz\ncirúrgica estava limpa. Ao aferir a pressão arterial da paciente, observa-se intenso espasmo carpal.\nNão havia outros achados no exame físico. Qual alteração deve estar presente no\neletrocardiograma desta paciente?","options":{"A":"Alargamento do QRS.","B":"Aumento do intervalo PR.","C":"Elevação do segmento ST.","D":"Prolongamento do intervalo QT."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-37376","number":"37376","sourceNumber":"37376","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Considere o quadro clínico e escolha a alternativa correta: Paciente feminina, branca,\n32 anos, balconista, refere fadiga e cansaço\nfísico. Nega dispneia. Apresenta também episódios de\nirritabilidade, ansiedade e insônia há cerca de três meses, associando os sintomas à mudança\nrecente de emprego. Relata que, apesar de aumento da ingesta alimentar, perdeu 8 kg no período.\nTambém apresenta palpitações e tremores finos em extremidades. No exame físico, foi evidenciado\nritmo cardíaco irregular, FC 110 bpm, aumento de volume em região cervical anterior e proptose\nocular bilateral.","options":{"A":"Trata-se de doença autoimune da tireoide, caracterizada por produção aumentada de\nimunoglobulinas tireoestimulantes, levando à secreção aumentada de hormônio tireoidiano e\naumento difuso da glândula. Deve ser solicitada dosagem de T4 livre e TSH para confirmação e\niniciado tratamento com levotiroxina e betabloqueador.","B":"Trata-se de doença autoimune da tireoide, caracterizada por destruição do tecido tireoidiano,\nlevando a hipofunção com infiltrado\nlinfocitário e fibrose da glândula. Deve ser solicitada dosagem\nde T4 livre e TSH para confirmação e iniciado tratamento com levotiroxina dose baixa, com\nposterior progressivo aumento da dose.","C":"Trata-se de doença autoimune da tireoide, caracterizada por produção aumentada de\nimunoglobulinas tireoestimulantes, levando à secreção aumentada de hormônio tireoidiano e\naumento difuso da glândula. Deve ser solicitada dosagem de T4 livre e TSH para confirmação e\niniciado tratamento com propiltiouracil e betabloqueador.","D":"Trata-se de doença autoimune da tireoide, caracterizada por destruição do tecido tireoidiano,\nlevando à hipofunção com infiltrado\nlinfocitário e fibrose da glândula. Deve ser solicitada dosagem\nde T4 livre e TSH para confirmação e iniciado tratamento com propiltiouracil e betabloqueador.","E":"Trata-se de doença autoimune da tireoide, caracterizada por produção aumentada de\nimunoglobulinas tireoestimulantes, levando à hipofunção tireoidiana com infiltrado linfocitário e\nfibrose da glândula. Deve ser solicitada dosagem de T4 livre e TSH para confirmação e iniciado\ntratamento com propiltiouracil e betabloqueador."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-30934","number":"30934","sourceNumber":"30934","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Mulher de 25 anos é encaminhada por apresentar níveis séricos elevados de T4 total e\nníveis normais de TSH. Assintomática. Qual dessas opções apresenta a explicação mais provável\ndessa alteração laboratorial?","options":{"A":"Hipertireoidismo subclínico.","B":"Resistência hipofisária ao hormônio tireoideano.","C":"Resistência periférica ao hormônio tireoideano.","D":"Uso de anticoncepcional oral.","E":"Adenoma hipofisário produtor de TSH."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-22935","number":"22935","sourceNumber":"22935","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente 65 anos, diabética, com antecedente de uso de amiodarona por arritmia\ncardíaca controlada evolui, em 3o pós-operatório\nde colecistectomia, com confusão mental e\nsonolência. Seus sinais vitais estão normais, não tem dispneia, dor torácica e os exames mostram\nhiponatremia (Na = 120 mEq/L) com glicemia e eletrocardiograma normais. São, respectivamente,\na causa mais provável e o exame a ser solicitado:","options":{"A":"insuficiência renal e creatinina","B":"tromboembolismo pulmonar e dímero-D","C":"hipotireoidismo e TSH","D":"acidente vascular cerebral e tomografia computadorizada de crânio","E":"sepse e hemoculturas"},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-22952","number":"22952","sourceNumber":"22952","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Dentro das patologias benignas da tireoide, podemos citar os distúrbios do metabolismo\ncomo o hipotireoidismo. Sobre essa\npatologia é INCORRETO afirmar que:","options":{"A":"está associado a um decréscimo da produção de T3 e T4 na glândula, embora possam também\nocorrer estados de limitada atividade na\nperiferia","B":"a ingestão insuficiente de iodo em países subdesenvolvidos explica a grande quantidade de\nestados hipotieoideos. Já nos países desenvolvidos as principais causas são a tireoidite de\nHashimoto e a ablação cirúrgica da glândula","C":"outras causas mais raras de hipotireoidismo referem-se aos defeitos hereditários da síntese de\nhormônio, ação medicamentosa e hipoplasia ou agenesia da tireoide","D":"acompanhando as alterações fisiológicas em resposta à deficiência de iodo, ocorre uma\ndiminuição difusa da glândula por uma resposta hipotrófica dos folículos tireoideanos e aumento\ndos espaços foliculares","E":"à medida que a deficiência de iodo torna-se mais grave, os folículos podem se tornar inativos e\ndistendidos pelo coloide, levando, em alguns casos à necrose, retração, hemorragia e retração\nfibrosa"},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-22954","number":"22954","sourceNumber":"22954","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"A incidência do hiperparatireoidismo primário (HPT) é de aproximadamente 25 por\n\n100.000 da população em geral, aumentando com a idade. A sua causa ainda é desconhecida.\n\nSobre essa patologia, assinale o item ERRADO.","options":{"A":"As complicações renais são frequentemente as manifestações mais graves, tais como\nnefralitíase, nefrocalcinose, nictúria e polidipsia","B":"a hipertensão no HPT é um fenômeno frequente e parece estar relacionada com o grau do\ndistúrbio renal","C":"pacientes com hipercalcemia podem manifestar distúrbios psiquiátricos ou nervosos, variando\ndesde depressão e ansiedade até psicose ou coma","D":"o diagnóstico de HPT primário é tipicamente feito com a documentação de uma elevação da\nconcentração de cálcio sérico em conjunto a uma elevação do PTH","E":"apesar do PTH exercer efeito sobre a excreção de bicarbonato pelo rim, pacientes com HPT\nraramente apresentam acidose metabólica hiperclorêmica"},"answer":"E","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-22962","number":"22962","sourceNumber":"22962","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Feocromocitomas são tumores adrenais secretores de catecolaminas que derivam das\ncélulas cromafins da medula adrenal. São tumores raros e podem se apresentar na forma\nesporádica ou familiar. São afirmativas corretas a respeito dos feocromocitomas, EXCETO:","options":{"A":"apresentam-se com sinais e sintomas de excesso de catecolaminas, como hipertensão arterial,\npalpitações, ansiedade, cefaleia e rubor. Podem também manifestar complicações cardiovasculares\ncomo infarto, arritmias e apoplexia","B":"um dado para o diagnóstico é a demonstração de aumento das catecolaminas plasmáticas e\nurinárias e de seus metabólitos. Apesar da dosagem urinária em 24 horas de ácido vanil mandélico\npossuir baixa especificidade, a dosagem sérica de metanefrinas fracionadas tem sido utilizada\ncomo método inicial de avaliação bioquímica por ser altamente sensível","C":"dentre os feocromocitomas, até 98% são encontrados no abdome, 2 a 3% no tórax e 1% no\npescoço. De todos eles, 10% são\nextra-adrenais ou bilaterais ou familiares ou malignos. Esta é uma\nregra regularmente acurada e utilizada","D":"o tratamento pré-operatório de pacientes com feocromocitoma centraliza-se em controle da\nhipertensão, bloqueio a-adrenérgico para evitar crise hipertensiva intraoperatória e reposição de\nfluidos para evitar colapso circulatório após a retirada do tumor","E":"para ressecção dos feocromocitomas opta-se por uma abordagem aberta e ampla para completa\nexploração do abdome. Independente do tamanho da lesão, o uso da laparoscopia é bastante\nrestrito nessas situações por não permitir um inventário adequado da cavidade"},"answer":"E","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-24307","number":"24307","sourceNumber":"24307","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Mulher de 32 anos evoluindo com febre baixa, mialgia e dor de garganta há 01 semana.\nHá 03 dias percebeu aumento do volume da\ntireóide que se mostrava muito dolorosa à palpação.\n\nNo momento do exame, apresentava FC=120 bpm, exame da orofaringe normal e sopro sistólico\npancardíaco. Qual a melhor opção em relação ao diagnóstico e conduta?","options":{"A":"Trata-se de Doença de Graves. Solicito TSH, T3 e T4 e inicio propiltiouracil","B":"Trata-se tireoidite viral. Solicito TSH, T3 e T4 e inicio AAS","C":"Trata-se de Doença de Graves. Solicito TSH e T4 livre e início prednisona","D":"Trata-se de tireoidite silenciosa. Solicito TSH e T4 livre e início propiltiouracil"},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-27744","number":"27744","sourceNumber":"27744","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente 36 anos, sexo feminino, com história de fadiga, constipação intestinal,\n\n?esquecimento?. Apresenta-se com a pele ressecada, pulso 60 ppm. A dosagem de T4 livre\nencontra-se diminuída e a de TSH aumentada. Qual a hipótese diagnóstica mais provável para\nesse caso?","options":{"A":"Hipotireoidismo primário","B":"Hipotireoidismo secundário","C":"Eutireoidismo","D":"Resistência ao hormônio tireoideano","E":"Hipertireoidismo"},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-25472","number":"25472","sourceNumber":"25472","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Mulher, 48 anos, obesa, hipertensa e diabética com fácies cushingoide. As dosagens\nde ACTH e cortisol matinal mostraram-se\ndiminuídas. Qual o provável diagnóstico?","options":{"A":"Síndrome de Cushing por adenoma adrenal","B":"Síndrome de Cushing por carcinoma adrenal","C":"Síndrome de Cushing iatrogênico","D":"Síndrome de Cushing central (doença de Cushing)","E":"Síndrome de Cushing ectópico por produção de ACTH ectópico."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-27721","number":"27721","sourceNumber":"27721","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Sobre as doenças da medula adrenal todas são verdadeiras, EXCETO:","options":{"A":"feocromocitomas são tumores adrenais secretores de catecolaminas.","B":"feocromocitomas em 10% são bilaterais, extra-adrenais, familiares, malignos e em 10% ocorrem\nem crianças.","C":"o efeito máximo do bloqueio alfa-adrenérgico é alcançado com o uso do nitroprussiato de sódio.","D":"feocromocitoma está associado com a MEN (neoplasia endócrina múltipla) tipo II.","E":"o feocromocitoma maligno é mais comum nas mulheres (3M: 1H)."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-24354","number":"24354","sourceNumber":"24354","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Indique qual das seguintes drogas é utilizada no tratamento da hiperprolactinemia, na\npresença ou não de adenoma hipofisário:","options":{"A":"Citrato de clomifeno.","B":"Tamoxifen.","C":"Bromoergocriptina.","D":"Progesterona."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-7266","number":"7266","sourceNumber":"7266","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Sobre a anatomia da glândula tireoide, responda o item correto.","options":{"A":"As artérias tireoideas superior e inferior são ramos diretos da artéria carótida externa e\nsubclávia, respectivamente.","B":"A glândula é drenada por três pares de sistema venoso: superior, média e inferior. A veia\ntireoidea média é encontrada em mais da metade das pessoas.","C":"A tireoide apresenta um pobre sistema de drenagem linfática, justificando portanto a baixa\nincidência de metástases linfonodais.","D":"Do lado esquerdo o nervo laríngeo recorrente separa-se do vago quando cruza com a artéria\nsubclávia. Do lado direito esta separação se dá quando o nervo atravessa a artéria aorta.","E":"O nervo laríngeo superior separa-se do nervo vago no pólo superior da tireoide e possui apenas\nfunção motora."},"answer":"E","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-9011","number":"9011","sourceNumber":"9011","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Qual das seguintes manifestações clínicas é comum na Síndrome de Cushing?","options":{"A":"Hipoglicemia","B":"Hipercalemia","C":"Alopecia","D":"Hipertensão arterial"},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-349743","number":"349743","sourceNumber":"349743","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente do sexo feminino, 56 anos, em pós-operatório de tireoidectomia radical, deu\nentrada no pronto atendimento com queixa de formigamento em membros superiores e tremores,\nassociados a sudorese. No exame físico, são encontrados sinais de Trousseau e Chvostek\npositivos. Considerando o antecedente da paciente, qual eletrólito pode estar em níveis alterados e\nque poderia explicar a clínica e os achados no exame físico?","options":{"A":"Cálcio.","B":"Sódio.","C":"Potássio.","D":"Magnésio.","E":"Cloro."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-365646","number":"365646","sourceNumber":"365646","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"A tireoidite de Hashimoto, o mais frequente distúrbio autoimune da tireoide, é a\nprincipal\ncausa de hipotireoidismo nas áreas do mundo onde não há deficiência de iodo. (Disponível em\n\n<https://www.sciencedirect.com/science/article/abs/pii/S1521690X19301186> Acesso em: 7 dez.\n2023, com adaptações.) Quanto a esse tema,\nentre os fatores de risco para o desenvolvimento da\ntireoidite de Hashimoto, está o (a)","options":{"A":"testosterona.","B":"excesso de vitamina D.","C":"suspensão de tratamento com interferon.","D":"excesso de iodo."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-322128","number":"322128","sourceNumber":"322128","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Um paciente será submetido a uma tireoidectomia total. Qual das alternativas a seguir\napresenta uma complicação que pode ocorrer em consequência desse tipo de cirurgia e sua\njustificativa?","options":{"A":"Hiperparatireoidismo por lesão das paratireoides.","B":"Paralisia de prega vocal por lesão do nervo laríngeo recorrente.","C":"Hipertireoidismo por liberação de grande quantidade de hormônios tireoideanos.","D":"Rouquidão por lesão do nervo glossofaríngeo.","E":"Hipercalcemia por paratireoidectomia acidental."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-322150","number":"322150","sourceNumber":"322150","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Em relação ao hipotireoidismo, é correto afirmar que","options":{"A":"é muito importante solicitar tireoglobulina sérica na avaliação inicial de nódulos de tireoide.","B":"a dosagem do T3 reverso (rT3), na avaliação de função tireoideana, é essencial.","C":"Não devem ser repetidos exames de autoanticorpos [antitireoperoxidase (Anti-TPO) e/ou\nantitireoglobulina] no seguimento de\npacientes com hipotireoidismo por tireoidite de Hashimoto com\nexame anterior positivo.","D":"é essencial a dosagem de tri-iodotironina (LT3), isolada ou em associação com levotiroxina\n(LT4), no tratamento de hipotireoidismo.","E":"a dosagem de marcadores moleculares, na avaliação inicial de pacientes com nódulo de tireoide,\né muito importante para o plano terapêutico."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-322179","number":"322179","sourceNumber":"322179","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Na Hiperplasia congênita das suprarrenais por deficiência da 21-hidroxilase, ocorre","options":{"A":"aumento exagerado da produção de cortisol, sem alterar os níveis de aldosterona.","B":"deficiência de 17-hidroxiprogesterona, com aumento da produção dos androgênios suprarrenais,\nexceto de androstenediona e testosterona.","C":"aumento do cortisol, com retroalimentação negativa deficiente do cortisol na hipófise e no\nhipotálamo, seguida por grave redução de hormônio liberador de corticotrofina e hormônio\nadrenocorticotrófico.","D":"hiperplasia das glândulas por redução dos níveis de hormônio liberador de corticotrofina e de\nhormônio adrenocorticotrófico.","E":"deficiência da produção de cortisol e, em 75% dos pacientes, deficiência da produção de\naldosterona."},"answer":"E","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-322192","number":"322192","sourceNumber":"322192","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Quais dos seguintes sintomas podem estar associados ao aumento do hormônio\nprolactina no organismo?","options":{"A":"Queda de cabelo e acne.","B":"Hirsutismo e aumento do fluxo menstrual.","C":"Amenorreia e galactorreia.","D":"Irregularidade menstrual e disforia pré-menstrual.","E":"Dispareunia e dismenorreia."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-305276","number":"305276","sourceNumber":"305276","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Uma paciente com um nódulo de tireoide biopsiado, compatível com neoplasia, possui\nindicação de tireoidectomia total. Para realizar tal cirurgia, o médico deve ter o conhecimento das\nestruturas anatômicas da região. Assinale a alternativa que apresenta apenas informações\nCORRETAS sobre a anatomia locorregional necessária para esse procedimento.","options":{"A":"A tireoide está localizada sob os músculos platisma e escaleno, que devem ser seccionados ou\nafastados para acessá-la.","B":"É necessário ficar atento quanto ao trajeto do nervo glossofaríngeo, já que ele tem seu trajeto\nlateral e adjacente à tireoide.","C":"É necessário ficar atento quanto ao esôfago, que tem trajeto posterior e adjacente à glândula\ntireoide.","D":"É necessário ficar atento às paratireoides, que se localizam atrás da glândula tireoide,\nadjacentes a ela.","E":"As artérias que irrigam a tireoide ? tireóidea superior, média e inferior ? provêm da artéria\ncarótida interna."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-305277","number":"305277","sourceNumber":"305277","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Um paciente com sintomas de sudorese, agitação, confusão mental, com níveis baixos\nde glicose e alívio após administração de\nglicose foi diagnosticado com um tumor gastrointestinal e\ntem indicação de tratamento cirúrgico. Quais são, respectivamente, o nome desse conjunto de\nsinais de sintomas e o do provável tumor desse paciente?","options":{"A":"Tríade de Charcot / Gastrinoma.","B":"Síndrome de Verner-Morrison / VIPoma.","C":"Síndrome de Verner-Morrison / Glucagonoma.","D":"Tríade de Virchow / GIST.","E":"Tríade de Whipple / Insulinoma."},"answer":"E","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-298863","number":"298863","sourceNumber":"298863","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Um paciente de 60 anos de idade, proveniente da Índia, foi atendido no pronto-socorro\npor alteração do status mental, humor deprimido\ne mudança de comportamento. Além disso, ele\napresentava dor óssea. Exames bioquímicos indicaram o nível de PTH 20 vezes acima do valor de\nreferência. A função renal mostrou-se preservada; SatO2 = 97% em ar ambiente; FC = 86 bpm; e\nPA = 120 mmHg x 84 mmHg. TC de pelve foi realizado, conforme imagem a seguir. A respeito\ndesse caso clínico e tendo em vista os conhecimentos médicos correlatos, julgue os itens a seguir.\nPor causa da alteração de humor depressivo, o ideal é iniciar com lítio e risperidona em doses\nbaixas.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-298864","number":"298864","sourceNumber":"298864","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Um paciente de 60 anos de idade, proveniente da Índia, foi atendido no pronto-socorro\npor alteração do status mental, humor deprimido\ne mudança de comportamento. Além disso, ele\napresentava dor óssea. Exames bioquímicos indicaram o nível de PTH 20 vezes acima do valor de\nreferência. A função renal mostrou-se preservada; SatO2 = 97% em ar ambiente; FC = 86 bpm; e\nPA = 120 mmHg x 84 mmHg. TC de pelve foi realizado, conforme imagem a seguir. A respeito\ndesse caso clínico e tendo em vista os conhecimentos médicos correlatos, julgue os itens a seguir.\nO PTH é responsável pelo aumento do cálcio sérico.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-298865","number":"298865","sourceNumber":"298865","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Um paciente de 60 anos de idade, proveniente da Índia, foi atendido no pronto-socorro\npor alteração do status mental, humor deprimido\ne mudança de comportamento. Além disso, ele\napresentava dor óssea. Exames bioquímicos indicaram o nível de PTH 20 vezes acima do valor de\nreferência. A função renal mostrou-se preservada; SatO2 = 97% em ar ambiente; FC = 86 bpm; e\nPA = 120 mmHg x 84 mmHg. TC de pelve foi realizado, conforme imagem a seguir. A respeito\ndesse caso clínico e tendo em vista os conhecimentos médicos correlatos, julgue os itens a seguir.\nSintomas psiquiátricos são pouco conhecidos e extremamente raros nesses pacientes.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-298866","number":"298866","sourceNumber":"298866","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Um paciente de 60 anos de idade, proveniente da Índia, foi atendido no pronto-socorro\npor alteração do status mental, humor deprimido\ne mudança de comportamento. Além disso, ele\napresentava dor óssea. Exames bioquímicos indicaram o nível de PTH 20 vezes acima do valor de\nreferência. A função renal mostrou-se preservada; SatO2 = 97% em ar ambiente; FC = 86 bpm; e\nPA = 120 mmHg x 84 mmHg. TC de pelve foi realizado, conforme imagem a seguir. A respeito\ndesse caso clínico e tendo em vista os conhecimentos médicos correlatos, julgue os itens a seguir.\nVitamina D pode ser considerada como um tratamento não cirúrgico importante para esse paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-298867","number":"298867","sourceNumber":"298867","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Um paciente de 60 anos de idade, proveniente da Índia, foi atendido no pronto-socorro\npor alteração do status mental, humor deprimido\ne mudança de comportamento. Além disso, ele\napresentava dor óssea. Exames bioquímicos indicaram o nível de PTH 20 vezes acima do valor de\nreferência. A função renal mostrou-se preservada; SatO2 = 97% em ar ambiente; FC = 86 bpm; e\nPA = 120 mmHg x 84 mmHg. TC de pelve foi realizado, conforme imagem a seguir. A respeito\ndesse caso clínico e tendo em vista os conhecimentos médicos correlatos, julgue os itens a seguir.\nAs setas em branco denotam lesões líticas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-298868","number":"298868","sourceNumber":"298868","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Um paciente de 60 anos de idade, proveniente da Índia, foi atendido no pronto-socorro\npor alteração do status mental, humor deprimido\ne mudança de comportamento. Além disso, ele\napresentava dor óssea. Exames bioquímicos indicaram o nível de PTH 20 vezes acima do valor de\nreferência. A função renal mostrou-se preservada; SatO2 = 97% em ar ambiente; FC = 86 bpm; e\nPA = 120 mmHg x 84 mmHg. TC de pelve foi realizado, conforme imagem a seguir. A respeito\ndesse caso clínico e tendo em vista os conhecimentos médicos correlatos, julgue os itens a seguir.\nÉ importante avaliar a presença de fraturas vertebrais, bem como sintomas de compressão\nradicular.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-274368","number":"274368","sourceNumber":"274368","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Em relação às tireoidites, assinale a alternativa CORRETA.","options":{"A":"A tireoidite de Hashimoto é a forma mais comum, acometendo mais mulheres, entre 3?40 anos,\nsendo o evento laboratorial mais comum a presença de anticorpos antitireoglobulina.","B":"A tireoidite pós-parto é um quadro raro que ocorre nos primeiros dias pós-parto, de curta\nduração, autolimitado, sem necessidade de tratamento específico.","C":"A tireoidite de Quervain é um quadro inflamatório e autoimune da tireoide, geralmente\nautolimitado, mais frequente em mulheres, presumivelmente causado por infecção viral ou\npós-infecção viral.","D":"A tireoidite mais comum é de forma infecciosa, causada por bactérias gram-positivas, comum\nem pacientes previamente hígidos e com bom\nprognóstico.","E":"A tireoidite induzida por radiação é um quadro de ocorrência exclusiva de pacientes com terapia\nactínica para controle de tireotoxicose prévia e se manifesta como coma mixedematoso por perda\naguda da função tireoidiana."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-262130","number":"262130","sourceNumber":"262130","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Uma paciente de 36 anos de idade apresenta queixas de palpitação, tremores nas\nmãos e insônia. Relata que perdeu cerca de\n16 kg em três meses, mesmo tendo percebido\naumento da fome. Ao exame físico, a paciente encontra-se lúcida, com tremor, FC = 116 bpm; FR =\n14 irpm, SatO2 = 98% com aumento do volume cervical e temperatura axilar = 36,3 °C. Ela nega\ncomorbidades ou uso de medicações e suplementos. De antecedentes pessoais, refere apenas ser\ntabagista, fazendo uso de meio maço de cigarros ao dia. Em razão da queixa de palpitação da\npaciente, é feito um eletrocardiograma que revela uma taquicardia sinusal, sem outras alterações.\n\nConsiderando a principal hipótese diagnóstica desse caso clínico e os conhecimentos médicos\ncorrelatos, julgue o item a seguir. A paciente\napresenta um quadro de crise tireotóxica, devendo ser\nimediatamente encaminhada para a unidade de terapia intensiva e iniciada terapia com\nglicocorticoides em altas doses.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-262131","number":"262131","sourceNumber":"262131","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Uma paciente de 36 anos de idade apresenta queixas de palpitação, tremores nas\nmãos e insônia. Relata que perdeu cerca de\n16 kg em três meses, mesmo tendo percebido\naumento da fome. Ao exame físico, a paciente encontra-se lúcida, com tremor, FC = 116 bpm; FR =\n14 irpm, SatO2 = 98% com aumento do volume cervical e temperatura axilar = 36,3 °C. Ela nega\ncomorbidades ou uso de medicações e suplementos. De antecedentes pessoais, refere apenas ser\ntabagista, fazendo uso de meio maço de cigarros ao dia. Em razão da queixa de palpitação da\npaciente, é feito um eletrocardiograma que revela uma taquicardia sinusal, sem outras alterações.\n\nConsiderando a principal hipótese diagnóstica desse caso clínico e os conhecimentos médicos\ncorrelatos, julgue o item a seguir. Tendo em vista a principal hipótese diagnóstica, essa é uma\ndoença autoimune na qual TRAB estimula a produção e a liberação de hormônios tireoidianos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-262132","number":"262132","sourceNumber":"262132","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Uma paciente de 36 anos de idade apresenta queixas de palpitação, tremores nas\nmãos e insônia. Relata que perdeu cerca de\n16 kg em três meses, mesmo tendo percebido\naumento da fome. Ao exame físico, a paciente encontra-se lúcida, com tremor, FC = 116 bpm; FR =\n14 irpm, SatO2 = 98% com aumento do volume cervical e temperatura axilar = 36,3 °C. Ela nega\ncomorbidades ou uso de medicações e suplementos. De antecedentes pessoais, refere apenas ser\ntabagista, fazendo uso de meio maço de cigarros ao dia. Em razão da queixa de palpitação da\npaciente, é feito um eletrocardiograma que revela uma taquicardia sinusal, sem outras alterações.\n\nConsiderando a principal hipótese diagnóstica desse caso clínico e os conhecimentos médicos\ncorrelatos, julgue o item a seguir. A doença\nde Graves é a principal hipótese diagnóstica e é a\nsegunda principal causa de hipertireoidismo, tendo os nódulos autônomos como a causa principal.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-262133","number":"262133","sourceNumber":"262133","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Uma paciente de 36 anos de idade apresenta queixas de palpitação, tremores nas\nmãos e insônia. Relata que perdeu cerca de\n16 kg em três meses, mesmo tendo percebido\naumento da fome. Ao exame físico, a paciente encontra-se lúcida, com tremor, FC = 116 bpm; FR =\n14 irpm, SatO2 = 98% com aumento do volume cervical e temperatura axilar = 36,3 °C. Ela nega\ncomorbidades ou uso de medicações e suplementos. De antecedentes pessoais, refere apenas ser\ntabagista, fazendo uso de meio maço de cigarros ao dia. Em razão da queixa de palpitação da\npaciente, é feito um eletrocardiograma que revela uma taquicardia sinusal, sem outras alterações.\n\nConsiderando a principal hipótese diagnóstica desse caso clínico e os conhecimentos médicos\ncorrelatos, julgue o item a seguir. Betabloqueadores constituem-se em um dos tratamentos para\ncontenção de sintomas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-262134","number":"262134","sourceNumber":"262134","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Uma paciente de 36 anos de idade apresenta queixas de palpitação, tremores nas\nmãos e insônia. Relata que perdeu cerca de\n16 kg em três meses, mesmo tendo percebido\naumento da fome. Ao exame físico, a paciente encontra-se lúcida, com tremor, FC = 116 bpm; FR =\n14 irpm, SatO2 = 98% com aumento do volume cervical e temperatura axilar = 36,3 °C. Ela nega\ncomorbidades ou uso de medicações e suplementos. De antecedentes pessoais, refere apenas ser\ntabagista, fazendo uso de meio maço de cigarros ao dia. Em razão da queixa de palpitação da\npaciente, é feito um eletrocardiograma que revela uma taquicardia sinusal, sem outras alterações.\n\nConsiderando a principal hipótese diagnóstica desse caso clínico e os conhecimentos médicos\ncorrelatos, julgue o item a seguir. Tabagismo constitui fator de risco para desenvolvimento da\ndoença de Graves.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-262135","number":"262135","sourceNumber":"262135","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Uma paciente de 36 anos de idade apresenta queixas de palpitação, tremores nas\nmãos e insônia. Relata que perdeu cerca de\n16 kg em três meses, mesmo tendo percebido\naumento da fome. Ao exame físico, a paciente encontra-se lúcida, com tremor, FC = 116 bpm; FR =\n14 irpm, SatO2 = 98% com aumento do volume cervical e temperatura axilar = 36,3 °C. Ela nega\ncomorbidades ou uso de medicações e suplementos. De antecedentes pessoais, refere apenas ser\ntabagista, fazendo uso de meio maço de cigarros ao dia. Em razão da queixa de palpitação da\npaciente, é feito um eletrocardiograma que revela uma taquicardia sinusal, sem outras alterações.\n\nConsiderando a principal hipótese diagnóstica desse caso clínico e os conhecimentos médicos\ncorrelatos, julgue o item a seguir. Caso a paciente estivesse grávida, entre as drogas\nantitireoidianas, o metimazol deveria ser usado no primeiro trimestre e o propiltiouracil passaria a\nser a droga de escolha a partir do segundo trimestre.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-262136","number":"262136","sourceNumber":"262136","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Uma paciente de 52 anos de idade, cuja menopausa ocorreu aos 48 anos, sem\nreposição hormonal, comparece a consulta\nencaminhada pela ginecologia para avaliação, pois\napresentou nível elevado de cálcio em exames de rotina, com valor de cálcio = 11,2. Ao exame\nfísico, a paciente pesava 59 kg, com FC = 71 bpm, FR = 12 irpm, e SatO2 = 99%. Sem patologias\npreviamente conhecidas. Tendo em vista esse caso clínico e os conhecimentos médicos correlatos,\njulgue o item a seguir. A hipercalcemia deve ser confirmada com nova dosagem de cálcio, que deve\nser corrigida pelo valor da albumina sérica.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-262138","number":"262138","sourceNumber":"262138","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Uma paciente de 52 anos de idade, cuja menopausa ocorreu aos 48 anos, sem\nreposição hormonal, comparece a consulta\nencaminhada pela ginecologia para avaliação, pois\napresentou nível elevado de cálcio em exames de rotina, com valor de cálcio = 11,2. Ao exame\nfísico, a paciente pesava 59 kg, com FC = 71 bpm, FR = 12 irpm, e SatO2 = 99%. Sem patologias\npreviamente conhecidas. Tendo em vista esse caso clínico e os conhecimentos médicos correlatos,\njulgue o item a seguir. Em caso de PTH aumentado, a hipótese principal torna-se\nhiperparatireoidismo primário.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-262139","number":"262139","sourceNumber":"262139","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Uma paciente de 52 anos de idade, cuja menopausa ocorreu aos 48 anos, sem\nreposição hormonal, comparece a consulta\nencaminhada pela ginecologia para avaliação, pois\napresentou nível elevado de cálcio em exames de rotina, com valor de cálcio = 11,2. Ao exame\nfísico, a paciente pesava 59 kg, com FC = 71 bpm, FR = 12 irpm, e SatO2 = 99%. Sem patologias\npreviamente conhecidas. Tendo em vista esse caso clínico e os conhecimentos médicos correlatos,\njulgue o item a seguir. A tomografia de região cervical é o padrão-ouro para localizar as\nparatireoides e deve ser solicitada para o diagnóstico.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-262140","number":"262140","sourceNumber":"262140","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Uma paciente de 52 anos de idade, cuja menopausa ocorreu aos 48 anos, sem\nreposição hormonal, comparece a consulta\nencaminhada pela ginecologia para avaliação, pois\napresentou nível elevado de cálcio em exames de rotina, com valor de cálcio = 11,2. Ao exame\nfísico, a paciente pesava 59 kg, com FC = 71 bpm, FR = 12 irpm, e SatO2 = 99%. Sem patologias\npreviamente conhecidas. Tendo em vista esse caso clínico e os conhecimentos médicos correlatos,\njulgue o item a seguir. Em caso de PTH baixo, neoplasias devem fazer parte da investigação das\ncausas da hipercalcemia da paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-262141","number":"262141","sourceNumber":"262141","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Uma paciente de 52 anos de idade, cuja menopausa ocorreu aos 48 anos, sem\nreposição hormonal, comparece a consulta\nencaminhada pela ginecologia para avaliação, pois\napresentou nível elevado de cálcio em exames de rotina, com valor de cálcio = 11,2. Ao exame\nfísico, a paciente pesava 59 kg, com FC = 71 bpm, FR = 12 irpm, e SatO2 = 99%. Sem patologias\npreviamente conhecidas. Tendo em vista esse caso clínico e os conhecimentos médicos correlatos,\njulgue o item a seguir. Apesar de menos comuns, doenças granulomatosas devem ser investigadas\nna paciente, caso o PTH esteja baixo e seja descartada a presença de neoplasias.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-262142","number":"262142","sourceNumber":"262142","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Uma paciente de 79 anos de idade, com quadro de tosse secretiva há cerca de três\ndias, evolui agora com alteração do nível de\nconsciência. Tem história de hipotireoidismo desde os\n20 anos de idade, em tratamento com levotiroxina, atualmente com tratamento irregular, pois a\npaciente estava se esquecendo de fazer uso da medicação. Também é hipertensa e dislipidêmica\nem uso de losartana e rosuvastatina. Ao exame físico, encontra-se sonolenta, com pele seca e fria,\nPA = 82 mmHg x 58 mmHg; FC = 50 bpm; FR = 12 irpm e SatO2 = 95%. Apresenta edema em\npernas e no rosto. Constatam-se leucócitos = 19.300 com desvio; creatinina = 1,4 mg/dL; TSH = 61\nmUI/L (VR 0,4 a 6,4); e T4 livre = 0,5 (VR 0,8 ? 1,8). A respeito desse caso clínico e com base nos\nconhecimentos médicos correlatos, julgue o item a seguir. Apesar de grave, o quadro da paciente\nnão tem mortalidade elevada.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-262143","number":"262143","sourceNumber":"262143","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Uma paciente de 79 anos de idade, com quadro de tosse secretiva há cerca de três\ndias, evolui agora com alteração do nível de\nconsciência. Tem história de hipotireoidismo desde os\n20 anos de idade, em tratamento com levotiroxina, atualmente com tratamento irregular, pois a\npaciente estava se esquecendo de fazer uso da medicação. Também é hipertensa e dislipidêmica\nem uso de losartana e rosuvastatina. Ao exame físico, encontra-se sonolenta, com pele seca e fria,\nPA = 82 mmHg x 58 mmHg; FC = 50 bpm; FR = 12 irpm e SatO2 = 95%. Apresenta edema em\npernas e no rosto. Constatam-se leucócitos = 19.300 com desvio; creatinina = 1,4 mg/dL; TSH = 61\nmUI/L (VR 0,4 a 6,4); e T4 livre = 0,5 (VR 0,8 ? 1,8). A respeito desse caso clínico e com base nos\nconhecimentos médicos correlatos, julgue o item a seguir. O tratamento deve ser feito com medidas\nde suporte, aquecimento do corpo e uso de hormônio tireoidiano.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-262144","number":"262144","sourceNumber":"262144","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Uma paciente de 79 anos de idade, com quadro de tosse secretiva há cerca de três\ndias, evolui agora com alteração do nível de\nconsciência. Tem história de hipotireoidismo desde os\n20 anos de idade, em tratamento com levotiroxina, atualmente com tratamento irregular, pois a\npaciente estava se esquecendo de fazer uso da medicação. Também é hipertensa e dislipidêmica\nem uso de losartana e rosuvastatina. Ao exame físico, encontra-se sonolenta, com pele seca e fria,\nPA = 82 mmHg x 58 mmHg; FC = 50 bpm; FR = 12 irpm e SatO2 = 95%. Apresenta edema em\npernas e no rosto. Constatam-se leucócitos = 19.300 com desvio; creatinina = 1,4 mg/dL; TSH = 61\nmUI/L (VR 0,4 a 6,4); e T4 livre = 0,5 (VR 0,8 ? 1,8). A respeito desse caso clínico e com base nos\nconhecimentos médicos correlatos, julgue o item a seguir. O quadro apresentado geralmente é\nmais comum em mulheres e idosos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-262145","number":"262145","sourceNumber":"262145","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Uma paciente de 79 anos de idade, com quadro de tosse secretiva há cerca de três\ndias, evolui agora com alteração do nível de\nconsciência. Tem história de hipotireoidismo desde os\n20 anos de idade, em tratamento com levotiroxina, atualmente com tratamento irregular, pois a\npaciente estava se esquecendo de fazer uso da medicação. Também é hipertensa e dislipidêmica\nem uso de losartana e rosuvastatina. Ao exame físico, encontra-se sonolenta, com pele seca e fria,\nPA = 82 mmHg x 58 mmHg; FC = 50 bpm; FR = 12 irpm e SatO2 = 95%. Apresenta edema em\npernas e no rosto. Constatam-se leucócitos = 19.300 com desvio; creatinina = 1,4 mg/dL; TSH = 61\nmUI/L (VR 0,4 a 6,4); e T4 livre = 0,5 (VR 0,8 ? 1,8). A respeito desse caso clínico e com base nos\nconhecimentos médicos correlatos, julgue o item a seguir. Deve ser iniciado também antibiótico.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-262146","number":"262146","sourceNumber":"262146","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Uma paciente de 79 anos de idade, com quadro de tosse secretiva há cerca de três\ndias, evolui agora com alteração do nível de\nconsciência. Tem história de hipotireoidismo desde os\n20 anos de idade, em tratamento com levotiroxina, atualmente com tratamento irregular, pois a\npaciente estava se esquecendo de fazer uso da medicação. Também é hipertensa e dislipidêmica\nem uso de losartana e rosuvastatina. Ao exame físico, encontra-se sonolenta, com pele seca e fria,\nPA = 82 mmHg x 58 mmHg; FC = 50 bpm; FR = 12 irpm e SatO2 = 95%. Apresenta edema em\npernas e no rosto. Constatam-se leucócitos = 19.300 com desvio; creatinina = 1,4 mg/dL; TSH = 61\nmUI/L (VR 0,4 a 6,4); e T4 livre = 0,5 (VR 0,8 ? 1,8). A respeito desse caso clínico e com base nos\nconhecimentos médicos correlatos, julgue o item a seguir. A infecção pulmonar da paciente,\nembora agrave o conjunto dos sintomas, não está diretamente relacionada ao quadro apresentado\npor ela.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-262147","number":"262147","sourceNumber":"262147","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Uma paciente de 79 anos de idade, com quadro de tosse secretiva há cerca de três\ndias, evolui agora com alteração do nível de\nconsciência. Tem história de hipotireoidismo desde os\n20 anos de idade, em tratamento com levotiroxina, atualmente com tratamento irregular, pois a\npaciente estava se esquecendo de fazer uso da medicação. Também é hipertensa e dislipidêmica\nem uso de losartana e rosuvastatina. Ao exame físico, encontra-se sonolenta, com pele seca e fria,\nPA = 82 mmHg x 58 mmHg; FC = 50 bpm; FR = 12 irpm e SatO2 = 95%. Apresenta edema em\npernas e no rosto. Constatam-se leucócitos = 19.300 com desvio; creatinina = 1,4 mg/dL; TSH = 61\nmUI/L (VR 0,4 a 6,4); e T4 livre = 0,5 (VR 0,8 ? 1,8). A respeito desse caso clínico e com base nos\nconhecimentos médicos correlatos, julgue o item a seguir. Deve ser iniciado também corticoide.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-262160","number":"262160","sourceNumber":"262160","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Uma paciente de 33 anos de idade comparece a consulta com queixa de indisposição,\nsonolência, queda de cabelo, unhas\nquebradiças e retenção hídrica, e leva os exames solicitados\npor sua ginecologista, pois apresentava irregularidade menstrual. Os exames mostram TSH = 14\nmUI/mL e T4L = 0,54 ng/dL. Ao exame físico, verificaram-se pele seca, FC = 62 bpm, FR = 14 irpm,\ne SatO2 = 100%. A paciente tem discreto aumento do volume cervical. A respeito desse caso\nclínico e com base nos conhecimentos médicos correlatos, julgue o item a seguir. A tireoidite de\nHashimoto é a segunda causa mais frequente, de acordo com o quadro da paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-262161","number":"262161","sourceNumber":"262161","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Uma paciente de 33 anos de idade comparece a consulta com queixa de indisposição,\nsonolência, queda de cabelo, unhas\nquebradiças e retenção hídrica, e leva os exames solicitados\npor sua ginecologista, pois apresentava irregularidade menstrual. Os exames mostram TSH = 14\nmUI/mL e T4L = 0,54 ng/dL. Ao exame físico, verificaram-se pele seca, FC = 62 bpm, FR = 14 irpm,\ne SatO2 = 100%. A paciente tem discreto aumento do volume cervical. A respeito desse caso\nclínico e com base nos conhecimentos médicos correlatos, julgue o item a seguir. O excesso de\niodo pode causar hipotireoidismo transitório decorrente do efeito Wolff-Chaikoff, o que\njustificaria o\ncaso da paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-262162","number":"262162","sourceNumber":"262162","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Uma paciente de 33 anos de idade comparece a consulta com queixa de indisposição,\nsonolência, queda de cabelo, unhas\nquebradiças e retenção hídrica, e leva os exames solicitados\npor sua ginecologista, pois apresentava irregularidade menstrual. Os exames mostram TSH = 14\nmUI/mL e T4L = 0,54 ng/dL. Ao exame físico, verificaram-se pele seca, FC = 62 bpm, FR = 14 irpm,\ne SatO2 = 100%. A paciente tem discreto aumento do volume cervical. A respeito desse caso\nclínico e com base nos conhecimentos médicos correlatos, julgue o item a seguir. Durante a\ninvestigação, deve-se dosar anti-TPO e anti-Tg, esta última menos comum. Altos níveis de de\n\nanti-TPO indicam Hashimoto, mas não é patognomônico.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-262163","number":"262163","sourceNumber":"262163","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Uma paciente de 33 anos de idade comparece a consulta com queixa de indisposição,\nsonolência, queda de cabelo, unhas\nquebradiças e retenção hídrica, e leva os exames solicitados\npor sua ginecologista, pois apresentava irregularidade menstrual. Os exames mostram TSH = 14\nmUI/mL e T4L = 0,54 ng/dL. Ao exame físico, verificaram-se pele seca, FC = 62 bpm, FR = 14 irpm,\ne SatO2 = 100%. A paciente tem discreto aumento do volume cervical. A respeito desse caso\nclínico e com base nos conhecimentos médicos correlatos, julgue o item a seguir. Os valores de\nreferência do TSH não sofrem influência da idade da paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-262164","number":"262164","sourceNumber":"262164","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Uma paciente de 33 anos de idade comparece a consulta com queixa de indisposição,\nsonolência, queda de cabelo, unhas\nquebradiças e retenção hídrica, e leva os exames solicitados\npor sua ginecologista, pois apresentava irregularidade menstrual. Os exames mostram TSH = 14\nmUI/mL e T4L = 0,54 ng/dL. Ao exame físico, verificaram-se pele seca, FC = 62 bpm, FR = 14 irpm,\ne SatO2 = 100%. A paciente tem discreto aumento do volume cervical. A respeito desse caso\nclínico e com base nos conhecimentos médicos correlatos, julgue o item a seguir. A irregularidade\nmenstrual pode ser causada por alteração da função tireoidiana.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-262165","number":"262165","sourceNumber":"262165","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Uma paciente de 33 anos de idade comparece a consulta com queixa de indisposição,\nsonolência, queda de cabelo, unhas\nquebradiças e retenção hídrica, e leva os exames solicitados\npor sua ginecologista, pois apresentava irregularidade menstrual. Os exames mostram TSH = 14\nmUI/mL e T4L = 0,54 ng/dL. Ao exame físico, verificaram-se pele seca, FC = 62 bpm, FR = 14 irpm,\ne SatO2 = 100%. A paciente tem discreto aumento do volume cervical. A respeito desse caso\nclínico e com base nos conhecimentos médicos correlatos, julgue o item a seguir. O tratamento\ndeve ser feito com levotiroxina, na dose inicial de 1 mcg por quilo da paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-262178","number":"262178","sourceNumber":"262178","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Certo paciente de 35 anos de idade relata estar notando aumento de mãos e pés,\nalargamento do nariz e lábios, e\nproeminência frontal da face e da mandíbula. Refere que alguns\ncalçados não estão servindo mais e também se queixa de dores articulares, episódios de cefaleia e\nfadiga. Em relação a esse caso clínico e com base nos conhecimentos médicos correlatos, julgue o\nitem a seguir. A principal hipótese diagnóstica é doença causada por adenoma hipofisário secretor\nde GH na maioria dos casos. Os demais casos são decorrentes de secreção hipotalâmica de\nhormônio liberador de hormônio do crescimento (GHRH) ou de secreção ectópica de GH ou de\nGHRH.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-262179","number":"262179","sourceNumber":"262179","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Certo paciente de 35 anos de idade relata estar notando aumento de mãos e pés,\nalargamento do nariz e lábios, e\nproeminência frontal da face e da mandíbula. Refere que alguns\ncalçados não estão servindo mais e também se queixa de dores articulares, episódios de cefaleia e\nfadiga. Em relação a esse caso clínico e com base nos conhecimentos médicos correlatos, julgue o\nitem a seguir. Devem ser feitas dosagens de GH e IGF-1. Os valores de GH são mais estáveis do\nque os de IGF-1, não são pulsáteis e são mais confiáveis e fidedignos para avaliar a atividade da\ndoença.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-262180","number":"262180","sourceNumber":"262180","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Certo paciente de 35 anos de idade relata estar notando aumento de mãos e pés,\nalargamento do nariz e lábios, e\nproeminência frontal da face e da mandíbula. Refere que alguns\ncalçados não estão servindo mais e também se queixa de dores articulares, episódios de cefaleia e\nfadiga. Em relação a esse caso clínico e com base nos conhecimentos médicos correlatos, julgue o\nitem a seguir. A enfermidade pode fazer parte da neoplasia endócrina múltipla tipo 1 (NEM-1).","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-262181","number":"262181","sourceNumber":"262181","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Certo paciente de 35 anos de idade relata estar notando aumento de mãos e pés,\nalargamento do nariz e lábios, e\nproeminência frontal da face e da mandíbula. Refere que alguns\ncalçados não estão servindo mais e também se queixa de dores articulares, episódios de cefaleia e\nfadiga. Em relação a esse caso clínico e com base nos conhecimentos médicos correlatos, julgue o\nitem a seguir. O tratamento de escolha deve ser o cirúrgico, sendo esse o padrão-ouro.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-262182","number":"262182","sourceNumber":"262182","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Certo paciente de 35 anos de idade relata estar notando aumento de mãos e pés,\nalargamento do nariz e lábios, e\nproeminência frontal da face e da mandíbula. Refere que alguns\ncalçados não estão servindo mais e também se queixa de dores articulares, episódios de cefaleia e\nfadiga. Em relação a esse caso clínico e com base nos conhecimentos médicos correlatos, julgue o\nitem a seguir. Esse paciente tem chance aumentada de ter pólipos colônicos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-262183","number":"262183","sourceNumber":"262183","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Certo paciente de 35 anos de idade relata estar notando aumento de mãos e pés,\nalargamento do nariz e lábios, e\nproeminência frontal da face e da mandíbula. Refere que alguns\ncalçados não estão servindo mais e também se queixa de dores articulares, episódios de cefaleia e\nfadiga. Em relação a esse caso clínico e com base nos conhecimentos médicos correlatos, julgue o\nitem a seguir. O tratamento medicamentoso pode ser realizado com somatropina.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-250085","number":"250085","sourceNumber":"250085","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"A insuficiência adrenal é um distúrbio caracterizado por alteração da função\nadrenocortical normal. Considerando essa\ninformação, julgue o item a seguir. Hiponatremia e\nhipercalemia são achados laboratoriais clássicos na insuficiência adrenal.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-255728","number":"255728","sourceNumber":"255728","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Um paciente de 12 anos de idade vai ao pediatra em razão de sua mãe querer fazer\numa avaliação anual com exames. Dessa vez, o\npediatra solicitou hormônio do crescimento sérico\n(GH), que veio uma vez e meio aumentado, acima dos valores de referência. O paciente faz\natividades físicas regulares e não apresenta alteração estrutural. Esse paciente tinha suspeita de\nsíndrome de West, mas esta foi descartada. Considerando esse caso clínico e os conhecimentos\nmédicos correlatos, julgue o item a seguir. Níveis aumentados de GH são normais em exercícios\nfísicos ou uma hora após o início de sono profundo.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-255729","number":"255729","sourceNumber":"255729","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Um paciente de 12 anos de idade vai ao pediatra em razão de sua mãe querer fazer\numa avaliação anual com exames. Dessa vez, o\npediatra solicitou hormônio do crescimento sérico\n(GH), que veio uma vez e meio aumentado, acima dos valores de referência. O paciente faz\natividades físicas regulares e não apresenta alteração estrutural. Esse paciente tinha suspeita de\nsíndrome de West, mas esta foi descartada. Considerando esse caso clínico e os conhecimentos\nmédicos correlatos, julgue o item a seguir. Em geral, a secreção de GH é maior em mulheres do\nque em homens.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-255753","number":"255753","sourceNumber":"255753","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Uma gestante de 12 semanas vai a consulta assintomática. Apresenta sorologias\nnegativas do primeiro trimestre, um TSH de\n6,25 mU/L (VR 0,3 e 4,0 mU/L) e um T4 livre de 0,9\nmU/L. Seu anti-TPO era positivo (3x acima do valor da normalidade). Acerca desse caso clínico e\ncom base nos conhecimentos médicos correlatos, julgue o item a seguir. Essa gestante apresenta\nrisco aumentado de pré-eclâmpsia.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-179182","number":"179182","sourceNumber":"179182","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Assinale a alternativa que apresenta a patologia que acomete indivíduos acima de\ncinquenta anos de idade, principalmente\nmulheres, devido ao uso de hipolipemiantes nesses casos\nassociar-se ao risco elevado de miopatia.","options":{"A":"diabetes","B":"hipertensão arterial","C":"angina instável","D":"hipotireoidismo","E":"obesidade mórbida"},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-179203","number":"179203","sourceNumber":"179203","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Um RN do sexo feminino apresenta sinais de virilização da genitália externa, traduzida\npor aumento de clitóris, fusão labial e formação\nde seio urogenital. Nessa situação hipotética, o\nprincipal distúrbio metabólico a ser monitorado será a:","options":{"A":"Hipoglicemia.","B":"Hipopotassemia.","C":"Hiponatremia.","D":"Hipocalcemia.","E":"Hipomagnesemia."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-179208","number":"179208","sourceNumber":"179208","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Uma paciente de 46 anos de idade foi submetida a uma avaliação geral de saúde\ndevido à queixa de fraqueza e fadigas\nfrequentes. Nega comorbidades prévias, alcoolismo,\ntabagismo e uso de drogas ilícitas. Ao exame físico, não apresentava alterações dignas de nota. À\navaliação laboratorial, foi evidenciado cálcio sérico de 12,1 mg/dl (8,4 a 10,4 mg/dl), fosfato\nsérico\nde 1,8 ml/dl (2,5 a 4,8 mg/dl) e cloreto sérico de 104 mmol/L. O hemograma, o restante da\navaliação laboratorial, o EAS, a radiografia de tórax e o eletrocardiograma de doze derivações\nvieram normais. Com base nesse caso hipotético, assinale a alternativa CORRETA:","options":{"A":"O diagnóstico da paciente é doença de Paget e a confirmação diagnóstica pode ser realizada\npela presença de PTHi sérico reduzido.","B":"É importante solicitar uma amostra de urina de 24 horas e, em caso de baixa concentração de\ncálcio urinário, pensar na hipótese de Hipercalcemia Hipocalciúrica Familiar Benigna (HHFB) e\nindicar paratireoidectomia.","C":"A paratireoidectomia é o melhor tratamento para a paciente e deverá ser realizada quando seu\nnível sérico de cálcio atingir 15 mg/dl.","D":"As glândulas paratireoides estão situadas na face posterior da tireoide, não sendo\nrecomendados os exames de imagem para localização pré-operatória.","E":"Na presença de PTH elevado e na ausência de padrão familiar de hipercalcemia, estão\nindicadas a localização e a exploração cirúrgica das paratireoides."},"answer":"E","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-152125","number":"152125","sourceNumber":"152125","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente do sexo feminino, 20 anos de idade, relata que, há três semanas, está com\nhipertensão refratária à terapêutica medicamentosa otimizada. Refere que apresenta cansaço\nextremo durante o dia, além de palpitações, cefaleia e sudorese. No momento da consulta, sua\npressão é de 160 x 100 mmHg. Foram solicitadas catecolaminas urinárias que apresentaram valor\nacima da normalidade. Considerando esse caso clínico, julgue o item a seguir. Feocromocitoma\nassociado à neoplasia endócrina múltipla 2A tem relação com carcinoma medular de tireoide.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-134972","number":"134972","sourceNumber":"134972","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"No que se refere ao câncer de esôfago, cirrose e doença de Crohn, julgue o item\nsubsecutivo. Se a ressonância magnética de abdome revelar a presença de nódulo sólido\nhomogêneo de 3 centímetros de diâmetro na glândula suprarrenal esquerda, existe indicação de\nadrenalectomia, mesmo na ausência de produção hormonal associada.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-105573","number":"105573","sourceNumber":"105573","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Os transtornos congênitos da tireoide são de elevada importância na pediatria, uma vez\nque os hormônios tireoidianos são\nfundamentais para o crescimento e desenvolvimento normal. Em\nrelação às causas e ao diagnóstico dessa patologia, é correto afirmar que:","options":{"A":"crianças com hipotireoidismo congênito, na maioria das vezes, apresentam baixo peso e (ou)\nbaixa estatura, pois a deficiência desses hormônios interfere no desenvolvimento fetal.","B":"a triagem neonatal deve ser realizada pela dosagem inicial de TSH, após 48 horas de vida, em\npapel de filtro por punção do calcanhar, seguida da dosagem de T4 nos casos em que o TSH\nestiver abaixo do percentil 50.","C":"a principal causa do hipotireoidismo congênito é a tireoidite, por isso devem ser pesquisados\nanticorpos na mãe em casos suspeitos.","D":"O hipertireoidismo congênito, devido às tireoidites maternas, é tão frequente quanto o\nhipotireoidismo, apesar de ser pouco diagnosticado, pois os sintomas manifestam-se em longo\nprazo e são confundidos com transtornos mentais, como a hiperatividade.","E":"o hipotireoidismo congênito é uma das principais causas evitáveis de deficiência mental."},"answer":"E","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-105531","number":"105531","sourceNumber":"105531","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Assinale a alternativa que apresenta a afecção patológica que melhor se relaciona com\na seguinte descrição: \"fenômeno imunológico\nque resulta na formação de complexo imune e de\ncomplemento na membrana basal das células foliculares e que leva a alterações da função da\ncélula tireoidiana e promove a produção de anticorpos microssomais tireóideos\".","options":{"A":"Tireoidite de Hashimoto.","B":"Doença de Graves.","C":"Doença de Plummer.","D":"Tireoidite de Riedel.","E":"Tireoidite supurativa aguda."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-108176","number":"108176","sourceNumber":"108176","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Julgue o item a seguir, relativo à deficiência de crescimento do corpo. Diversos genes\nresponsáveis por codificar fatores de transcrição estão implicados na etiologia da deficiência\ncombinada dos hormônios hipofisários (pan-hipopituitarismo), sendo o gene PROP-1 o mais\nfrequentemente envolvido.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-88722","number":"88722","sourceNumber":"88722","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Julgue o item seguinte com relação ao hipotireoidismo. Mesmo que ocorra uma melhora\nclínica de paciente com hipotireoidismo após o período de duas a três semanas de terapêutica,\nrecomenda-se a medida do TSH sérico depois de seis semanas de início do tratamento regular\npara uma nova reavaliação e subsequente reajuste de dose, se necessário.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-88731","number":"88731","sourceNumber":"88731","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Julgue o item seguinte com relação ao hipotireoidismo. Pacientes cujo hipotireoidismo é\nresultante de tireoidite crônica autoimune podem necessitar de doses mais altas de levotiroxina\npara a normalização do quadro.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-27542","number":"27542","sourceNumber":"27542","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"A tireoidite de Riedel pode se associar com uma das afecções citadas abaixo.\nAssinale-a.","options":{"A":"Colangite esclerosante.","B":"Ginecomastia.","C":"Tumor retroperitonial.","D":"Insulinoma.","E":"Esofagite de refluxo."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-27548","number":"27548","sourceNumber":"27548","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"A neoplasia endócrina múltipla do tipo I (NEM I), caracteriza-se pela ocorrência\nsimultânea de:","options":{"A":"feocromocitoma, hiperplasia da paratireoide e adenomas hipofisários.","B":"tumor medular da tireoide, feocromocitoma e insulinoma.","C":"adenomas hipofisários, tumor medular da tireoide e feocromocitoma.","D":"insulinoma, adenomas hipofisários e neuromas mucosos.","E":"hiperplasia da paratireoide, tumor das ilhotas pancreáticas e adenomas hipofisários."},"answer":"E","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-352369","number":"352369","sourceNumber":"352369","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Um homem de 55 anos foi encaminhado ao ambulatório de Cirurgia devido a uma\nalteração abdominal identificada. Anteriormente,\nestava em boa saúde, mas começou a\nexperienciar fraqueza muscular generalizada de forma insidiosa, ocasionalmente acompanhada por\ncâimbras. Além disso, relata que sua urina, por vezes, apresenta uma coloração acastanhada. Os\nexames laboratoriais revelaram uma urina de tipo I com presença de hemossiderinúria e níveis de\ncreatina fosfoquinase de 2.000 U/L (valor de referência: 22 - 334 U/L). Uma anomalia na imagem\nabdominal está evidente na seta e na cabeça de seta na figura abaixo. Considerando o quadro\nclínico hipotético apresentado, julgue o item a seguir. Na condição apresentada, dependendo da\nrapidez com que ocorre o desequilíbrio hidroeletrolítico predominante, é possível que se desenvolva\numa paralisia ascendente, que se assemelha à Síndrome de Guillain-Barré.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-352368","number":"352368","sourceNumber":"352368","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Um homem de 55 anos foi encaminhado ao ambulatório de Cirurgia devido a uma\nalteração abdominal identificada. Anteriormente,\nestava em boa saúde, mas começou a\nexperienciar fraqueza muscular generalizada de forma insidiosa, ocasionalmente acompanhada por\ncâimbras. Além disso, relata que sua urina, por vezes, apresenta uma coloração acastanhada. Os\nexames laboratoriais revelaram uma urina de tipo I com presença de hemossiderinúria e níveis de\ncreatina fosfoquinase de 2.000 U/L (valor de referência: 22 - 334 U/L). Uma anomalia na imagem\nabdominal está evidente na seta e na cabeça de seta na figura abaixo. Considerando o quadro\nclínico hipotético apresentado, julgue o item a seguir. Mutações somáticas do trocador no gene do\ncanal de potássio pode ser a causa de quase metade dos casos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-352367","number":"352367","sourceNumber":"352367","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Um homem de 55 anos foi encaminhado ao ambulatório de Cirurgia devido a uma\nalteração abdominal identificada. Anteriormente,\nestava em boa saúde, mas começou a\nexperienciar fraqueza muscular generalizada de forma insidiosa, ocasionalmente acompanhada por\ncâimbras. Além disso, relata que sua urina, por vezes, apresenta uma coloração acastanhada. Os\nexames laboratoriais revelaram uma urina de tipo I com presença de hemossiderinúria e níveis de\ncreatina fosfoquinase de 2.000 U/L (valor de referência: 22 - 334 U/L). Uma anomalia na imagem\nabdominal está evidente na seta e na cabeça de seta na figura abaixo. Considerando o quadro\nclínico hipotético apresentado, julgue o item a seguir. Após um rastreamento positivo, quando a\ntomografia de cortes finos revela uma massa unilateral com mais de 1,0 cm em pacientes com\nidade igual ou inferior a 40 anos, sem alteração contralateral de mesma topografia, a intervenção\ncirúrgica é recomendada.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-352366","number":"352366","sourceNumber":"352366","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Um homem de 55 anos foi encaminhado ao ambulatório de Cirurgia devido a uma\nalteração abdominal identificada. Anteriormente,\nestava em boa saúde, mas começou a\nexperienciar fraqueza muscular generalizada de forma insidiosa, ocasionalmente acompanhada por\ncâimbras. Além disso, relata que sua urina, por vezes, apresenta uma coloração acastanhada. Os\nexames laboratoriais revelaram uma urina de tipo I com presença de hemossiderinúria e níveis de\ncreatina fosfoquinase de 2.000 U/L (valor de referência: 22 - 334 U/L). Uma anomalia na imagem\nabdominal está evidente na seta e na cabeça de seta na figura abaixo. Considerando o quadro\nclínico hipotético apresentado, julgue o item a seguir. Em situações específicas, a realização de\ncateterismo da veia suprarrenal pode ser necessária para confirmar a lateralização e, assim,\norientar a decisão terapêutica, que pode incluir tratamento medicamentoso.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-334881","number":"334881","sourceNumber":"334881","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Um paciente de 35 anos de idade, assintomático, procurou atendimento médico para\nrealizar seu exame anual periódico exigido pela empresa em que trabalha. No exame físico,\nidentificou-se tireoide palpável com consistência lisa e elástica, não havendo relato de dor à\npalpação. A avaliação da função tireoidiana mostrou TSH, aumentado com T4 livre normal. Que\nachado laboratorial confirma o provável diagnóstico desse paciente?","options":{"A":"Leucocitose com desvio à esquerda","B":"Nível de T3 aumentado","C":"Nódulo hipocaptante de tireoide","D":"Presença de anticorpo antitireoperoxidase","E":"Aumento do colesterol total"},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-301244","number":"301244","sourceNumber":"301244","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Uma paciente de 53 anos de idade, obesa, portadora de diabetes mellitus tipo 2,\nprocurou atendimento médico com resultado de\nexame laboratorial mostrando valor sérico reduzido\nde 25 hidroxi-vitamina D. A paciente negou sintomas e relatou estar em uso de orlistate 120 mg\n(três vezes ao dia) há seis meses, além de metformina, 1 g ao dia, há cinco anos. Com base nesse\ncaso hipotético, considerando o posicionamento da Sociedade Brasileira de Endocrinologia e\nMetabologia, julgue os itens de 1 a 3. O orlistate utilizado pela paciente pode causar\nhipovitaminose\nD pelo aumento da degradação da vitamina D e de seus metabólitos ao ativar as enzimas\nlisossomais hepáticas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-301245","number":"301245","sourceNumber":"301245","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Uma paciente de 53 anos de idade, obesa, portadora de diabetes mellitus tipo 2,\nprocurou atendimento médico com resultado de\nexame laboratorial mostrando valor sérico reduzido\nde 25 hidroxi-vitamina D. A paciente negou sintomas e relatou estar em uso de orlistate 120 mg\n(três vezes ao dia) há seis meses, além de metformina, 1 g ao dia, há cinco anos. Com base nesse\ncaso hipotético, considerando o posicionamento da Sociedade Brasileira de Endocrinologia e\nMetabologia, julgue os itens de 1 a 3. A deficiência de vitamina D da paciente pode estar\nacompanhada da elevação da concentração sérica de paratormônio, o que aumenta o risco de\nfraturas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-301246","number":"301246","sourceNumber":"301246","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Uma paciente de 53 anos de idade, obesa, portadora de diabetes mellitus tipo 2,\nprocurou atendimento médico com resultado de\nexame laboratorial mostrando valor sérico reduzido\nde 25 hidroxi-vitamina D. A paciente negou sintomas e relatou estar em uso de orlistate 120 mg\n(três vezes ao dia) há seis meses, além de metformina, 1 g ao dia, há cinco anos. Com base nesse\ncaso hipotético, considerando o posicionamento da Sociedade Brasileira de Endocrinologia e\nMetabologia, julgue os itens de 1 a 3. Em casos de deficiência grave de vitamina D, ocorrem\nhipercalcemia e sintomas relacionados, como náuseas, vômitos, fraqueza, anorexia e desidratação.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-274590","number":"274590","sourceNumber":"274590","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Homem, 43 anos, hipertenso, com feocromocitoma suprarrenal devido a neoplasia\nendócrina múltipla 2. Nesse caso, o tratamento de escolha é a ressecção cirúrgica do tumor.\n\nQuanto ao uso dos betabloqueadores, é CORRETO afirmar:","options":{"A":"São os medicamentos de escolha para o controle da frequência cardíaca.","B":"São os medicamentos de escolha para o controle da PA antes da cirurgia.","C":"Devem ser sempre adicionados antes do uso de alfabloqueadores, isolados, para não\ndesencadearem crises hipertensivas.","D":"Sempre devem ser associados ao uso de diuréticos, para não agravar a hipotensão postural\ncausada pelos alfabloqueadores."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-291476","number":"291476","sourceNumber":"291476","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Uma mulher de 30 anos de idade vem a consulta com o endocrinologista para\nacompanhamento de hipotireoidismo. Há 6\nmeses ela procurou o médico da Unidade Básica de\nSaúde próxima a sua residência devido a constipação (evacuava a cada 3 dias, com fezes\nressecadas e com dor ao evacuar). A paciente era sedentária e apresentava erros alimentares\nevidentes, com baixa ingesta de água durante o dia e pouco consumo de frutas e verduras. O\nmédico orientou ajustes na alimentação, ingesta hídrica e necessidade de atividade física regular,\nassim como dosagem de TSH e T4 livre. Após 2 meses a paciente retornou, tendo aderido às\nrecomendações, resultando na solução do quadro de constipação (evacuava diariamente, sem dor,\ncom fezes bem formadas), contudo, os exames laboratoriais demonstraram: TSH=5,5mUI/mL (valor\nde referência: 0,4 a 4, 5mUI/mL) e T4 livre =1,0 (valor de referência 0,7 a 1,8 ng/dL). O médico\nrepetiu os exames que indicaram TSH = 5,3mUI/mL (valor de referência: 0,4 a 4, 5mUI/mL) e T4\nlivre = 1,1 (valor de referência 0,7 a 1,8 ng/dL). Diante da persistência dos exames alterados, o\nmédico prescreveu levetiroxina 50mcg/dia e encaminhou ao especialista. Durante a consulta com o\nendocrinologista, a paciente está assintomática, com tireoide não palpável e índice de massa\ncorpórea 22kg/m², contudo, não havia iniciado a levotiroxina, pois possuía receio de possíveis\nefeitos adversos. Considerando o que foi apresentado, o endocrinologista deve","options":{"A":"Insistir com o uso da levotiroxina, pois trata-se de um caso de hipotireoidismo primário.","B":"Insistir com o uso da levotiroxina, pois trata-se de um caso de hipotireoidismo secundário.","C":"Orientar não usar a levotiroxina, pois trata-se de um caso de hipotireoidismo subclínico.","D":"Iniciar a levotiroxina apenas após realizar cintilografia, para confirmação do diagnóstico."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-291494","number":"291494","sourceNumber":"291494","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Mulher, 26 anos de idade, usou pílula contraceptiva por 6 anos e interrompeu há cerca\nde 9 meses. Desde então, menstruou apenas 2\nvezes e está há 4 meses em amenorreia. Nega\nfogachos, acne, hirsutismo ou ressecamento vaginal. Ao exame físico: bom estado geral,\nhemodinamicamente estável, mamas com glactorreia bilateral, sem nódulos palpáveis. Útero de\ntamanho normal e anexos não palpáveis. Beta-hCG negativo. Para elucidação diagnóstica, deve-se\nsolicitar dosagem de","options":{"A":"estradiol.","B":"progesterona.","C":"prolactina.","D":"testosterona."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-291509","number":"291509","sourceNumber":"291509","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Mulher de 38 anos foi internada na enfermaria de clínica médica de hospital\nuniversitário de ampla complexidade, em\nfunção de quadro de fibrilação atrial paroxística com alta\nresposta ventricular, sem instabilidade hemodinâmica, mas associada a queixas recentes de\nemagrecimento não intencional, irritabilidade e tremores finos de extremidades. Na anamnese\ndirigida, a paciente confirmava a presença de intolerância ao calor, fadiga, fraqueza, amenorreia e\nhiperdefecação. Ao exame físico, além da taquiarritmia, foram observados bócio difuso (com sopro\nà ausculta local), exoftalmia, tremores palpebrais frequentes, mixedema pré-tibial e sobre o hálux\ndireito, hipocratismo digital e pele quente e úmida. Administradas duas doses sequenciais, com\nintervalos de 5 minutos, de metoprolol intravenoso (5 mg), após redução da frequência cardíaca,\nocorreu reversão da arritmia para o ritmo sinusal. Solicitados exames complementares, resultados\nrevelaram TSH < 0,004 mUl/L (valor de referência: 0,5 a 4,5 mUl/L) e T4 livre = 4,2 ng/dL (valor de\nreferência: 0,9 a 2,0 ng/dL). Além de ser mantido o tratamento com beta-bloqueador, considerando\no fato de a paciente nunca ter sido previamente tratada de sua doença, a equipe médica optou por\ninstituir terapêutica direcionada à inibição da função da enzima tireoperoxidase, reduzindo a\noxidação e organificação do iodo na tireoide, além de promover a redução dos níveis de\nautoanticorpos circulantes. A intervenção terapêutica instituída nesse sentido foi","options":{"A":"radioiodo.","B":"dexametasona.","C":"metimazol.","D":"colestiramina."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-244459","number":"244459","sourceNumber":"244459","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Uma paciente de 42 anos de idade é submetida a tireoidectomia total, em razão de\nnódulo, com punção aspirativa com agulha fina (PAAF) compatível com tumor indiferenciado de\ntireoide. No segundo dia pós-operatório, refere que, ao medir a pressão arterial, passou a\napresentar espasmos na musculatura da mão. Acerca desse caso clínico, assinale a alternativa\ncorrespondente ao achado descrito pela paciente e aos cuidados que se devem ser seguidos.","options":{"A":"Sinal de Trousseau; solicitar cálcio e ECG.","B":"Sinal de Hertoghe; solicitar TSH e T4.","C":"Sinal de Chvostek; solicitar cálcio sérico.","D":"Sinal de Von Graefe; solicitar potássio e sódio séricos.","E":"Sinal de Dalrymple; solicitar T4 livre e T3."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-244476","number":"244476","sourceNumber":"244476","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Um paciente de 42 anos de idade, com história de melanoma metastático em remissão\nda doença após início do tratamento\noncológico, procurou o serviço do pronto-socorro com um\nquadro de náusea, vômitos e ansiedade intratáveis. Ela havia iniciado terapia dupla com\nnivolumabe e ipilimumabe há um mês, e sua última dose foi há uma semana. Ela negou uso de\nálcool ou drogas ilícitas. Na apresentação, estava febril a 38 ºC, com FC = 146 bpm, FR = 18 irpm,\nSatO2 = 98% em ar ambiente e PA = 140 mmHg x 100 mmHg. Ao exame, a paciente estava\nagitada e extremamente ansiosa, com exoftalmia leve, mas acordada, alerta e orientada, sem\ndistensão venosa jugular, sem edema periférico, com exame cardíaco normal e sons claros ao\nexame pulmonar. O hemograma inicial completo, o painel metabólico básico, a lipase, a função\nrenal, o ácido úrico e o exame de urina estavam normais. O teste de gravidez foi negativo. As\nhemoculturas foram obtidas e mostraram-se negativas às 48 horas. Um eletrocardiograma mostrou\ntaquicardia sinusal. Os testes de função tireoidiana foram: TSH = 0,062 µU/mL (VR = 0,5 a 5,4) e\nT4 livre = 16,4 ng/dL (variação normal de 1,5 a 3,5 ng/dL). Um ultrassom da tireoide revelou\nheterogeneidade difusa da tireóide consistente com tireoidite inespecífica. Acerca desse caso\nclínico e tendo em vista os conhecimentos médicos correlatos, assinale a alternativa correta.","options":{"A":"A paciente manifesta quadro de choque séptico após tratamento oncológico. A sepse ocasiona\ndiminuição dos níveis séricos do hormônio tireoidiano e menor liberação de catecolaminas.","B":"A paciente tem quadro de reação de liberação de citoquinas, induzida pelos inibidores de TNF\nalfa (ipilimumab), com supressão transitória da função tireoideana.","C":"O nivolumabe e o ipilimumab são inibidores de TNF alfa; assim, o quadro clínico da paciente é\ncompatível com síndrome de lise tumoral.","D":"As manifestações clínicas da paciente são compatíveis com um quadro de insuficiência adrenal\naguda secundária ao tratamento oncológico.","E":"A paciente apresenta quadro de tempestade tireoideana e deve iniciar com propranolol 60 mg a\ncada seis horas, para obter controle\nadequado da frequência cardíaca, hidrocortisona 100 mg a\ncada oito horas e metimazol 20 mg a cada oito horas."},"answer":"E","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-230578","number":"230578","sourceNumber":"230578","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Durante o atendimento de um paciente com Síndrome de Down e obesidade,\n\nobserva-se um resultado de TSH de 6,5. Ele já apresentou, em outros momentos da vida, elevação\ndo TSH, com normalização dos resultados em\nexames subsequentes e sempre com dosagem de\nT4 livre normal. Qual é a MELHOR conduta em relação à avaliação tireoidiana desse paciente?","options":{"A":"Encaminhar ao endocrinologista.","B":"Nova dosagem de TSH, T4 livre e pesquisa do anticorpo Antitireoperoxidase (ATPO).","C":"Iniciar levotiroxina.","D":"Parar de dosar o TSH desse paciente, já que se encontra repetidamente elevado sem impacto\nclínico e com dosagem do T4 normal."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-212129","number":"212129","sourceNumber":"212129","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Caso clínico: paciente sem doenças prévias; idade: 19 anos; sexo: feminino; sinais e\nsintomas: tremores nas extremidades, nervosismo e palpitações taquicárdicas (FC = 15 bpm; PA =\n135 mmHg x 65 mmHg, pulsos radiais palpáveis e arrítmicos). Avaliação cardiovascular evidenciou\nictus cordis in situ, ritmo cardíaco irregular em 2 tempos, taquicárdico, bulhas normofonéticas, sem\nsopros ou ruídos adventícios. Na palpação, percebeu-se glândula tireoide indolor, levemente\naumentada e não nodular. Resultado de dosagem séricas: TSH (tirotrofina) = 0,05 mU/L (valores de\nreferência = 0,4-4,2 mU/L); T4 livre (tiroxina livre) = 4,0 nanogramas/dl (valores de referência =\n\n0,8-2,7 nanograma/dl); anticorpos antirreceptor de TSH (ou Trab) = 2 U/L (valor de referência < 10\nU/L); anticorpos antitireoglobulinas = positivo 1/6.400 (valores de referência não reagente <\n1/100);\ndeterminação de anticorpos antiperoxidase tireoidiana (anti-TPO) = 70 U/ml (valores de referência <\n35 U/ml). Ecodopplercardiograma = normal. Tira de ritmo eletrocardiográfico (ECG) mostrada na\nfigura a seguir (derivação D2, velocidade do papel: 25 mm/s, calibração: 1 cm= 1 mV). A respeito\ndas informações do caso clínico descrito anteriormente, julgue o item subsequente. O principal\ndiagnóstico clínico é tireoidite de Hashimoto.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-212132","number":"212132","sourceNumber":"212132","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Caso clínico - paciente sem doenças prévias; Idade: 19 anos: sexo: feminino; Sinais e\nsintomas: tremores nas extremidades, nervosismo e palpitações taquicárdicas (FC = 15 bpm, PA\n135 mmHg x 65 mmHg, pulsos radiais palpáveis e arrítmicos); Avaliação cardiovascular evidenciou\nictus cordis in situ, ritmo cardíaco irregular em 2 tempos, taquicárdico, bulhas normofonéticas, sem\nsopros ou ruídos adventícios. Na palpação, percebeu-se glândula tireoide indolor, levemente\naumentada e não nodular. Resultado de dosagem séricas: TSH (tirotrofina) = 0,05 mU/L (valores de\nreferência = 0,4 - 4,2 mU/L); T4 livre (tiroxina livre) = 4,0 nanogramas/dL (valores de referência =\n0,8 - 2,7 nanograma/dL); anticorpos antirreceptor de TSH (ou Trab) = 2 U/L (valor de referência <\n10 U/L); anticorpos antitireoglobulinas = positivo 1/6.400 ( valores de referência não reagente <\n1/100); determinação de anticorpos antiperoxidase tireoidiana (anti-TPO) = 70 U/mL (valores de\nreferência < 35 U/mL). Ecodopplercardiograma = normal. Tira de ritmo eletrocardiográfico (ECG)\nmostrada na figura a seguir (derivação D2, velocidade do papel: 25 mm/s, calibração: 1 cm= 1 mV).\nA respeito das informações do caso clínico descrito anteriormente, julgue o item subsequente. A\nprincipal base tiofisiopatogenética da doença apresentada pela paciente do caso clínico em\nquestão e a infecção viral.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-212125","number":"212125","sourceNumber":"212125","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Caso clínico - paciente sem doenças prévias; Idade: 19 anos: sexo: feminino; Sinais e\nsintomas: tremores nas extremidades, nervosismo e palpitações taquicárdicas (FC = 15 bpm, PA\n135 mmHg x 65 mmHg, pulsos radiais palpáveis e arrítmicos); Avaliação cardiovascular evidenciou\nictus cordis in situ, ritmo cardíaco irregular em 2 tempos, taquicárdico, bulhas normofonéticas, sem\nsopros ou ruídos adventícios. Na palpação, percebeu-se glândula tireoide indolor, levemente\naumentada e não nodular. Resultado de dosagem séricas: TSH (tirotrofina) = 0,05 mU/L (valores de\nreferência = 0,4 - 4,2 mU/L); T4 livre (tiroxina livre) = 4,0 nanogramas/dL (valores de referência =\n0,8 - 2,7 nanograma/dL); anticorpos antirreceptor de TSH (ou Trab) = 2 U/L (valor de referência <\n10 U/L); anticorpos antitireoglobulinas = positivo 1/6.400 (valores de referência não reagente <\n1/100); determinação de anticorpos antiperoxidase tireoidiana (anti-TPO) = 70 U/mL (valores de\nreferência < 35 U/mL). Ecodopplercardiograma = normal. Tira de ritmo Eletrocardiográfico (ECG)\nmostrada na figura a seguir (derivação D2, velocidade do papel: 25 mm/s, calibração: 1 cm= 1 mV).\nA respeito das informações do caso clínico descrito anteriormente, julgue o item subsequente. O\nuso de medicamento betabloqueador, como o propranolol, é recomendado para essa condição\nclínica.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-206140","number":"206140","sourceNumber":"206140","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Com relação à paralisia das cordas vocais, assinale a alternativa INCORRETA:","options":{"A":"O nervo laríngeo recorrente inerva toda a musculatura laríngea, exceto o músculo cricotireóideo,\nque é inervado pelo nervo laríngeo superior.","B":"A paralisia dos músculos laríngeos pode ocorrer a partir de uma lesão do sistema nervoso\ncentral ou, mais comumente, por comprometimento de nervo periférico (90%).","C":"No lado esquerdo, o nervo laríngeo recorrente separa-se do nervo vago no tórax e passa em\ntorno do arco aórtico ao nível do ducto\narterioso, correndo superiormente ao sulco traqueoesofágico\naté a articulação cricotireóidea.","D":"A paralisia vocal direita é mais comum que a da esquerda."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-206149","number":"206149","sourceNumber":"206149","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Hiperparatiroidismo é a terceira alteração endócrina mais comum, após o diabetes e a\ndoença tireoidea. Quanto a isso, assinale a\nalternativa INCORRETA:","options":{"A":"É caracterizada por hipersecreção de paratormônio, levando a hipercalcemia.","B":"Quando o hiperparatiroidismo é observado em casos de insuficiência renal crônica é\ndenominado hiperparatiroidismo secundário.","C":"A abordagem clássica para o tratamento cirúrgico do Hiperparatiroidismo primário é a\nexploração cervical unilateral.","D":"A Cintilografia com Tecnécio-99m Sestamibi funciona por captação mitocondrial e é um bom\nexame para localização\n\npré-operatória não invasiva da paratireoides."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-206156","number":"206156","sourceNumber":"206156","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Sobre o Feocromocitoma, assinale a alternativa INCORRETA:","options":{"A":"Originam-se das células cromafínicas da medula adrenal ou células paraganglionares\nextramedulares.","B":"Secretam norepinefrina, epinefrina e dopamina.","C":"São bilaterais em 50% dos casos.","D":"Podem ser esporádicos ou associados a NEM2A ou doença de von Hippel-Lindau."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-177269","number":"177269","sourceNumber":"177269","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Um homem de 45 anos de idade busca orientação médica. Ele relata uma mudança na\nprópria fisionomia, ao mesmo tempo em que há necessidade de que ele renove os repectivos\ndocumentos de identificação. Ele informa que, nos últimos 5 anos, iniciou uso de anti-hipertensivo e\ntem apresentado impotência sexual e diminuição da energia. No período, ele necessitou trocar os\nsapatos por números maiores. Com base nas informações apresentadas, a investigação do quadro\nclínico do referido paciente indica a solicitação de","options":{"A":"TSH e T4 livre, em função do fato de que o hipotireoidismo é uma afecção que acarreta\nalterações corpóreas e hipertensão.","B":"nível sérico de IGF-I, já que, na acromegalia, as mudanças de fisionomia e a hipertensão são\nfrequentes.","C":"cortisol livre na urina de 24 horas, em função do fato de que a síndrome de Cushing justifica as\nmudanças de fisionomia e hipertensão.","D":"nível sérico de hormônio de crescimento, já que os adenomas hipofisários acarretam\nacromegalia e mudanças como as citadas, pela\nhipersecreção de hormônio do crescimento.","E":"nível sérico de prolactina, já que a hipersecreção hipofisária causa adinamia e alteração da\nlibido\nsexual"},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-177235","number":"177235","sourceNumber":"177235","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Uma mulher de 22 anos de idade procura um ambulatório com queixa de dificuldade de\ncontrole dos níveis pressóricos, desde que recebeu o diagnóstico de pressão alta, há 6 meses. Ela\ninforma que, desde o diagnóstico, tem seguido as recomendações dietéticas e as relacionadas aos\nhábitos de vida. Atualmente, ela está em uso de nifedipina, 20 mg, 3 vezes ao dia, associada a\nmetoprolol 100 mg ao dia, e clonidina, 0,200 mg, 3 vezes ao dia. No último mês, ela foi admitida 2\nvezes em um pronto-socorro, com crises hipertensivas, tendo apresentado melhora após uso de\ncaptopril. Ao exame físico, ela apresenta níveis pressóricos estimados em 176 mmHg x 98 mmHg e\nfrequência cardíaca de 62 bpm. Durante o citado exame, não se evidencia edema ou sopros\ncardíacos. Não foi constatada na paciente distribuição anormal de pelos na face. Ela traz diversos\nexames; entre eles, o Mapa, com valores alterados, além de um ecocardiograma, com resultado\nnormal. Evidenciou-se, na paciente, função renal normal, com creatina de 0,8 mg/dL e redução de\npotássio, mantido em 2,8 mEq/dL. O bicarbonato teve o valor medido em 30 mEq/dL. Já a glicemia\nde jejum era de 96 mg/dL. Com base nas informações do hipotético caso clínico mencionado, é\ncorreto afirmar que este se trata de hipertensão secundária a:","options":{"A":"síndrome de Cushing.","B":"doença renovascular por displasia fibromuscular.","C":"feocromocitoma.","D":"hiperaldosteronismo primário.","E":"hiperplasia suprarrenal congênita."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-154491","number":"154491","sourceNumber":"154491","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"RN a termo com IG de 38 semanas e 4 dias, peso de nascimento de 3640 g. APGAR\n8/9 recebeu alta no segundo dia de vida e aos\n16 dias comparece à segunda consulta de\npuericultura, em aleitamento materno exclusivo, com queixa de constipação. Apresenta ganho\nponderal adequado e ao exame é notado apenas icterícia. A mãe refere que a criança é \"boazinha\",\nchora pouco e está amarela desde a alta da maternidade. Diante do quadro deve-se pensar em:","options":{"A":"Galactosemia.","B":"Icterícia associada ao aleitamento materno.","C":"Atresia de vias biliares.","D":"Icterícia fisiológica persistente.","E":"Hipotireoidismo congênito."},"answer":"E","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-154509","number":"154509","sourceNumber":"154509","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Menina de 6 anos de idade, previamente hígida, é atendida pelo pediatra com história\nde pelos pubianos há 6 meses e crescimento\nacelerado. Ao exame físico identificado estágio de\nTanner M1P3 sem ambiguidade genital. Os exames laboratoriais mostram: DHEA-S de 78 ug/dL\n(VR <150 ug/dL); testosterona de 80 ng/dL (VR< 40 ng/dL); androstenediona de 300 ng/dL (VR <\n275 ng/dL) e 17-OH progesterona de 940 ng/dL (VR< 150 ng/dL). Diante do quadro clínico trata-se\nprovavelmente de:","options":{"A":"Tumor suprarrenal.","B":"Puberdade precoce isolada idiopática.","C":"Exposição exógena de androgênios.","D":"Tumor ovariano.","E":"Hiperplasia Adrenal Congênita."},"answer":"E","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-133974","number":"133974","sourceNumber":"133974","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"A interpretação de resultados laboratoriais de função tireoidiana em doentes\ncriticamente enfermos apresenta dificuldades. Em\nrelação à síndrome do eutireoideo doente e de\nacordo com a Diretriz Brasileira de Hipotireoidismo - Projeto Diretrizes, assinale a alternativa\ncorreta.","options":{"A":"Medicações como corticoides e dopamina podem interferir no resultado de exames de função\ntireoidiana.","B":"Em razão da importância da ação tireoidiana em casos graves, a avaliação da função tireoidiana,\nnesses casos, deve ser feita de rotina por\nendocrinologistas.","C":"A concentração de T3 reverso costuma estar diminuída nesses pacientes, devendo se reposto\nprofilaticamente.","D":"Quando feita a análise da função tireoidiana, ela deve ser realizada com o paciente em jejum de\n48 horas para evitar fatores confundidores.","E":"Na ocasião em que é feita a análise da função tireoidiana, deve-se priorizar excepcionalmente a\navaliação do T4 total."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-133981","number":"133981","sourceNumber":"133981","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"De acordo com a Diretriz Brasileira de Hipotireoidismo, em relação à investigação de\ndiagnósticos diferenciais envolvendo hipóteses de hipotireoidismo e depressão, assinale a\nalternativa CORRETA.","options":{"A":"Pacientes deprimidos devem receber de rotina reposição de hormônios tireoidianos,","B":"O diagnóstico de hipotireoidismo clínico deve ser feito com base na relação T4 livre por T4\ntotal.","C":"O diagnóstico de hipotireoidismo subclínico deve ser considerado em pacientes deprimidos.","D":"O tratamento de hipotireoidismo é fundamentado na reposição de TSH.","E":"O tratamento de hipotireoidismo apoia-se na reposição de T4 total."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-129041","number":"129041","sourceNumber":"129041","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Uma paciente com 36 anos de idade, portadora de tireoidite de Hashimoto há cinco\nanos, procurou atendimento médico após receber\nos resultados de seus exames de uma clínica de\n\"check-up\". Ela não tinha qualquer queixa de saúde, referiu mãe hipertensa e pai com câncer de\npróstata e estava em uso diário de 75 mcg de levotiroxina sódica. Sua preocupação era com o\ndiagnóstico de lúpus eritematoso sistêmico dado por facultativo. Seu exame físico não mostrou\nalterações. Ao analisar os exames complementares que a paciente havia levado, o médico\nconstatou que o exame para fator antinuclear era positivo, com descrição de padrão nuclear\npontilhado fino denso e título de 1/160. Não havia nenhuma alteração no hemograma ou nas\nprovas de atividade inflamatória. Com base nesse caso clínico hipotético, assinale a alternativa\ncorreta.","options":{"A":"O título de 1/160 confirma o diagnóstico de lúpus eritematoso sistêmico.","B":"O padrão de fluorescência nuclear indica forte probabilidade de existir hepatite autoimune.","C":"A tireoidite de Hashimoto pode explicar o fator antinuclear positivo, sem que haja qualquer outra\ndoença autoimune.","D":"O tipo de padrão de fluorescência e o elevado título sérico indicam que é muito provável que\nseja lúpus eritematoso induzido por droga (levotiroxina).","E":"A associação de autoanticorpos e a ausência de sintomas indicam que se trata de lúpus pérnio."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-129045","number":"129045","sourceNumber":"129045","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Assinale a alternativa que apresenta a complicação, a longo prazo, mais comum em\npacientes com doença de Graves tratados com iodo radioativo.","options":{"A":"Atresia de esôfago.","B":"Hipotireoidismo.","C":"Carcinoma da tireoide.","D":"Linfoma da tireoide.","E":"Infertilidade."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-111352","number":"111352","sourceNumber":"111352","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Uma idosa de 62 anos de idade apresenta, há um ano, sintomas de cansaço,\ndesânimo, ganho de peso, edema de membros\ninferiores e hipercolesterolemia não controlada\ncom estatinas. Dos exames a seguir, assinale o mais indicado nesse caso.","options":{"A":"Dosagem do hormônio liberador da tireotropina.","B":"Dosagem do hormônio estimulante da tireoide.","C":"Dosagem da tiroxina livre.","D":"Ecocardiograma.","E":"Eletrocardiograma."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-111329","number":"111329","sourceNumber":"111329","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Em relação à insuficiência adrenal, é CORRETO afirmar:","options":{"A":"O diagnóstico de crise adrenal é sempre clínico,\n\ndevendo o tratamento ser iniciado rapidamente sempre que houver a suspeita da doença.","B":"A hipoglicemia não é um achado frequente.","C":"A dosagem de cortisol basal sempre define o\ndiagnóstico.","D":"Hiperpigmentação cutânea, astenia, perda de peso e hipotensão sugerem o quadro de\ninsuficiência adrenal secundária.","E":"A dosagem de ACTH é fundamental para definir o melhor modo de tratamento."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-80703","number":"80703","sourceNumber":"80703","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Assinale a alternativa que apresenta uma manifestação da insuficiência adrenal aguda.","options":{"A":"Taquicardia.","B":"Hipotermia.","C":"Hipertensão.","D":"Hipopotassemia.","E":"Hipernatremia."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-97754","number":"97754","sourceNumber":"97754","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Uma paciente com 42 anos de idade, com antecedentes de duas gestações prévias\nsem intercorrências e sem outras comorbidades,\ncomparece à Unidade Básica de Saúde com\nqueixas de aumento de volume em região cervical anterior, notado há aproximadamente 10 meses.\nNega dor local ou vermelhidão. Nega quadros semelhantes na família. No exame físico encontra-se\nem bom estado geral, corada, sem linfonomegalias cervicais. A tireoide é visível durante a\ndeglutição e, na palpação, tem dimensões aumentadas em cerca de 2 vezes, com consistência\nmais fibrosa do que a normal, é móvel e indolor e sem nódulos palpáveis. As auscultas cardíaca e\npulmonar são normais. A frequência cardíaca é de 72 bpm e a pressão arterial = 125 x 70 mmHg. A\npaciente não apresenta tremores de extremidades. A ultrassonografia da tireoide revela uma\nglândula com ecotextura heterogênea e com parênquima moderadamente hipoecoico; observam-se\náreas de hiperecogenicidade e traves fibróticas. O volume total é de 28 ml (Valor de referência = 8\n-\n14 ml). Além de solicitar dosagem de TSH e de T4 livre, a conduta adequada para essa paciente é\nsolicitar:","options":{"A":"punção aspirativa da tireoide.","B":"pesquisa de anticorpo antitireoperoxidase.","C":"dosagem de T3 livre e cintilografia da tireoide.","D":"dosagem de T3 livre e pesquisa de anticorpo antirreceptor do TSH."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-75546","number":"75546","sourceNumber":"75546","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Mulher com 52 anos de idade, previamente hígida, há 3 meses queixa-se de astenia,\nsonolência e ganho de peso, constipação, além de artralgias e mialgias. Ao exame, nota-se pele\nseca e frequência cardíaca de 62 bpm, além de não apresentar sinais de artrite ou deformidades\narticulares. Os exames indicados e o principal diagnóstico a serem considerados são,\nrespectivamente:","options":{"A":"CPK e aldolase; fibromialgia.","B":"TSH e T4 livre; hipotireoidismo primário.","C":"Cálcio sérico e PTH; hiperparatireoidismo.","D":"TSH e T4 livre; hipotireoidismo secundário.","E":"Cortisol e potássio séricos; insuficiência adrenal."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-351611","number":"351611","sourceNumber":"351611","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Um indivíduo do sexo masculino, 65 anos de idade, apresenta uma massa suprarrenal\ndireita acidental ao exame tomografia\ncomputadorizada (TC), durante a investigação devido a um\ntraumatismo. Ele não tem história de hipertensão nem quaisquer condições malignas. O exame\nfísico é negativo. A investigação sanguínea demonstra eletrólitos e metanefrinas plasmáticas\nnormais. O cortisol livre urinário está normal e o teste de supressão de dexametasona, por uma\nnoite, em doses baixas, mostrou um nível baixo de cortisol na manhã seguinte. O exame TC\ndemonstrou uma massa heterogênea, de forma irregular, de 6cm. Assinale a alternativa que\napresenta CORRETAMENTE a próxima providência apropriada no tratamento desse paciente.","options":{"A":"Efetuar uma biópsia com agulha da massa suprarrenal sob orientação TC.","B":"Repetir o exame TC em 6 meses.","C":"Efetuar uma adrenalectomia aberta.","D":"Administrar mitotane ao paciente."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-351591","number":"351591","sourceNumber":"351591","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"É CORRETO afirmar que a mais frequente complicação associada ao pós-operatório do\ntratamento cirúrgico do câncer de tiroide é:","options":{"A":"Infecção.","B":"Granuloma de fio cirúrgico.","C":"Seroma.","D":"Hipocalcemia."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-346837","number":"346837","sourceNumber":"346837","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Mulher de 27 anos queixa-se de dor na região cervical anterior e febre há 8 dias. Nega\ncomorbidades conhecidas e não faz uso de medicamentos. Ao exame físico, PA: 140x86mmHg,\nFC: 118bpm, FR: 18ipm, SPO? 98% (aa), Tax: 37,9°C. Apresenta tireoide de volume aumentado,\nquente e dolorosa a palpação. Os exames respiratório, cardiovascular e abdominal não revelam\noutras anormalidades. O exame neurológico revela tremor postural e cinético das extremidades\nsuperiores e hiperreflexia difusa. Exames de laboratório: TSH 0,03mU/L (VR 0,4 a 4,5mU/L); T4L\n2,7ng/dL (VR 0,7 a 1,8ng/dL); leucócitos 15.980/mm3 (VR 4.000 a 11.000/mm³); neutrófilos 11.540\n(VR 1.500-7.600/m³); VHS 84mm (VR > 20mm). Assinale a alternativa que apresenta a prescrição\nMAIS adequada para essa paciente.","options":{"A":"Metimazol e dipirona.","B":"Propiltiouracil e betabloqueador.","C":"Antibiótico e anti-inflamatório não esteroidal.","D":"Anti-inflamatório não esteroidal e betabloqueador."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-320443","number":"320443","sourceNumber":"320443","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"A causa mais comum de Distúrbio da Diferenciação Sexual é:","options":{"A":"Anormalidades cromossômicas.","B":"Tumores virilizantes dos ovários.","C":"Exposição intrauterina à progestágenos.","D":"Hiperplasia adrenal congênita.","E":"Uso de drogas ilícitas na gestação"},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-304843","number":"304843","sourceNumber":"304843","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Mulher de 32 anos, apresenta quadro de náuseas, vômitos, dor abdominal e astenia há\n4 semanas. Ao exame físico apresenta hipotensão\nortostática, hiperpigmentação em região areolar,\náreas de dobras cutâneas e gengival. Sem outras alterações ao exame do sistema cardiovascular,\nrespiratório e palpação abdominal. Apresenta os seguintes exames laboratoriais: glicemia = 65\nmg/dl; sódio = 138 mEq/L; potássio = 6,4 mEq/L; magnésio = 1,8 mg/dl; hemoglobina = 12,8 g/dl;\nleucócitos = 7.800/mm³; hormônio tiroestimulante = 1,35 UI/ml. Na sequência da propedêutica\nlaboratorial, espera-se encontrar:","options":{"A":"Níveis séricos de cortisol baixo, de ACTH e renina aumentados.","B":"Níveis séricos de cortisol e de renina baixos e de ACTH aumentado.","C":"Níveis séricos de cortisol baixo, de renina aumentado e de ACTH normal.","D":"Níveis séricos de cortisol, aldosterona e de ACTH baixos."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-313285","number":"313285","sourceNumber":"313285","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Quando a concentração plasmática de cálcio cai, a glândula paratireoide é estimulada a\nliberar paratormônio (PTH). Este aumenta a excreção urinária de fosfato e a reabsorção de cálcio.\nA elevação do PTH estimula os rins a secretar ?-hidroxilase que leva a ativação de:","options":{"A":"Folato.","B":"Aldosterona.","C":"Magnésio.","D":"Vitamina D.","E":"Vitamina E."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-260713","number":"260713","sourceNumber":"260713","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Qual o tumor funcionante mais comum do pâncreas?","options":{"A":"Vipoma.","B":"Gastrinoma.","C":"Insulinoma.","D":"Adenocarcinoma.","E":"Glucagonoma."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-227250","number":"227250","sourceNumber":"227250","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Os níveis séricos de fosfatase alcalina óssea encontram-se mais elevados na seguinte\nsituação:","options":{"A":"Hipoparatireoidismo.","B":"Artrite reumatoide.","C":"Doença de Paget.","D":"Osteoporose."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-246360","number":"246360","sourceNumber":"246360","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Lactente de 3 meses é levado por tia materna ao pediatra da UBSF com queixa de\nsonolência, letargia, choro rouco e dificuldade para sugar mamadeira. Ao exame físico apresentava\ntom de pele amarelado, mixedema, macroglossia, fontonelas amplas e hérnia umbilical.\n\nQuestionada sobre o teste do pezinho, tia relata que a mãe biológica é usuária de drogas,\nabandonou a criança e que não assumiu a\nresponsabilidade legal da mesma. Não tem os\ndocumentos de nascimento e não sabe dizer se exame foi realizado. Pelos sinais e sintomas\nclínicos, qual a principal hipótese diagnóstica?","options":{"A":"Hiperplasia Adrenal Congênita","B":"Deficiência da Biotinidase","C":"Hipotireoidismo Congênito","D":"Anemia Falciforme"},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-227096","number":"227096","sourceNumber":"227096","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"O hipotireoidismo na lactância e na infância pode ser congênito ou adquirido. Em\nrelação ao hipotireoidismo, assinale a alternativa INCORRETA:","options":{"A":"O hipotireoidismo adquirido é tipicamente causado por tireoidite autoimune (tireoidite de\nHashimoto) e ocorre na fase final da infância e da adolescência.","B":"A triagem de rotina nos recém-nascidos detecta o hipotireoidismo antes do aparecimento dos\nsinais clínicos.","C":"O hipotireoidismo em crianças é geralmente congênito; as causas adquiridas se tornam mais\ncomuns com a idade.","D":"A dosagem de T3 livre deve ser realizada sempre que se suspeitar de hipotireoidismo."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-227313","number":"227313","sourceNumber":"227313","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"A tireoide tem um papel importante na regulação de numerosos processos metabólicos\nde todo o corpo. Nos distúrbios da tireoide é\nCORRETO afirmar:","options":{"A":"O hipotireoidismo congênito é hereditário e se apresenta, na maioria dos casos, com retardo no\ndesenvolvimento mental e físico, que já é visível ao nascimento. As crianças com hipotireoidismo\ncongênito nascem pequenas para a idade gestacional e com os reflexos mais lentos.","B":"A tireoide de Hashimoto ou tireoidite linfocítica crônica é rara antes da adolescência e a\npresença de bócio descarta o diagnóstico.","C":"Na tireoidite linfocítica crônica, a glândula tireoide geralmente está diminuída, com\nconsistência\nfirme e indolor à palpação.","D":"O hipertireoidismo resulta da secreção excessiva de hormônio tireoidiano durante a infância e\ngeralmente é causado pela doença de Graves."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-220281","number":"220281","sourceNumber":"220281","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Em relação ao tratamento do hipotireoidismo, assinale a alternativa CORRETA:","options":{"A":"A reposição da levotiroxina melhora a maioria das manifestações clínicas, exceto a disfunção\ncognitiva e os transtornos do humor.","B":"Na tireoidite de Hashimoto, está indicado o uso de corticoide para impedir a progressão da\ndestruição autoimune da glândula.","C":"A dose de levotiroxina deve ser ajustada de acordo com o valor do TSH após 2 semanas do\ninício.","D":"Nos pacientes idosos e cardiopatas, é recomendado iniciar doses baixas de levotiroxina e\nprogredir lentamente."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-199543","number":"199543","sourceNumber":"199543","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Em relação à insuficiência adrenal, assinale a assertiva CORRETA.","options":{"A":"A doença de Addison é causada por autoanticorpos contra as células produtoras de ACTH.","B":"Suspensão abrupta de um corticoide após longo tempo de administração exógena é a principal\ncausa de insuficiência adrenal.","C":"Hiperpigmentação é achado típico da insuficiência adrenal secundária.","D":"O tratamento da insuficiência adrenal secundária requer a reposição de prednisona e\nfludrocortisona."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-196744","number":"196744","sourceNumber":"196744","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente 24 anos, com tendência a engordar, dificuldade de perder peso, desânimo,\nqueda de cabelo e pele seca. Você desconfia\nde alteração em:","options":{"A":"Hipófise.","B":"Tireoide.","C":"Ovário.","D":"Suprarrenal."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-196800","number":"196800","sourceNumber":"196800","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Pacientes em corticoterapia prolongada podem desenvolver efeitos adversos e efeitos\ncolaterais. Assinale a opção abaixo que NÃO é um efeito que ocorre durante a corticoterapia.","options":{"A":"Hiperglicemia.","B":"Hipercalemia.","C":"Osteoporose.","D":"Dislipidemia."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-188021","number":"188021","sourceNumber":"188021","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Mulher, 46 anos, vem ao consultório médico preocupada com nódulo tireoidiano\nencontrado incidentalmente durante banho. No exame físico, apresenta nódulo único de\nconsistência firme com aproximadamente 1,0 cm de diâmetro. Sobre o manejo da doença em\nquestão, assinale a alternativa correta:","options":{"A":"Hormônio tireoestimulante sérico baixo se correlaciona com uma maior probabilidade de\nmalignidade.","B":"Microcalcificações e hipervascularização são achados ultrassonográficos suspeitos de câncer.","C":"Ultrassonografia evidenciando lesão cística ou mesmo sólido-cística descarta neoplasia maligna.","D":"Ressonância magnética é inapropriada para avaliação de massa tireoidiana com linfonodos\ncervicais palpáveis.","E":"Biópsia aspirativa com agulha fina apresenta valor preditivo positivo próximo de 90% para\nnódulos sólidos malignos na tireoide."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-172516","number":"172516","sourceNumber":"172516","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente do sexo masculino, 64 anos, hipertenso e diabético de longa data, PO tardio\nde revascularização miocárdica, miocardiopatia\nisquêmica com fração de ejeção discretamente\nreduzida, insuficiência renal crônica ainda sem terapia dialítica e proteinúria de 6 g em 24h. Faz\nuso de losartan 100 mg/dia, bisoprolol 10 mg/dia, AAS 100 mg dia, furosemida 40 mg/dia,\nrosuvastatina 20 mg/dia, mononitrato de isossorbida 40 mg/dia, trimetazidina 70 mg/dia e\nreposição oral de potássio. Internado no CTI por piora da dispneia com BNP bastante elevado;\ncreatina = 3,6; ureia = 190; alcalose metabólica e potássio = 2,1.","options":{"A":"Sem dúvidas, essa dosagem de potássio está errada, deve ser repetida, afinal não é possível\nhaver hipocalemia em um paciente com insuficiência\nrenal, usando losartan e betabloqueador.","B":"É um quadro clássico de hipoaldosteronismo hiporreninêmico, evidenciado claramente pela\nalcalose metabólica e pela hipocalemia.","C":"Inicialmente, poderia até se pensar em atribuir a hipocalemia ao uso da furosemida, mas a\npresença de alcalose metabólica afasta definitivamente essa\n\npossibilidade.","D":"É um possível caso de hiperaldosteronismo primário associado aos problemas já\nexistentes, onde uma elevada atividade da renina\nplasmática e níveis elevados de aldosterona\nplasmática auxiliam na confirmação do diagnóstico. Além disso, um exame de imagem das\nsuprarrenais é fundamental.","E":"É um possível caso de hiperaldosteronismo primário associado aos problemas já\nexistentes, onde uma atividade da renina\nplasmática bastante reduzida e níveis elevados de\naldosterona plasmática auxiliam na confirmação\n\ndo diagnóstico. Além disso, um exame de imagem das suprarrenais é fundamental."},"answer":"E","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-174389","number":"174389","sourceNumber":"174389","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"A tríade diagnóstica encontrada na síndrome de Verner-Morrison caracteriza-se por:","options":{"A":"Altos níveis de peptídeo intestinal vasoativo no sangue, tumor pancreático e diarreia\nsecretória.","B":"Altos níveis de gastrina no sangue, tumor pancreático e úlcera gástrica recidivante.","C":"Altos níveis de somastostatina no sangue, tumor hepático e diarreia aquosa.","D":"Altos níveis de 5-HT no sangue, tumor hepático e rubor facial.","E":"Altos níveis de aldosterona no sangue, tumor de supra-renal, hipertensão arterial sistêmica."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-148615","number":"148615","sourceNumber":"148615","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Mulher de 32 anos apresenta quadro de perda ponderal, taquicardia, palpitações,\nagitação psicomotora, tremores e hiperfagia há cerca\nde 2 meses. Ao exame físico apresenta-se\ncom FC=135 bpm, PA = 140 x 60 mmHg, tremor fino de extremidades, tireóide aumentada\ndifusamente de volume com temperatura local elevada e sopro tireoidiano, proptose bilateral sem\nsinais flogísticos oculares. Assinale a alternativa correspondente ao manejo deste caso neste\nmomento.","options":{"A":"Devem ser prescritos metimazol, benzodiazepínico, inibidor da enzima conversora de\nangiotensinas.","B":"Devem ser prescritos propiltiuracil, propranolol, prednisona.","C":"A paciente deve ser encaminhada para tratamento com iodo radioativo.","D":"A paciente deve ser encaminhada para tratamento cirúrgico.","E":"Deve ser prescritos solução de lugol e sais de lítio."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-162586","number":"162586","sourceNumber":"162586","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"A Síndrome de Cushing pode ser causada pela produção ectópica de ACTH ou CRH.\nCom base nisso, considere as neoplasias\nabaixo. I ? Carcinoide de timo; II ? Carcinoma de pulmão;\nIII ? Carcinoma de pâncreas. Quais podem estar associadas à Síndrome de Cushing?","options":{"A":"Apenas I.","B":"Apenas II.","C":"Apenas III.","D":"Apenas II e III.","E":"I, II e III."},"answer":"E","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-155472","number":"155472","sourceNumber":"155472","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Sobre o carcinoma folicular da tireóide, marque a alternativa CORRETA:","options":{"A":"Hipotireoidismo é a regra no momento do diagnóstico.","B":"O comprometimento linfonodal ocorre na maioria dos pacientes.","C":"Rouquidão sugere melhor prognóstico.","D":"Está presente em até 10% dos pacientes portadores de bócio multinodular.","E":"É o tipo mais comum de câncer da tireóide."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-131614","number":"131614","sourceNumber":"131614","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Sobre a tireoide, assinale a resposta CORRETA:","options":{"A":"O carcinoma folicular é o câncer mais comum em pacientes com história de radioterapia externa.","B":"Metástases de câncer de tireoide são frequentes em linfonodos do nível 1.","C":"Carcinoma medular deve ser habitualmente tratado com tireoidectomia total sem\nlinfadenectomia.","D":"1% dos cistos do ducto tireoglosso podem conter câncer. Podem ocorrer tumores foliculares,\npapilíferos e anaplásicos. Exceto medulares.","E":"Sialoadenite não é uma complicação possível após dose ablativa de 100 mCi de I 131."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-100993","number":"100993","sourceNumber":"100993","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Qual é o tumor pancreático funcionante de origem neuroendócrina mais comum?","options":{"A":"Gastrinoma.","B":"Insulinoma.","C":"Glucagonoma.","D":"Vipoma.","E":"Feocromocitoma."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-77600","number":"77600","sourceNumber":"77600","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"São indicações para solicitar densitometria óssea, EXCETO:","options":{"A":"Mulher na pós-menopausa.","B":"Fratura patológica prévia.","C":"Corticoterapia prolongada.","D":"Litíase Renal.","E":"Homens com mais de 50 anos."},"answer":"E","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-77496","number":"77496","sourceNumber":"77496","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"A paciente R.S.B., 57 anos, em pós-menopausa há 8 anos, assintomática, apresentou\no seguinte resultado de densitometria mineral\nóssea: T-escore de coluna lombar de L1-L4 = -1,3\nDP; T-score de fêmur total = -0,9 DP; T-score de colo do fêmur = -1,2 DP. Propedêutica\ncomplementar revelou: calcemia = 10,5 mg/dl (valor de referência: 8,6-10,2 mg/dl); fosfatemia = 2,9\nmg/dl (valor de referência: 2,5-4,5 mg/dl); fosfatase alcalina óssea específica sérica = 49,4 U/L\n(valor de referência: 14,2-42,7 U/L); paratormônio sérico = 85 pg/ml (valor de referência: 4-52\npg/dl); creatinina = 0,8 mg/dl; ureia = 24 mg/dl; ultrassonografia cervical sem evidência de imagem\nsuspeita; cintilografia de paratireoides com 99mTC-sestamibi evidenciando captação prolongada do\nradioisótopo em topografia do polo inferior do lobo direito da tireoide. Em relação ao quadro\nclínico\napresentado, assinale a alternativa INCORRETA:","options":{"A":"Osteíte fibrosa cística e síndrome neuropsiquiátrica podem ocorrer nas formas mais graves\ndesta doença.","B":"Estes achados podem estar presentes nas síndromes de neoplasias endócrinas múltiplas tipo 1\ne tipo 2.","C":"Raramente este quadro pode ser ocasionado por um carcinoma.","D":"Neste caso o tratamento de escolha é paratireoidectomia.","E":"Nos casos familiares, geralmente mais de uma glândula paratireoide encontra-se hiperplasiada."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-77539","number":"77539","sourceNumber":"77539","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"A paciente IMR, 72 anos, tem diagnóstico de hipertensão arterial, diabetes tipo 2 e\nosteopenia em coluna lombar. Encontra-se em uso de metformina 1500 mg/dia, losartana 50\nmg/dia, hidroclorotiazida 12,5 mg/dia, carbonato de cálcio 1200 mg/dia e ácido acetilsalicílico 100\nmg/dia. Encontra-se assintomática. Apresenta os seguintes exames laboratoriais: glicemia de jejum\n\n= 108 mg/dl, glicemia 2 horas pós-prandial = 138 mg/dl, hemoglobina glicada = 6,3%, colesterol\ntotal = 150 mg/dl, HDL-colesterol = 54\nmg/dl, triglicerídios = 135 mg/dl, creatinina = 1,1 mg/dl,\nhormônio tireoestimulante = 6,9 (valor de referência: 0,34-5,6 µUI/ml), tiroxina livre = 0,88 ng/dl\n(valor de referência: 0,54-1,24 ng/dl), anticorpo anti-tireoperoxidase= 32 UI/ml (valor de\nreferência:\n\n< 9 UI/ml), cálcio total = 9,2 mg/dl (valor de referência: 8,6-10,2 mg/dl), 25-OH vitamina D = 18\nmg/dl (valor de referência > 30 mg/dl). Em relação ao caso clínico supra descrito, assinale a\nalternativa incorreta.","options":{"A":"Não há necessidade de ajuste de dose da metformina ou associação de outro hipoglicemiante\noral para a paciente.","B":"Como a paciente apresenta fatores de risco cardiovascular e osteopenia, está indicado o uso de\nlevotiroxina para tratamento do hipotireoidismo.","C":"Está indicada a reposição de colecalciferol devido à perda de massa óssea.","D":"Apesar do elevado risco cardiovascular da paciente, não há indicação para uso de estatina\ncomo droga hipolipemiante.","E":"Os níveis pressóricos da paciente devem idealmente ficar abaixo de 130/80 mmHg, sendo\nrecomendado o uso de um medicamento inibidor da enzima conversora de angiotensina ou\nbloqueador do receptor da angiotensina II."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-77369","number":"77369","sourceNumber":"77369","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente, 19 anos, sexo masculino, internado no HECI após alguns atendimentos em\nrede básica e em pronto atendimento, há\ncerca de 1 mês com história de fraqueza e discreto\nedema de membros inferiores, além de manchas hipercrômicas mais notadamente em face e\npernas. Refere ter sido também diagnosticado diabético em uma dessas consultas de pronto\natendimento, onde, além disso, era identificada presença de hipocalemia. Nesses atendimentos era\nmedicado com insulina e potássio e liberado para casa. Na admissão ao HECI, além das alterações\njá descritas, apresentava ainda hipertensão arterial (170 x 100). Exames laboratoriais iniciais\nmostravam hipocalemia grave (1,8), além de acentuada alcalose metabólica (bicarbonato de 50).\n\nNeste caso, qual a melhor hipótese diagnóstica?","options":{"A":"Insuficiência suprarrenal (doença de Addison).","B":"Paralisia hipocalêmica periódica.","C":"Uso inadequado de insulina nesses atendimentos anteriores de pronto-socorro.","D":"Acidose tubular renal.","E":"Síndrome de Cushing com produção ectópica de ACTH."},"answer":"E","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-77531","number":"77531","sourceNumber":"77531","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Sobre hipotireoidismo na infância, responda qual alternativa está CORRETA. I) Deve\nser avaliado Hipotireoidismo Congênito (HC) em\nneonatos com icterícia prolongada. II) Atraso no\ndesenvolvimento neuropsicomotor é um dos sintomas de hipotireoidismo adquirido. III) O\nhipotireoidismo congênito é a principal causa evitável de deficiência mental.","options":{"A":"Somente III está correta.","B":"Todas estão corretas.","C":"Somente II e III estão corretas.","D":"Somente I e III estão corretas.","E":"Somente I e II estão corretas."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-43295","number":"43295","sourceNumber":"43295","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente do sexo feminino, 34 anos, com queixa de emagrecimento de 8 kg em 2\nmeses, tremores, insônia, palpitação e sudorese\nexcessiva. Ao exame físico, encontra-se lúcida,\ncorada, acianótica, FC 135 bpm, PA 120/60 mmHg, mãos quentes e sudoreicas, com tremor leve\nde extremidades, reflexos Aquileu e patelar exacerbados. Exame da região cervical com nódulo\ntireoidiano móvel de 2 cm em polo superior do lobo direito. Restante da glândula normal. Com base\nnos dados acima, os exames indicados que confirmariam a hipótese diagnóstica e o diagnóstico da\npaciente são respectivamente:","options":{"A":"Eletrocardiograma, TSH e T4 livre; Taquiarritmia e Doença de Graves.","B":"US de tireoide, TSH e T4 livre; Doença de Graves.","C":"Cintilografia de tireoide, TSH e T4 livre; Doença de Plummer.","D":"US e Ressonância da tireoide, TSH e T4 livre; Doença de Plummer.","E":"Hemograma, TSH, T4 livre; Tireoidite de Hashimoto."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-23139","number":"23139","sourceNumber":"23139","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Quanto aos insulinomas, podemos afirmar que:","options":{"A":"Comumente estão localizados no trígono dos insulinomas (espaço entre: vesícula biliar, borda\nduodenal e cabeça pancreática).","B":"São considerados os ?APUDOMAS? (tumores originados de células do sistema APUD) mais\nraros.","C":"75% dos insulinomas são malignos, por este motivo as ressecções desses tumores devem ser\namplas e acompanhadas de linfadenectomias.","D":"A suspeição clínica baseia-se na tríade de Whipple, que consiste em Hipoglicemia refratária ao\nconsumo de glicose + Insulinemia elevada +\nsudorese.","E":"Pode estar associado à neoplasia endócrina múltipla."},"answer":"E","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-27391","number":"27391","sourceNumber":"27391","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Em relação ao hipoparatiroidismo primário, como encontra-se o cálcio e fósforo\nplasmático, respectivamente:","options":{"A":"baixo; alto","B":"baixo; baixo","C":"alto; baixo","D":"alto; alto","E":"todas erradas"},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-23146","number":"23146","sourceNumber":"23146","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Todas as afirmativas estão corretas exceto:","options":{"A":"Na tireoidite de Hashimoto encontra-se níveis elevados de anticorpos circulantes\nantitireoglobulina.","B":"A tireoidite de Hashimoto é mais frequente no período da adolescência, no sexo masculino.","C":"A síndrome de DiGeorge caracteriza-se por hipoparatireoidismo congênito, aplasia tímica e\nanomalias cardíacas.","D":"Hipocalcemia é comum nas primeiras horas de vida, principalmente em prematuros.","E":"A tríade clássica da doença de Graves inclui bócio, exoftalmia e hipertireoidismo."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-9379","number":"9379","sourceNumber":"9379","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Quais das doenças abaixo podem diminuir o débito urinário quando associadas ao\nDiabetes Insípido?","options":{"A":"Mixedema e insuficiência supra-renal.","B":"Diabetes mellitus e dislipidemia.","C":"Diabetes mellitus e hipoparatireoidismo.","D":"Insulinoma e hiperparatiroidismo.","E":"Hipercortisolismo primário e secundário."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-363962","number":"363962","sourceNumber":"363962","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Leia o caso clínico a seguir: Mulher de 53 anos foi encaminhada para avaliação de\nhiperprolactinemia. Não apresentava qualquer tipo de queixa, totalmente assintomática.\n\nAntecedente de última menstruação há 48 meses. Trazia exame de RNM de sela túrcica com lesão\ncompatível com adenoma hipofisário de 5 mm, sem invasão extra-selar. Seguindo as diretrizes do\núltimo Consenso Internacional da Sociedade Hipofisária, a conduta mais apropriada para essa\npaciente deverá ser","options":{"A":"o encaminhamento para cirurgia.","B":"o encaminhamento para radioterapia.","C":"a utilização de agonista dopaminérgico.","D":"o acompanhamento da paciente."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-363982","number":"363982","sourceNumber":"363982","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente de 45 anos, transplantado renal, começou a apresentar um quadro de\nhipertensão severa, apesar do uso de vários anti-hipertensivos. Não usa diuréticos. Na\ninvestigação, apresentou hipocalemia. A partir do caso apresentado, qual deve ser o próximo\nexame a ser solicitado, pensando na causa desse distúrbio?","options":{"A":"Dosagem de tacrolimos.","B":"Doppler do enxerto renal.","C":"Relação aldosterona/atividade plasmática de renina.","D":"Dosagem de metanefrinas séricas urinárias."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-354830","number":"354830","sourceNumber":"354830","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Leia o relato do caso clínico a seguir. Paciente, 40 anos idade, sexo masculino, durante\ninvestigação de cefaleia foi encontrado adenoma hipofisário de 0,8 cm em lobo direito da hipófise.\nExames laboratoriais demonstram GH: 10 µg/L, IGF1: 215 ng/mL (VR: 58 a 219 ng/mL) e\nnormalidade dos demais eixos hipofisários. Considerando o caso relatado, qual é a próxima\nconduta e sua justificativa?","options":{"A":"Acompanhar o paciente a longo prazo, por tratar-se de um incidentaloma hipofisário.","B":"Solicitar o teste de supressão do GH com glicose (dosagem de GH durante o TOTG) para\nesclarecimento diagnóstico.","C":"Iniciar o tratamento com octreotide LAR pois o GH, no valor apresentado no exame, confirma\ndiagnóstico de acromegalia.","D":"Encaminhar o paciente para neurocirurgia, por se tratar de um tumor de hipófise com efeitos\ncompressivos."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-354829","number":"354829","sourceNumber":"354829","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Leia o relato do caso clínico a seguir. Paciente, 45 anos de idade, sexo feminino, refere\nsintomas de perda de peso, tremores, sudorese, taquicardia e diarreia. Ao exame físico apresenta\nexoftalmia bilateral, com edema e eritema em ambas as pálpebras e conjuntivas, além de dor à\nmovimentação ocular; PA: 140/90 mmHg, FC; 112 bpm. Exames complementares com discreto\naumento de volume tireoidiano ao ultrassom, anti TRAB: 3 UI/L (VR: < 0,55 UI/L), TSH: 0,001\nmicroUI/mL (VR: 0,48 a 5,6), T4 livre: 3 ng/dL (VR: 0,85 a 1,5 ng/dL). Considerando o caso\nrelatado, qual é a conduta a ser adotada?","options":{"A":"Indicar radioiodoterapia por ser um procedimento resolutivo, com grande probabilidade de cura.","B":"Encaminhar para Tireoidectomia total de imediato.","C":"Iniciar tratamento medicamentoso com tapazol 30 mg e propranolol.","D":"Escolher entre as opções terapeuticas: radioidoterapia, tireoidectomia total ou tratamento\nmedicamentoso a critério do médico\nassistente e da preferência do paciente, já que nenhum dos\ntratamentos é contraindicado e nem há expectativa de melhor resposta com um tratamento\nespecífico."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-362629","number":"362629","sourceNumber":"362629","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Os fatores de risco descritos para hiperglicemia induzida pelo uso de glicocorticoide são\nlistados corretamente no item:","options":{"A":"Uso de doses mais baixas (prednisolona > 20 mg, hidrocortisona > 50 mg, dexametasona > 4\nmg), longa duração de tratamento, idade avançada, IMC elevado, intolerância à glicose prévia,\nhistória de diabetes gestacional, história anterior de hiperglicemia induzida por glicocorticoide,\nhistória familiar de DM, HbA1c ? 6%.","B":"Uso de doses mais altas (prednisolona > 20 mg, hidrocortisona > 50 mg, dexametasona > 4 mg),\ncurta duração de tratamento, idade avançada, IMC elevado, intolerância à glicose prévia, história\nde diabetes gestacional, história anterior de hiperglicemia induzida por glicocorticoide, história\nfamiliar de DM, HbA1c ? 6%.","C":"Uso de doses mais altas (prednisolona > 20 mg, hidrocortisona > 50 mg, dexametasona > 4 mg),\nlonga duração de tratamento, idade avançada, IMC elevado, intolerância à glicose prévia, história\nde diabetes gestacional, história anterior de hiperglicemia induzida por glicocorticoide, história\nfamiliar de DM, HbA1c ? 6%.","D":"Uso de doses mais altas (prednisolona > 20 mg, hidrocortisona > 50 mg, dexametasona > 4 mg),\nlonga duração de tratamento, idade avançada, IMC elevado, intolerância à glicose prévia, história\nde diabetes gestacional, história anterior de hiperglicemia induzida por glicocorticoide, história\nfamiliar de DM, e não por HbA1c ? 6%."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-339758","number":"339758","sourceNumber":"339758","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Um paciente de 80 anos foi admitido no hospital devido a um episódio de fibrilação\natrial de frequência rápida. Familiares\nreferiam também quadro de perda de peso, apatia, declínio\ncognitivo, dispneia e fraqueza muscular ao longo dos últimos seis meses. Qual dos exames abaixo\nserá mais útil para a definição diagnóstica neste caso?","options":{"A":"Holter","B":"TSH","C":"Pet scan","D":"Creatinina","E":"Ressonância de encéfalo"},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-331969","number":"331969","sourceNumber":"331969","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente feminina, 55 anos, é portadora de diarreia crônica, dor em abdome superior, e\ncom úlceras gástricas de localização atípica e de difícil controle. Durante investigação\ndiagnóstica,\naventa-se a hipótese de essa paciente ser portadora da síndrome de Zollinger-Ellison. Nesse caso,\no tumor causador tem como localização mais frequente o:","options":{"A":"Antrogástrico.","B":"Duodeno.","C":"Figado.","D":"Pâncreas.","E":"Colédoco."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-334774","number":"334774","sourceNumber":"334774","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Mulher de 67 anos de idade, com hipertensão arterial compensada em uso de 2 classes\nde medicações anti-hipertensivas. Fez avaliação\nde rotina com dosagem de TSH de 6,4 mUi/L (VR\n0,45 - 4,50). Após 8 semanas repetiu TSH com resultado de 6,0 mUi/L (VR 0,45 - 4,5). De acordo\ncom o Consenso Brasileiro para avaliação e tratamento do hipotireoidismo subclínico em adultos:\nrecomendações do Departamento de Tireoide da SBEM, a conduta inicial para este caso é","options":{"A":"solicitar dosagem sérica de triiodotironina e anticorpos tireoidianos.","B":"iniciar tratamento com levotiroxina em doses baixas com aumento gradual.","C":"acompanhar clínica e laboratorialmente a paciente, sem iniciar o tratamento.","D":"iniciar uso da associalção de levotiroxina e triiodotironina em doses baixas."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-342605","number":"342605","sourceNumber":"342605","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Uma paciente submetida a tireoidectomia total por bócio de grandes dimensões evolui\ncom dispneia intensa, cornagem e estridor assim\nque é retirado o tubo endotraqueal. A\nlaringoscopia mostra cordas vocais paralisadas em adução. Tendo em vista as relações anatômicas\nentre tireoide, traqueia, vasos e nervos da região cervical anterior, provavelmente que estrutura\nfoi\nlesada durante o procedimento operatório?","options":{"A":"nervo laríngeo recorrente","B":"nervo laríngeo superior","C":"músculo cricofaringeo","D":"fáscia pré-vertebral"},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-334775","number":"334775","sourceNumber":"334775","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Rapaz de 28 anos de idade, apresentou diagnóstico de SARS-COV2 há 4 semanas,\ncom sintomas leves, sem necessidade de\ninternação e uso de medicações específicas. Há 2\nsemanas vem evoluindo com recidiva da dor cervical, palpitações, tremores e sudorese excessiva.\nAntecedente familiar de hipotireoidismo. Ao exame: fácies atípica, tireoide aumentada de volume e\ndolorosa á palpação, FC: 102 bpm, PA: 130 x 70 mmHg, tremores, de extremidades. Exames\nlaboratoriais: TSH: < 0,01 MUI/I, VR (0,45 - 4,5), T 4 livre: 1,8 (0,8 - 1,4), anticorpos\ntireoidianos\nnegativos, TRAb negativo. De acordo com o caso relatado, o diagnóstico e a conduta são,\nrespectivamente,","options":{"A":"doença de Graves pelo antecedente familiar e função tireoidiana: iniciar drogas como metimazol.","B":"tireoidite subaguda dolorosa viral: utilizar propranolol, anitinflamatótio e acompanhar\nevolução.","C":"doença de Graves pela história familiar e exames laboratoriais; indicar dose ablativa com iodo\nradioativo e propranolol.","D":"tireoidite subaguda dolorosa viral; utilizar prednisona e metimazol."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-321551","number":"321551","sourceNumber":"321551","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"De acordo com os guidelines da Endocrine Society, qual dos testes iniciais deve ser\nrecomendado para diagnóstico de hipercortisolismo em um paciente com suspeita de síndrome de\ncushing?","options":{"A":"Cortisol salivar no final de noite (2 medidas).","B":"Cortisol sérico com ACTH pela manhã.","C":"Teste de estímulo com ACTH (cortrosina).","D":"Teste de supressão com 8mg de dexametasona."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-330077","number":"330077","sourceNumber":"330077","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente, 50 anos, sexo feminino, apresenta insuficiência adrenal com acometimento\ndo setor hipofisário corticotrófico, com\ncomprometimento da produção de Hormônio\nAdrenocorticotrófico (ACTH) e consequente deficiência de glicocorticoide e andrógenos adrenais,\nsem comprometer a produção de mineralocorticoide, sem escurecimento da pele e mucosas e nem\nhiperpotassemia. É um caso de:","options":{"A":"Insuficiência adrenal primária crônica.","B":"Insuficiência adrenal primária aguda.","C":"Insuficiência adrenal secundária crônica.","D":"Insuficiência adrenal secundária aguda."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-334115","number":"334115","sourceNumber":"334115","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Com relação à produção hormonal do hipotálamo e hipófise, assinale a alternativa\ncorreta.","options":{"A":"Os hormônios CRH, liberador das gonadotrofinas (GnRH), liberador da tireotrofina (TRH) e\nliberador do hormônio do crescimento (GHRH)\nsão produzidos no hipotálamo e alcançam a hipófise\natravés do trato hipotalâmico-hipofisário.","B":"A arginina vasopressina (AVP) é produzida nos neurônios magnocelulares do hipotálamo e\nalcançam a hipófise através do trato hipotalâmico-hipofisário.","C":"O hormônio liberador da AVP é produzido no hipotálamo e é levado à adeno-hipófise por meio\ndo sangue.","D":"Os hormônios CRH, GnRH, TRH e GHRH são produzidos o hipotálamo e alcançam a\nneuro-hipófise por meio do sangue."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-334122","number":"334122","sourceNumber":"334122","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Sobre o prognóstico da Doença de Graves na faixa etária pediátrica, assinale a\nalternativa correta.","options":{"A":"Em geral, não há remissão, e os pacientes utilizam drogas antitireoideanas até a vida adulta.","B":"Cerca de 30% a 50% dos casos apresentam remissão espontânea, permitindo a retirada gradual\nda medicação.","C":"Apenas 10% dos pacientes apresentam remissão espontânea, por isso, frequentemente, há\nindicação de tireoidectomia total.","D":"Apesar de grande parte das crianças apresentarem remissão espontânea, quase todas precisam\nser submetidas à ablação cirúrgica ou química, em\nrazão do alto risco de crise tireotóxica."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-342627","number":"342627","sourceNumber":"342627","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"A causa mais frequente de tireotoxicose é:","options":{"A":"adenoma tóxico","B":"doença de Graves","C":"tireoidite subaguda","D":"bócio multinodular tóxico"},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-334800","number":"334800","sourceNumber":"334800","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"O tratamento dos prolactinomas da hipófise é preferencialmente feito com:","options":{"A":"Cirurgia.","B":"Betabloqueadores.","C":"Inibidor direto da renina.","D":"Agonistas dopaminérgicos."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-334132","number":"334132","sourceNumber":"334132","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Todas as alternativas abaixo apresentam sintomas que são sinais de alarme para crise\ntireotóxica, exceto:","options":{"A":"Icterícia.","B":"Diarreia.","C":"Hipertermia.","D":"Exantema."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-342635","number":"342635","sourceNumber":"342635","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Um recém-nascido de 10 dias é atendido com quadro de icterícia. A mãe relata que ele\npermaneceu internado na maternidade durante 5 dias por ter apresentado hipoglicemia e icterícia.\nO peso e o comprimento ao nascer são 3.000g e 49cm, respectivamente. Ao exame físico,\nmostrou-se ativo, ictérico, com tônus adequado, micropênis e testículos tópicos. Assinale a\nalternativa correta, que apresenta o diagnóstico mais provável:","options":{"A":"síndrome de Noonan","B":"hipotireoidismo congênito","C":"hipopituitarismo","D":"síndrome de Silver-Russe"},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-342636","number":"342636","sourceNumber":"342636","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Um recém-nascido com 2 semanas de vida, mamando exclusivamente ao seio materno,\napresenta perda de peso, recusa alimentar, vômitos, desidratação com sódio = 120mEq/L e\npotássio = 6,5mEq/L, além de glicemia de 40mg/dL. Qual é o diagnóstico mais provável?","options":{"A":"filho de mãe diabética","B":"ingestão insuficiente de leite","C":"hiperplasia adrenal congênita","D":"estenose hipertrófica do piloro"},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-300795","number":"300795","sourceNumber":"300795","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Denomina-se ?hiperaldosteronismo primário? o grupo de doenças em que a produção\nde aldosterona pelo córtex adrenal é\ninapropriadamente elevada, relativamente autônoma em\nrelação ao sistema renina-angiotensina-aldosterona e não pode ser suprimida (ou é apenas\nparcialmente suprimida) por sobrecarga de sódio. Nesse contexto, a etiologia responsável pela\nmaioria dos casos de hiperaldosteronismo primário é:","options":{"A":"Hiperplasia adrenal primária unilateral.","B":"Carcinomas adrenais produtores de aldosterona.","C":"Hiperplasia adrenal bilateral.","D":"Hiperaldosteronismo familial."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-300797","number":"300797","sourceNumber":"300797","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Os prolactinomas, tumores hipofisários produtores de prolactina (PRL), são os\nadenomas hipofisários mais frequentes. Em geral,\nsurgem esporadicamente, mas podem se\nassociar a síndromes genéticas, como neoplasia endócrina múltipla tipo 1 e adenoma hipofisário\nfamiliar isolado. Considerando as manifestações clínicas associadas aos prolactinomas, é\nCORRETO afirmar:","options":{"A":"A hiperprolactinemia leva ao hipogonadismo hipogonadotrófico, principalmente por inibir a\npulsatilidade do hormônio liberador das gonadotrofinas (GnRH).","B":"Clinicamente, as mulheres podem apresentar fase lútea longa, anovulação, infertilidade,\noligomenorreia e amenorreia.","C":"A hiperprolactinemia crônica leva ao aumento da densidade mineral óssea na coluna lombar em\nambos os sexos em razão do hipogonadismo.","D":"A compressão da haste hipofisária, do tecido hipofisário normal ou em decorrência da apoplexia\nhipofisária, leva ao comprometimento dos seios cavernosos."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-300798","number":"300798","sourceNumber":"300798","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"A acromegalia, na maioria dos casos (98%), é causada por um adenoma hipofisário\nsecretor de somatotrofinoma (GH), sendo 70-80%\nmacroadenomas. Carcinomas somatotróficos\nsão extremamente raros. Por ser uma doença com estigmas, o diagnóstico é clínico na maioria dos\ncasos. Os sinais e os sintomas mais comuns na acromegalia em relação ao comprometimento\nosteomuscular são:","options":{"A":"Espessamento da pele, papilomas cutâneos (skin tags), espaçamento dentário.","B":"Espessamento do couro cabeludo, acantose nigricante, hiperidrose, hirsutismo.","C":"Aumento das mãos e do número dos sapatos, aumento do volume do crânio, acentuação dos\nmalares.","D":"Edema de tecidos moles, aumento da cartilagem do nariz e das orelhas, lábios espessados."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-300799","number":"300799","sourceNumber":"300799","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"A Síndrome de Cushing é caracterizada por um grupo de sinais e sintomas que refletem\na exposição prolongada e inapropriada ao\ncortisol. É considerada a etiologia mais prevalente da\nSíndrome de Cushing endógena:","options":{"A":"Corticotrofinoma.","B":"Depressão e outras doenças psiquiátricas.","C":"Etilismo.","D":"Resistência aos glicocorticoides."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-294256","number":"294256","sourceNumber":"294256","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"As doenças osteometabólicas incluem um grupo extenso de afecções que alteram o\nmetabolismo ósseo, resultando, entre outras coisas, em aumento ou redução generalizada da\nmassa óssea. Dentro deste contexto, o hiperparatireoidismo secundário tem relação direta com","options":{"A":"o escorbuto.","B":"a osteodistrofia renal.","C":"o raquitismo.","D":"as mucopolissacaridoses."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-314103","number":"314103","sourceNumber":"314103","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente de 36 anos procurou endocrinologista com queixa de ganho de peso, cerca de\n10 quilos nos últimos seis meses, atribuído\nao isolamento pela pandemia, diminuição da atividade\nfísica e episódios de compulsão alimentar. Ao exame físico, entretanto, chamava atenção a\npresença de estrias violáceas abdominais e hipertensão arterial estágio 2. Iniciada investigação\npara hipercortisolismo, com diagnóstico final de síndrome de cushing ACTHdependente, com\nadenoma hipofisário de 8mm ao exame de imagem. Segundo os Guidelines da Endocrine Society,\nqual conduta inicial seria considerada como terapia de primeira linha nessa paciente?","options":{"A":"Cirurgia para ressecção da lesão hipofisária.","B":"Tratamento medicamentoso com inibidores da esteroidogênese, por tempo indeterminado.","C":"Adrenalectomia bilateral.","D":"Radioterapia."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-294266","number":"294266","sourceNumber":"294266","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente do sexo masculino procurou endocrinologista devido a quadro de obesidade,\ncom ganho de 15 quilos nos últimos seis meses,\nassociado a aumento de apetite. No exame físico,\napresentava índice de massa corpórea de 33 kg/m², hipertensão arterial (154/99 mmHg), aumento\nda circunferência abdominal (108 cm), presença de estrias com 2,0 cm de largura em abdome, de\ntom violáceo. Feita hipótese diagnóstica de síndrome de Cushing. Nesse caso, qual é a conduta\nindicada para confirmação diagnóstica?","options":{"A":"Cortisol sanguíneo pela manhã, colhido em posição supina. Dois valores acima de 30 µg/dl\nconfirmam diagnóstico de síndrome de Cushing.","B":"Solicitar ressonância magnética de sela túrcica. A presença de adenoma hipofisário maior que 5\nmm ratifica diagnóstico de doença de Cushing.","C":"Cortisol sanguíneo com valor acima de 1,8 µg/dl, após supressão com 1 mg de dexametasona\nassociado a cortisol salivar das 23 horas\nelevado, confirma o diagnóstico de hipercortisolismo.","D":"Solicitar tomografia computadorizada de abdome superior. A presença de adenoma adrenal > 7\nmm é diagnóstico de síndrome de Cushing ACTH-independente."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-313198","number":"313198","sourceNumber":"313198","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Uma mulher de 43 anos está em investigação por fraturas recorrentes por pequenos\ntraumas. Antecedentes pessoais: hipertensão\narterial, nefrolitiase e constipação intestinal há 2\nanos. Inventário ósseo: fraturas de rádio e ulna esquerdos e de calcâneos consolidadas,\nosteopenia intensa em ossos da mão e crânio com aspecto ?em sal e pimenta?. O achado\neletrocardiográfico mais provável é:","options":{"A":"ondas T apiculadas","B":"elevação do segmento ST","C":"encurtamento do intervalo QT","D":"bloqueio AV do 2° grau Mobitz ||"},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-295355","number":"295355","sourceNumber":"295355","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente de 25 anos, do sexo feminino, refere ganho de peso excessivo nos últimos\nanos e acredita ser por alteração em\ntireoide. Refere indisposição, fraqueza, queda de cabelo e\nunhas quebradiças. Faz uso de anticoncepcional oral. Ao exame físico: PA: 130/85 mmHg, FC 85\nbpm, peso 85 kg, altura 1,55 m. Exames laboratoriais: TSH ? 5,6 (VR 0,3 a 4,5), T4 livre ? 0,96\nng/dl (VR 0,85 a 1,5 ng/dl), Hb 11,7 g/dl (VR 12 a 16 g/dl), VCM 75 fl (VR 80 a 100 fl), HCM 26 pg\n\n(VR 26 a 32 pg), leucócitos 6.800 (VR 4.000 a 11.000), plaquetas 275.000, CT 210, LDL 150, HDL\n\n35, TGL 180. Nesse caso, em relação ao diagnóstico, sabe-se que:","options":{"A":"A presença de sintomas compatíveis com hipotireoidismo associado a um exame de TSH acima\ndo valor referencial confirma o diagnóstico e indica a reposição imediata de levotiroxina para\nevitar\npiora do quadro clínico.","B":"Seria necessário repetir a dosagem de TSH e, caso o valor seja confirmado, o tratamento com\nlevotiroxina deve ser iniciado, já que a paciente está sintomática.","C":"Não podemos confirmar o diagnóstico de hipotireoidismo, pois os sintomas relatados pela\npaciente podem ter outras causas e é possível\nque a alteração do TSH seja secundária à própria\nobesidade.","D":"Antes de iniciar o tratamento é necessário dosar o selênio e o iodo, pois pode ser necessário\ntratamento prévio com lugol e selênio em caso de deficiências confirmadas."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-313209","number":"313209","sourceNumber":"313209","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Uma mulher de 27 anos refere labilidade emocional, choro fácil, dificuldade para dormir\ne palpitações taquicárdicas. Na avaliação\nclínica, apresenta-se inquieta, com pele quente e úmida e\ntremor fino de extremidades. Sua frequência cardíaca é de 116bpm, e notam-se reflexos\ntendinosos exacerbados. Assinale a alternativa que contém o achado de exame complementar\nmais provável:","options":{"A":"T4 total baixo","B":"T3 indetectável","C":"TSH baixo","D":"T4 livre baixo"},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-316325","number":"316325","sourceNumber":"316325","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Em relação à insuficiência adrenal, marque a alternativa correta:","options":{"A":"São alterações laboratoriais comuns: hipoglicemia, hipocalemia, hipernatremia e hipocalcemia.","B":"A síndrome poliglandular autoimune tipo I ocorre por mutação no gene ATP7B e se caracteriza\npela presença de candidíase mucocutânea,\nhipoparatireoidismo e doença de Addison.","C":"Alguns medicamentos podem causar insuficiência adrenal. Como exemplo, temos o cetoconazol,\nque aumenta a metabolização hepática do cortisol\ne a rifampicina, que inibe a esteroidogênese.","D":"A hiperpigmentação cutânea é um achado da insuficiência adrenal primária, não ocorrendo na\ninsuficiência adrenal secundária e aparece por aumento do MSH (melanocyte-stimulating hormone).\nO MSH estimula os melanócitos."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-315809","number":"315809","sourceNumber":"315809","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente de 52 anos de idade, masculino, procura atendimento médico ambulatorial\ndevido a picos hipertensivos frequentes nos\núltimos meses. Relata que há aproximadamente 3\nmeses vem apresentando picos hipertensivos esporádicos (aproximadamente 2 picos semanais\nisolados), com necessidade de controle pressórico com medicamentos orais. Nega uso contínuo de\nanti-hipertensivos. Devido ao aumento da frequência dos episódios, optou por procurar atendimento\nmédico. Relata ganho ponderal importante nos últimos meses, sem alteração de dieta ou exercício\nfísico, associado a dispneia progressiva. Nega febre. Nega tosse. Nega outras comorbidades. Nega\ncirurgias prévias. Ao exame físico: bom estado geral, corado, hidratado, eupneico, anictérico,\nacianótico, fáscies ?em lua cheia?. Bulhas rítmicas, normofonéticas, sem sopros. Murmúrio\nvesicular presente bilateral, com discretos estertor difusos. Abdome em avental, com estrias\nvioláceas, indolor a palpação, sem massas palpáveis. Pressão Arterial - Membro superior direito:\n160 x 100 mmHg Pressão Arterial - Membro superior esquerdo: 159 x 100 mmHg Glicemia em\njejum - 152 mg/dl (teste de triagem Realizou ultrassonografia abdominal que evidenciou massa em\ntopografia de loja renal esquerda, sem contornos definidos. Realizou, então, a tomografia e a\nradiografia de tórax abaixo. A principal hipótese diagnóstica é:","options":{"A":"Adenoma de suprarrenal.","B":"Aldosteronoma.","C":"Carcinoma adrenocortical.","D":"Adenocarcinoma ductal de pâncreas."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-317211","number":"317211","sourceNumber":"317211","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente de 28 anos de idade, em acompanhamento por hipotireoidismo, decorrente de\ntireoidite de Hashimoto, vem em consulta na UBS para reavaliação clínica. Refere sonolência\ndiurna e piora do hábito intestinal com tendência a constipação. Faz uso diário de levotiroxina\n125mcg, omeprazol 20mg e carbonato de cálcio 500mg pela manhã. Ao exame físico, peso: 55kg,\nPA: 120x80 mmHg, FC: 62 bpm, tireoide com volume diminuído sem outras alterações. Os exames\nlaboratoriais mostram: TSH: 18,0 mUl/L (VR: 0,45-4,5) e T4 livre: 0,5 ng/dL (VR: 0,6-4,5). É\nCORRETO afirmar que:","options":{"A":"A paciente está em hipotireoidismo subclínico, o que não justifica os sintomas. Outras causas\ndevem ser investigadas.","B":"É necessário verificar se a administração da levotiroxina está sendo feita da forma preconizada.","C":"Os sintomas podem ser pelo hipotireoidismo, pois a paciente recebeu dose insuficiente de\nlevotiroxina para o seu peso, devendo-se aumentar a dose.","D":"Os sintomas podem ser pelo hipotireoidismo, devendo ser associada reposição de T3, pois é\npossível que a paciente apresente defeito na desiodase responsável pela conversão de T4 em T3."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-308295","number":"308295","sourceNumber":"308295","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"A hiperplasia adrenal congênita (HAC) é uma doença com significativa\nmorbimortalidade, frequentemente subdiagnosticada.\nSobre a HAC, marque a alternativa incorreta.","options":{"A":"A HAC é um conjunto de doenças, de herança autossômica recessiva, potencialmente letal,\nresultantes da deficiência de uma das\nenzimas responsáveis pela síntese de cortisol nas glândulas\nadrenais.","B":"A HAC faz parte da triagem neonatal em nosso estado, através do teste do pezinho.","C":"As formas clínicas da HAC são tradicionalmente divididas em dois grandes grupos: Forma\nclássica e Forma não clássica.","D":"A Forma não clássica, cujos sintomas se manifestam ao nascimento, é subdividida em forma\nperdedora de sal, e possui como sintomas a virilização da genitália externa, surgimento precoce\ndos pêlos pubianos e aumento da massa muscular."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-300992","number":"300992","sourceNumber":"300992","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"O eritema necrolítico migratório é uma rara condição cutânea que se apresenta como\nlesões eritematosas, migratórias, com vesículas e bolhas na superfície, evoluindo para cura com\nhiperpigmentação. É fortemente associado com:","options":{"A":"Gastrínoma.","B":"GIST - tumor estromal.","C":"Insulinoma.","D":"Glucagonoma."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-258153","number":"258153","sourceNumber":"258153","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"A vitamina D exerce um importante papel na homeostase do cálcio. A vitamina D:","options":{"A":"Tem no calcidiol sua forma mais ativa.","B":"Sofre um primeiro processo de metabolização no fígado pela enzima 1-?-hidroxilase.","C":"Após primeira etapa de metabolização é transportada ao pulmão para segunda etapa de\nhidroxilação.","D":"Após ser hidroxilada pela 24-?-hidroxilase atuará no osteoblasto."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-257906","number":"257906","sourceNumber":"257906","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente do sexo feminino, de 64 anos, com diagnóstico de hipotireoidismo há vários\nanos, com dose estável de levotiroxina (75\nmicrogramas/dia). Sempre em eutiroidismo na avaliação\nhormonal realizada semestralmente. Há nove meses, vem apresentando aumento de peso\ngradativo (cerca de 7 kg) e há seis meses início de sintomas gastrointestinas. Realizado o\ndiagnóstico de doença do refluxo. Orientada a realizar medidas de mudanças no estilo de vida e\niniciado tratamento com pantoprazol - 40 mg/dia. Exame atual de função tireoidiana com T4 livre de\n0,8 ng/dL (VR: 0,89 - 1,76 ng/dL) e TSH de 11,5 µUI/mL (VR: 0,48-5,6 µ UI/mL). Nesse caso, qual a\nconduta inicial mais correta para essa paciente?","options":{"A":"Avaliar aderência através de teste de absorção de levotiroxina.","B":"Manter dose de levotiroxina, observando as elevações discretas de TSH, que são características\nfisiológicas no paciente idoso.","C":"Aumentar dose de levotiroxina, ajustando para as variáveis do aumento de peso e provável\ndiminuição da absorção pela elevação do pH gástrico.","D":"Acrescentar triiodotironina (T3) para melhor supressão do eixo."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-257909","number":"257909","sourceNumber":"257909","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"A hiperplasia adrenal congênita por deficiência da 21-hidroxilase forma não clássica, é\ncaracterizada por uma forma clínica mais branda, por apresentar uma atividade enzimática residual\nda enzima CYP21A2, sem perda de sal, porém com níveis de androgênios adrenais ligeiramente\nelevados. Apresenta dificuldades na avaliação e tratamento, sendo frequentemente diagnosticada\nerroneamente como síndrome de ovários policísticos. Em relação a essa doença,","options":{"A":"segundo a Endocrine Society, o exame de screening recomendado é a dosagem de\n17-OH-progesterona basal, pela manhã, na fase folicular.","B":"a presença de ovários policísticos ao exame de ultrassom exclui o diagnóstico.","C":"o cortisol elevado na urina de 24 horas associado a elevação de níveis plasmáticos de SDHEA\nsugerem o diagnóstico.","D":"confirmado diagnóstico, o tratamento com glicocorticoide deve ser instituído imediatamente, de\nforma contínua, sem interrupção."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-273131","number":"273131","sourceNumber":"273131","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Corticoide ou corticosteroide é um grupo de hormonas esteroides produzidas pelas\nglândulas suprarrenais ou a derivados sintéticos destas. Se dividem em glicocorticoides,\nmineralocorticoides e 17-cetosteroides. Considerando o enunciado, é CORRETO afirmar:","options":{"A":"A descontinuidade do tratamento deve ocorrer de forma súbita.","B":"Apresentam efeito orexígeno e euforizante.","C":"São utilizados somente no tratamento da dor associada a lesões traumáticas e neoplásicas do\nsistema nervoso periférico.","D":"Podem ser empregados apenas por VO (Dexametasona, Deflazacort, Prednisolona) e IM\n(Hidrocortisona, Dexametasona, Betametasona, Metilprednisolona)."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-257910","number":"257910","sourceNumber":"257910","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente encaminhado ao serviço de endocrinologia para avaliação hormonal devido ao\nquadro de oligospermia. Referia facilidade para ganho de peso, leve adinamia, libido diminuído e\ncefaleia ocasional. Negava alteração visual. Antecedente de TCE por acidente automobilístico há\nsete anos, tendo permanecido em coma por 27 dias. Exames laboratoriais iniciais: provas de\nfunção hepática normais, anemia (hb: 12,3%) e testosterona: 39 ng/dL (VR: 241-827 ng/dL).\n\nSolicitado novos exames: Na: 139 mmol/L, K: 4,3 mmol/L; IGF-1: 49 ng/mL (VR: 2,1 -17,7 ng/mL);\n\nFSH: 2,02 mUI/mL; LH: 1,19 mUI/mL; testosterona: 34 ng/dL (VR: 241,0 a 827,0 ng/dL); T4 livre:\n\n0,6 ng/dL (VR: 0,89 - 1,76 ng/dL), TSH: 0,9 µUI/mL (VR: 0,48-5,6 µUI/mL), Cortisol 8 h: 21 mcg/dL\n(VR: 5,3-22,5 mcg/dL), ACTH: 19,5 pg/mL (VR:\naté 46 pg/mL). RNM de sela túrcica normal, sem\nlesão expansiva. Diante do quadro clínico, qual a melhor conduta?","options":{"A":"Reposição de glicocorticoide, testosterona, hormônio de crescimento e da tireoide, pois o\npaciente apresenta pan-hipopituitarismo.","B":"Necessário avaliar eixo adrenocorticotrófico, com teste de estímulo (hipoglicemia ou cortrosina),\nantes de iniciar reposição de hormônio\ntireoidiano.","C":"Necessário avaliar eixo adrenocorticotrófico, com teste de supressão com 1 mg de\ndexametazona às 23 horas e coleta de cortisol às 8 horas na manhã seguinte, para avaliar\nnecessidade de glicocorticoide.","D":"Reposição de GH, hormônio tireoidiano e testosterona. Eixo adrenocorticotrófico preservado,\nsem necessidade de reposição de glicocorticoide."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-257912","number":"257912","sourceNumber":"257912","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente procurou reumatologista devido à poliartralgia. No exame físico, chamava\natenção a fronte abaulada com prognatismo,\nsugerindo quadro clínico de acromegalia,\nposteriormente confirmada por exames laboratoriais e pela presença de um macroadenoma\nhipofisário (1,5 cm diâmetro), com invasão suprasselar. Submetido a tratamento cirúrgico, com\nremoção aparente de toda massa tumoral. Após quatro meses da cirurgia, paciente se apresentava\nassintomático. Exames laboratoriais realizados no pós-operatório revelaram um nadir de 0,2 ng/mL\ndo hormônio de crescimento na curva glicêmica e valores de IGF1 na faixa normal para idade e\nsexo. De acordo com as recomendações da SBEM, qual conduta é considerada mais adequada\npara este paciente?","options":{"A":"Iniciar tratamento imediato com análogo de somatostatina.","B":"Iniciar tratamento com agonista dopaminérgico.","C":"Iniciar tratamento com antagonista do receptor de GH.","D":"Manter sem medicação para acromegalia, apenas com dosagem de GH e IGF-1 a cada seis\nmeses."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-281980","number":"281980","sourceNumber":"281980","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"A doença que se apresenta com bócio, exoftalmia, dermopatia e aumento na produção\ndos hormônios tireoidianos é a:","options":{"A":"Doença de Graves.","B":"Tireoide de Hashimoto.","C":"Tireoide de Riedel.","D":"Tireoide de Quervain."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-258172","number":"258172","sourceNumber":"258172","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Homem de 85 anos, com hipertensão e dislipidemia, veio encaminhado por apresentar\nTSH: 7,5 mUI/L (0,4?4,0). Repetiu exames:\nTSH: 6,4 mUI/L (0,4?4,0), T4 livre: 1,2 ng/dl (VR:\n0,8?1,8), anticorpos antitireoperoxidase e antitireoglobulina negativos. Nesse caso, qual é a\nconduta mais apropriada?","options":{"A":"Observar sem reposição de levotiroxina e repetir os exames com intervalo de seis meses.","B":"Iniciar levotiroxina em dose baixa com aumento gradual até dose efetiva.","C":"Iniciar dose plena de levotiroxina.","D":"Prescrever lugol a 5%; três gotas por dia durante 30 dias e repetir função tireoidiana."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-281284","number":"281284","sourceNumber":"281284","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"É a causa mais comum de Hiperparatireoidismo Primário:","options":{"A":"Adenoma.","B":"Hiperplasia primária.","C":"Carcinoma.","D":"Tireoidite."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-274476","number":"274476","sourceNumber":"274476","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente 26 anos, sexo feminino vem ao pronto atendimento com queixa de mal estar,\nhistórico de nictúria recorrente há mais de 3 meses e que percebeu alteração domiciliar da pressão\narterial. Nega histórico de doenças prévias. Nega uso de medicações ou substâncias ilícitas. Ao\nexame físico PA 140/90 mmHg em ambos MMSS. Sem outros achados de exame físico.\n\nConsiderando o diagnóstico sindrômico descrito e os dados do contexto, a causa etiológica mais\nprovável seria:","options":{"A":"Glomerulonefrite aguda.","B":"Hiperaldosteronismo primário.","C":"Feocromocitoma.","D":"Estenose de artéria renal."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-274477","number":"274477","sourceNumber":"274477","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente 26 anos, sexo feminino vem ao pronto atendimento com queixa de mal estar,\nhistórico de nictúria recorrente há mais de 3 meses e que percebeu alteração domiciliar da pressão\narterial. Nega histórico de doenças prévias. Nega uso de medicações ou substâncias ilícitas. Ao\nexame físico PA 140/90 mmHg em ambos MMSS. Sem outros achados de exame físico. Qual dado\ndiagnóstico possui baixa sensibilidade na avaliação clínica em pacientes com o referido\ndiagnóstico?","options":{"A":"Nível sérico de K+ abaixo do valor de referência.","B":"Nível sérico de aldosterona.","C":"Nível sérico de renina.","D":"Relação aldosterona/renina."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-274778","number":"274778","sourceNumber":"274778","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente, 38 anos, sexo masculino, dá entrada no pronto atendimento conduzido por\nfamiliares devido quadro de letargia há 12 horas. O mesmo não consegue se comunicar bem no\nmomento. Familiares referem que paciente vem apresentando, há 3 meses, dificuldade de\nconcentração, mudança de humor e se comportando diferente do habitual. Além disso, referem que\npaciente apresentou perda de peso nos últimos 2 meses. O mesmo não apresenta histórico de\nantecedentes pessoais. Ao exame físico, o que chama atenção é, além do emagrecimento,\nmudança da pigmentação na palma das mãos e em mucosa oral, com lesões hipercrômicas.\n\nConsiderando o contexto do quadro clínico, a principal hipótese diagnóstica e a causa da\nmanifestação inicial descrita é:","options":{"A":"neoplasia endócrina múltipla tipo 1 / hipomagnesemia.","B":"insuficiência supra renal / hipercalcemia.","C":"tuberculose ganglionar / hiponatremia.","D":"acidose tubular renal tipo V / hiponatremia."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-281288","number":"281288","sourceNumber":"281288","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Incidentaloma de adrenal é definido por um nódulo ou massa incidental da suprarrenal\nencontrado em um exame de imagem do abdome realizado para investigação de queixas não\nrelacionadas a esta glândula. Das alternativas abaixo, assinale a que apresenta a característica\ntomográfica sugestiva de benignidade para incidentaloma de adrenal.","options":{"A":"Tamanho > 6 cm.","B":"Presença de conteúdo cístico intra-lesional.","C":"Invasão da veia cava inferior.","D":"Densidade menor que 1 UH (Unidade Hounsfield)."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-277434","number":"277434","sourceNumber":"277434","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Uma mulher de 22 anos apresenta ciclos menstruais irregulares há cerca de 10 meses,\ncom períodos de amenorreia, negando uso de\nmedicamentos. Não tem parceiros sexuais há 2\nanos. Os exames físico geral e ginecológico eram normais. A dosagem de prolactina ETA elevada\n(150ng/dL) revelou TSH e T4 livres normais. A ressonância magnética de sela túrcica revelou um\nmacroadenoma hipofisário. A conduta é:","options":{"A":"uso de agonistas da dopamina","B":"uso de agonistas do GnRH","C":"uso de contraceptivos hormonais orais","D":"radioterapia"},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-273195","number":"273195","sourceNumber":"273195","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"A doença suprarrenal que consiste na alteração física e mental causada pelo excesso\nde cortisol no organismo por um longo período,\nque causa ganho de peso, diabetes, hipertensão,\nface de lua cheia e é diagnosticada por meio de exames de sangue, urina ou saliva é a(o):","options":{"A":"Hiperaldosteronismo.","B":"Síndrome de Cushing.","C":"Insuficiência adrenal.","D":"Hiperplasia adrenal congênita."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-241686","number":"241686","sourceNumber":"241686","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Mulher de 26 anos é admitida no pronto-atendimento com queixa de taquicardia. Ao\nexame físico, apresenta exoftalmia, mãos\númidas e trêmulas, FC: 140 bpm, Tax 37,1°C. O exame\nneurológico identificou desorientação, agitação e hiperreflexia. Medicada na internação com\npropiltiouracil. A estratégia para inibir a liberação do hormônio pré-formado consiste na\nadministração de:","options":{"A":"amiodarona.","B":"iodeto de potássio.","C":"metimazol.","D":"propranolol.","E":"verapamil."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-231933","number":"231933","sourceNumber":"231933","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Uma paciente de 39 anos, branca, secretária executiva em uma multinacional, refere\nalteração nos olhos após viagem ao exterior, a trabalho. Refere antecedente de tireoidopatia\ntratada há mais de 3 anos e não sabe referir o medicamento utilizado na época, mas nega uso de\nradioiodo e cirurgia na região tireoidiana. Além das alterações oculares, refere estar com insônia,\nirritação e palpitações. Sem outras queixas e sem outros antecedentes patológicos, refere\ntabagismo, mas nega etilismo e uso de medicações no momento. Ao exame físico: exoftalmo\ndiscreto bilateral, lagoftalmo bilateral, tremores de pálpebras e extremidades, bócio difuso, PA =\n160x70 mmHg, FC = 120 bpm, mais nada digno de nota. Trouxe exames laboratoriais solicitados\npelo médico do trabalho: TSH suprimido com T4 livre elevado, hemograma e funções renal e\nhepática dentro da normalidade. Assinale a alternativa correta:","options":{"A":"o hipertireoidismo subclínico que a paciente apresenta deve ser tratado com radioiodoterapia\nseguida pelo uso de tireia, pois já apresentou esse\nquadro","B":"o diagnóstico de hipotireoidismo deve ser pensado, pois a paciente já apresentou um quadro\nanterior e a recorrência justifica o seu tratamento imediato","C":"no momento, a conduta inicial pode ser feita com o emprego de medicações da classe das\ntioureias ou tionamidas e solicitação de exames de controle","D":"o tratamento com levotiroxina deve ser iniciado imediatamente, pois a paciente apresenta\nsintomatologia e exames laboratoriais alterados","E":"o quadro clínico e laboratorial sugere o diagnóstico de doença de Basedow-Graves e necessita\nde tratamento imediato com levotiroxina sódica e\npropranolol, seguido por cirurgia para o\ntratamento definitivo"},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-241687","number":"241687","sourceNumber":"241687","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Mulher de 32 anos em investigação para astenia crônica. Na avaliação laboratorial,\nencontra-se TSH < 0,01 mcU/L e T4 livre < 0,1 ng/ml. A próxima etapa da investigação clínica\nbaseia-se em:","options":{"A":"cintilografia da tireoide.","B":"anticorpo antirreceptor de tireotrofina (TRAb).","C":"anticorpo antitireoperoxidase (anti-TPO).","D":"ultrassonografia da tireoide.","E":"ressonância magnética da sela turca."},"answer":"E","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-254212","number":"254212","sourceNumber":"254212","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Mariana acompanha o ambulatório de cardiologia e hoje recebe 4 pacientes, que\nreceberão sua primeira avaliação com\nespecialistas, após diagnóstico recente de hipertensão.\nPaciente 1 - homem, 49 anos, relatos de valores elevados de PA há cerca de 10 anos, sem\ntratamento ou seguimento; exames alterados: presença de microalbuminúria. Paciente 2 - mulher,\n32 anos, antecedente de nódulo de adrenal em seguimento conservador; exames alterados:\nhipercalemia. Paciente 3 - homem, 35 anos, apresenta episódios de cefaleia, sudorese, palpitação,\nassociados a picos hipertensivos. Paciente 4 - homem, 55 anos, apresenta ao exame físico\npresença de sopro abdominal. Baseado nos dados acima, assinale alternativa que indica o paciente\nque Mariana deveria suspeitar de HAS secundária e a etiologia mais provável:","options":{"A":"Paciente 1 - glomerulonefrite primária.","B":"Paciente 2 - hiperaldosteronismo.","C":"Paciente 3 - feocromocitoma.","D":"Paciente 4 - aneurisma de aorta."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-246522","number":"246522","sourceNumber":"246522","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Mulher, 45 anos, apresentando quadro de irritabilidade, alopecia, intolerância ao calor,\ntaquicardia, proptose palpebral, foi submetida à avaliação laboratorial. Qual resultado melhor se\nencaixa ao quadro clínico?","options":{"A":"TSH elevado, T4 livre elevado, T3 diminuído.","B":"THS elevado, T4 livre diminuído, T3 diminuído","C":"TSH suprimido, T4 livre diminuído, T3 diminuído.","D":"TSH suprimido, T4 livre aumentado, T3 aumentado.","E":"TSH elevado, T4 livre diminuído, T3 aumentado."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-249842","number":"249842","sourceNumber":"249842","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"M.D.S.N., de 70 anos, do sexo feminino, chega ao pronto-socorro com queixa de\nformigamentos e dormência em extremidades, com início há um dia. Refere também fadiga e\nsensação de palpitações. Não apresenta outras queixas e estava assintomática antes do início do\nquadro. O exame físico geral é normal, com exceção de incisão em região cervical anterior, que,\nquando interrogada, a paciente diz se dever a uma cirurgia realizada há cinco dias, \"para retirar a\ntireoide\", não sabendo informar mais detalhes. Tem como comorbidades, transtorno de ansiedade\ngeneralizada e diabetes mellitus. O diagnóstico e a etiologia para o caso apresentado são,\nrespectivamente:","options":{"A":"hipercalcemia - adenoma de paratireoides.","B":"polineuropatia periférica - diabetes mellitus.","C":"hipocalcemia - hipoparatireoidismo pós-manipulação.","D":"crise de ansiedade - síndrome do pânico."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-248904","number":"248904","sourceNumber":"248904","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Nas situações de diagnóstico do hipotireoidismo e do hipertireoidismo primários, a\ndosagem sérica do TSH é o teste mais confiável.\nPorém, em determinadas situações, essa\ndosagem pode apresentar algumas limitações na avaliação da função tireoidiana. Dessa forma:","options":{"A":"níveis séricos diminuídos de hormônios tireoidianos são acompanhados de concentrações\nelevadas de TSH nos usuários de biotina em altas\ndoses, sem correlacionar com doença clínica","B":"pacientes com hipotireoidismo sem adesão ao tratamento e que fazem uso adequado de\nlevotiroxina semanas antes da coleta de sangue\npodem apresentar valores séricos baixos de TSH e\naltos de hormônios tireoidianos","C":"pacientes com disfunção tireoidiana crônica e grave podem apresentar o TSH ainda alterado,\napesar da normalização dos níveis séricos\ndos hormônios tireoidianos","D":"medicações como dopamina e glicocorticoides têm ação estimuladora na secreção do. TSH,\npodendo mimetizar o hipertireoidismo primário"},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-254216","number":"254216","sourceNumber":"254216","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente em investigação de doença adrenal retorna com exames solicitados na última\nconsulta: aldosterona elevada (mesmo após teste com infusão salina); atividade plasmática da\nrenina reduzida; sódio urinário elevado; cateterismo de veias adrenais com coleta de sangue para\ndosagem de aldosterona revelou secreção unilateral de aldosterona. Qual o provável diagnóstico\nda paciente?","options":{"A":"Síndrome de Liddle.","B":"Síndrome de Conn.","C":"Hiperaldosteronismo idiopático.","D":"Hiperaldosteronismo secundário."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-249850","number":"249850","sourceNumber":"249850","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"No hipertireoidismo apatético,","options":{"A":"em crianças, há predomínio de sintomas adrenérgicos, como irritabilidade, nervosismo,\nagressividade e sudorese.","B":"em idosos, são predominantes sintomas cardiovasculares, depressão, labilidade emocional,\nprostração e apatia.","C":"em crianças, são observados diminuição da velocidade de crescimento, baixa estatura e baixo\npeso.","D":"em idosos, são recorrentes os sintomas adrenérgicos, como agitação, nervosismo,\nagressividade e sudorese."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-232227","number":"232227","sourceNumber":"232227","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Leia o caso clínico a seguir. Paciente de 51 anos, do sexo masculino, com diagnóstico\nde diabetes mellitus tipo 2 e HAS, há cinco\nanos. Durante consulta de rotina com endocrinologista,\napresentou queixa de artralgia em várias articulações associada a hiperidrose e, ao exame físico,\npresença de discreto prognatismo, o que suscitou hipótese diagnóstica de acromegalia, confirmada\nposteriormente com a dosagem de GH basal de 7,6 ng/mL (VR homem: inferior ou igual a 3,00) e\nIGF-1 de 446 ng/mL (VR 50 a 54 anos: 48 a 209). A ressonância magnética revelou massa selar\nsólida, de 1,9 cm em seu maior diâmetro, sem expansão extrasselar, nem compressão de quiasma\nóptico. Nesse caso, qual tratamento primário de escolha deve ser indicado para esse paciente?","options":{"A":"Cirurgia transesfenoidal, realizada preferencialmente em centro especializado de referência.","B":"Antagonista do receptor de GH, representado pelo pegvisomanto (PEG).","C":"Análogos de somatostatina, como o octreotide.","D":"Agonistas dopaminérgicos, como a cabergolina."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-234328","number":"234328","sourceNumber":"234328","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Homem de 45 anos relata perda de aproximadamente cinco kg (5% do peso) em um\nmês, após quadro com febre e odinofagia de remissão espontânea. Nega alterações oculares.\n\nSente dor cervical à palpação e à deglutição, insônia, palpitações e aumento do número de\nevacuações diárias. Refere estar em uso de\nsuplementos \"termogênicos\" para melhorar sua\ndisposição para atividades físicas, há seis meses. Traz em mãos os seguintes exames: TSH = 0,01\nuIU/ml (VR 0,5 - 4,5 uIU/ml), T4 livre = 2,77 ng/dl (VR 0,7-1,5), tireoglobulina 250 ng/ml (VR:\n\n1,5-50), antitireoperoxidase e TRAb negativos. Nesse caso, o exame que melhor elucidaria o\nquadro atual e o provável diagnóstico desse paciente são:","options":{"A":"T3 total e tireotoxicose exógena.","B":"T4 total e bócio multinodular tóxico.","C":"VHS e tireoidite subaguda.","D":"Antitireoglobulina e doença de Graves."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-247415","number":"247415","sourceNumber":"247415","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente é readmitido no hospital no quarto dia pós-tireoidectomia total por carcinoma\npapilífero, apresentando rouquidão importante e sinal de Chvostek. A conduta mais apropriada é:","options":{"A":"observar, pois as alterações são comuns e transitórias.","B":"iniciar reposição de cálcio devido a hipoparatireoidismo.","C":"acionar o cirurgião devido à suspeita de hematoma cervical compressivo.","D":"ajustar a reposição de hormônio tireoideano, insuficiente."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-252753","number":"252753","sourceNumber":"252753","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente do sexo feminino, 36 anos, procura atendimento referindo palpitações, tremor\nde extremidades, insônia, perda ponderal de 15 kg\nnos últimos 30 dias e diarreia. Ao exame,\nobserva-se pele quente e úmida, frequência cardíaca de 120 bpm e pressão arterial de 140 x 90\nmmhg. Exames laboratoriais mostram: TSH: 0,001 MUI/l (Valores de referência: 0,4 a 4,3); T4 livre:\n2,5 ng/dl (0,7 a 1,8)), Glicemia de jejum: 80 bpm; Colesterol total: 180 mg/dl; HD-colesterol: 47\nmg/dl ; LDL-colesterol: 100 mg/dl, triglicerídeo: 100 mg/dl. Ultrassonografia da tireoide mostra\nnódulo hiperecogênico, TI-RADS 3, de 1,2 cm, no lobo esquerdo da tireoide. Diante desse caso,\nqual exame deve ser solicitado?","options":{"A":"Cintilografia da tireoide.","B":"Punção aspirativa por agulha fina da tireoide.","C":"Teste genético para avaliação do nódulo.","D":"Ressonância nuclear magnética do pescoço."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-252757","number":"252757","sourceNumber":"252757","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente do sexo feminino, 35 anos, procura atendimento referindo episódios\nrecorrentes de cefaleia, sudorese e\npalpitação. Portadora de hipertensão arterial de difícil controle,\nmesmo em uso de anlodipina 10 mg/dia, losartana 100 mg/dia e hidroclorotiazida 25 mg/dia. Está\nmuito preocupada, pois fez uma tomografia de abdome que mostrou uma massa na adrenal direita.\nRefere ter sido submetida a tireoidectomia total há 3 anos, por um carcinoma medular da tireoide.\nDiante do caso, quais exames seriam interessantes para o diagnóstico?","options":{"A":"Aldosterona sérica e cortisol sérico matinal.","B":"Cálcio sérico e metanefrinas urinárias.","C":"Cobre urinário e atividade de renina plasmática.","D":"Ureia e magnésio sérico."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-249511","number":"249511","sourceNumber":"249511","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Mulher de 56 anos procura atendimento médico ambulatorial queixando-se de diarreia\nde início há 3 meses, perda de peso,\ncalafrios e tremores sem causa aparente. Nega febre aferida.\nQueixa-se também de baixa acuidade visual. Nega alteração de hábitos rotineiros, alimentares e\nintrodução/suspensão de drogas de uso contínuo. Notou que há aumento de seu pescoço, relatado\ncomo \"inchaço\". Na investigação apresentou tireóide aumentada difusamente à palpação, níveis de\nT4 elevado, TSH suprimido e anticorpos anti-tireoideanos não detectáveis. Ecografia de tireóide\nevidenciou glândula difusamente aumentada. A cintilografia com iodo 131 evidenciou uma área\nautônoma funcional bem localizada e restante da glândula suprimida (não captante). A principal\nhipótese diagnóstica é:","options":{"A":"Doença de Plummer.","B":"Doença de Graves.","C":"Doença de Paget.","D":"Arterite de Takayasu."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-249513","number":"249513","sourceNumber":"249513","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente de 26 anos procura pronto-socorro queixando-se de forte mialgia e câimbras\nconstantes que pioraram há 1 semana. Nega febre. Nega trauma. Vem apresentando crises\nhipertensivas recorrentes, já em uso de losartana 100mg/dia, anlodipino 10mg/dia e bisoprolol\n5mg/dia, sem melhora. Após coleta de rotina laboratorial em pronto-socorro foi internada por\nhipocalemia. Submeteu-se à tomografia de abdome abaixo. O provável diagnóstico é:","options":{"A":"Leptospirose.","B":"Paraganglioma.","C":"Adenoma adrenal.","D":"Hipoaldosteronismo - NEM 1."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-229876","number":"229876","sourceNumber":"229876","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente jovem apresentando palpitação, procura cardiologista que descarta causas\ncardíacas. Suspeita de origem endocrinológica\ne solicita exames de tireoide que revelam: TSH 0.01\nmU/L, T3 250 ng/dl, T4 livre 2.5 ng/dl, T4 25ng/dl, tireoglobulina 1.0 ng/ml, cintilografia com\nbaixa\ncaptação. Valores de referência: TSH 0,3 e 4,0 mU/L, T3 80 a 180 ng/dl, T4 livre 0.7-1.8 ng/dl, T4\ntotal 4,5 a 12.6 mg/dl, tireoglobulina 2,0 a 60,0 ng/MI. O provável diagnóstico é","options":{"A":"a doença de Graves","B":"o bócio nodular tireotóxico","C":"tireoidite factícia","D":"tireoidite subaguda"},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-229561","number":"229561","sourceNumber":"229561","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente de 53 anos, diagnosticado pelo endocrinologista com Hiperparatireoidismo\nprimário. Qual a causa MAIS comum deste\ndesequilíbrio hormonal?","options":{"A":"carcinoma medular de tireoide.","B":"neoplasia endócrina múltipla tipo 2A.","C":"neoplasia de hipófise.","D":"adenoma único de paratireoide."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-229566","number":"229566","sourceNumber":"229566","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"NÃO faz parte das causas fisiológicas de hiperprolactinemia:","options":{"A":"estresse.","B":"gestação.","C":"estimulação de mamilos.","D":"hipertiroidismo."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-217004","number":"217004","sourceNumber":"217004","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Sobre as substâncias que interferem na absorção da levotiroxina no tratamento do\nhipotireoidismo, julgue os itens a seguir. I. Carbonato de cálcio. II. Hidróxido de alumínio. III.\nOmeprazol. IV. Sulfato ferroso. Pode-se afirmar que:","options":{"A":"Apenas I e II estão certos.","B":"Apenas I e III estão certos.","C":"Apenas II, III e IV estão certos.","D":"Apenas I, III e IV estão certos.","E":"Todos estão certos."},"answer":"E","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-201669","number":"201669","sourceNumber":"201669","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Leia o caso clínico a seguir. Paciente de 24 anos, do sexo masculino, apresentando\nfebre, sudorese e palpitações. Ao exame físico, a\npressão arterial encontra-se em 180/110 mmHg.\nQue exame poderia auxiliar fortemente no seu diagnóstico?","options":{"A":"Dosagem de sódio urinário.","B":"Dosagem de serotonina urinária.","C":"Dosagem de metanefrina urinária.","D":"Dosagem de creatinina urinária."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-216686","number":"216686","sourceNumber":"216686","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Mulher de 28 anos queixa irritação, tremores, nervosismo e perda ponderal de 7kg em 2\nmeses, após ter iniciado tratamento para emagrecimento. O exame físico revela taquicardia e\nhipertensão arterial. Os exames complementares apresentaram TSH indetectável, VHS normal,\ntireoide homogênea a ultrassonografia, e captação baixa de iodo marcado à cintilografia. O\ndiagnóstico para esse quadro é:","options":{"A":"Tireoidopatia factícia.","B":"Doença de Basedow-Graves.","C":"doença de Plummer.","D":"Tireoidite de De Quervain."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-201731","number":"201731","sourceNumber":"201731","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Leia o caso clínico a seguir. Mulher de 42 anos procura assistência médica por causa\nde alteração de função tireoidiana. Refere\natividade física intensa e que, após um treino,\napresentou dor lombar de grande intensidade com irradiação para parte posterior de membro\ninferior esquerdo, sendo prescritos fisioterapia e glicocorticoide injetável intramuscular de\ndepósito\nhá uma semana (três ampolas). Ciclos menstruais regulares, em uso de contraceptivos orais. PA =\n120 x 80 mmHg; FC = 70 BPM, com ritmo cardíaco regular. Tireoide normopalpável. Traz os\nexames: TSH = 0,3 mUI/L (VR 0,4 a 4,0); T4 livre = 1,4 ng/dl (VR 0,8 a 1,9); T3 = 1,4 ng/ml (VR 0,7\na 1,8); TRAb = 0,1 UI/L (VR < 1,75); ATPO = 30 UI/ml (VR < 35); antitireoglobulina = 15 UI/ml (VR <\n20). Qual é a provável causa da alteração no TSH desta paciente?","options":{"A":"Doença de Graves.","B":"Uso de contraceptivo oral.","C":"Hashitoxicose.","D":"Uso de glicocorticoide."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-214970","number":"214970","sourceNumber":"214970","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"A doença de Graves, a forma mais comum de hipertireoidismo, quando acomete\nmulheres grávidas apresenta características e cuidados específicos. Assinale a alternativa\nincorreta:","options":{"A":"a crise tireotóxica, decorrente do hipertireoidismo na gravidez, exige cuidados intensivos devido\nà extrema gravidade","B":"o propranolol pode ser usado, porém em baixas doses e por um curto e período de tempo, para\nevitar efeitos prolongados sobre o feto, como bradicardia ou retardo de crescimento intrauterino","C":"o propiltiouracil não deve ser indicado para o tratamento no 1° trimestre, devido ao risco de\nembriopatia acentuada","D":"a administração de iodo-131, como forma definitiva de tratamento do hipertireoidismo, é\ncontraindicada durante a gravidez"},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-216449","number":"216449","sourceNumber":"216449","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Marque a alternativa INCORRETA:","options":{"A":"O hipotireoidismo primário é uma importante causa de hiperprolactinemia.","B":"Os achados clínicos típicos da hiperprolactinemia são: amenorreia e galactorreia.","C":"A principal causa de hiperprolactinemia é o tumor hipotalâmico produtor de prolactina.","D":"O tratamento da hiperprolactinemia por adenoma hipofisário produtor de prolactina é feito com o\nuso de agonistas dopaminérgicos."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-214119","number":"214119","sourceNumber":"214119","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Mulher portadora de cancêr de mama e em uso de dexametasona (10mg) em cada\nseção de quimioterapia, evoluiu com aumento\nde glicemia de jejum (200mg/dl) hemoglobina glicada\nde 8% e triglicérides de 200mg. Diante dessa situação as medidas iniciadas são","options":{"A":"reduzir ou suspender a dexametasona, estimular a realização de exercícios físicos, reeducação\nalimentar e metiformina.","B":"manter a dexametasona na mesma dose, pois ela não interfere na glicemia e inicar o uso de\ninsulina NPH.","C":"reduzir ou suspender a dexametasona e iniciar uso de insulina glargina.","D":"manter a dexametasona ajustando a dose, estimular realização de exercícios físicos e\nreeducação alimentar."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-217088","number":"217088","sourceNumber":"217088","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Sobre os distúrbios da tireoide, julgue os seguintes itens. I. O hipotireoidismo\ncongênito\né a principal causa evitável de deficiência\nmental, com ocorrência de 1 a cada 3000 ou 4000\n\nrecém-nascidos, aproximadamente. II. O hipotireoidismo adquirido tem início insidioso, podendo\nocorrer em qualquer fase da vida. III. Na\nfaixa etária pediátrica, a doença de Graves responde por\nmais de 90% dos casos de hipertireoidismo. É mais prevalente no sexo feminino e sua incidência\ntem pico entre 11 e 15 anos. Pode-se afirmar que:","options":{"A":"Todos os itens estão certos.","B":"Apenas os itens I e II estão certos.","C":"Apenas os itens I e III estão certos.","D":"Apenas os itens II e III estão certos.","E":"Apenas o item II está certo."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-214154","number":"214154","sourceNumber":"214154","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Algumas sindromes genéticas estão associadas a neoplasias, de forma que a Sindrome\nNeuroendocrina Multipla tipo 2 (MEN-2) está associada a mutação ativadora do proto-oncogene\nRET. As principais manifestações clínicas desta sindorme incluem:","options":{"A":"hiperparatireoidismo primário, tumor carcinoide produtor de somatostaina e feocromocitoma.","B":"feocromocitoma, hipertireoidismo e hiperpartiroidismo pirmário.","C":"feocromocitoma, tumor carcinoide produror de somatostatina e hiperparatireoidismo primário.","D":"hiperparatireoidismo primário, feocromocitoma e carcinoma medular de tireoide."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-205585","number":"205585","sourceNumber":"205585","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Assinale a alternativa INCORRETA sobre as características clínicas das Síndromes de\nNeoplasias Endócrinas Múltiplas:","options":{"A":"A Síndrome NEM2A está associada à feocromocitoma e hiperparatiroidismo.","B":"A Síndrome NEM2B associa-se a neuromas mucosas e anormalidades esqueléticas.","C":"A Síndrome NEM2B tem padrão de herança autossômico dominante e são causadas por\nmutações no proto-oncogene RET no cromossomo 10.","D":"A anormalidade endócrina mais comum é a NEM2."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-205648","number":"205648","sourceNumber":"205648","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Medicamento que NÃO aumenta a prolactina é:","options":{"A":"Levodopa.","B":"Metildopa.","C":"Metoclopramida.","D":"Sulpirida."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-178793","number":"178793","sourceNumber":"178793","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Qual a manifestação mais comum da síndrome de Cushing?","options":{"A":"Obesidade centrípeta.","B":"Hipertensão.","C":"Fadiga e Fraqueza.","D":"Edema.","E":"Estrias violáceas."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-173543","number":"173543","sourceNumber":"173543","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente de 27 anos procura assistência médica por causa de palpitações, sudorese e\ntremores de extremidades há 72 horas. Apresenta retração palpebral, sem proptose. A tireoide é\naumentada de volume difusamente e dolorosa à palpação, sem eritema. FC = 116 bpm. PA =\n160x70 mmHg. Exames laboratoriais: TSH = 0,03 (VR 0,4-4,0 mUI/L); T4 total = 18 (VR 6 a 12\nmcg/dL); T4 livre = 3,9 (VR 0,7 a 1,8 ng/dL); T3 = 280 (VR 70 a 180 ng/dL). TRAb = 1,0 (VR < 1,75\n\nUI/mL). Nesse caso, o paciente deve","options":{"A":"iniciar antibioticoterapia de imediato e realizar US cervical para drenar os prováveis abscessos\ntireoidianos.","B":"apresentar VSH, tireoglobulina e proteína C reativa elevados e espera-se uma captação de iodo\nradioativo em 24 horas inferior a 5%.","C":"inicar droga antitireoidiana imediatamente, por se tratar de doença de Graves.","D":"estar em uso de hormônio tireoidiano exógeno, o que pode ser confirmado com a dosagem da\ntireoglobulina elevada."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-174113","number":"174113","sourceNumber":"174113","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Nas situações de diagnóstico do hipotireoidismo e do hipertireoidismo primários, a\ndosagem sérica do TSH é o teste mais confiável.\nPorém, em determinadas situações, essa\ndosagem pode apresentar algumas limitações na avaliação da função tireoidiana. Dessa forma:","options":{"A":"Níveis séricos diminuídos de hormônios tireoidianos são acompanhados de concentrações\nelevadas de TSH nos usuários de biotina em altas\ndoses, sem correlacionar com doença clínica.","B":"Pacientes com hipotireoidismo sem adesão ao tratamento e que fazem uso adequado de\nlevotiroxina semanas antes da coleta de sangue\npodem apresentar valores séricos baixos de TSH e\naltos de hormônios tireoidianos.","C":"Pacientes com disfunção tireoidiana crônica e grave podem apresentar o TSH ainda alterado,\napesar da normalização dos níveis séricos\ndos hormônios tireoidianos.","D":"Medicações como dopamina e glicocorticoides têm ação estimuladora na secreção do TSH,\npodendo mimetizar o hipertireoidismo primário."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-185110","number":"185110","sourceNumber":"185110","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Sobre a síndrome de Cushing não iatrogênica, verifica-se o seguinte:","options":{"A":"As principais causas são os tumores de hipófise ou a secreção ectópica de ACTH.","B":"Apesar do cortisol matinal elevado, o cortisol na urina de 24h está reduzido.","C":"O teste com doses baixas de dexametasona não suprime o cortisol e é útil para o diagnóstico.","D":"Obesidade, alteração menstrual, hirsutismo, hipotensão e edema são comuns em mulheres."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-185127","number":"185127","sourceNumber":"185127","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"A respeito dos efeitos da amiodarona sobre a tireoide, sabe-se que:","options":{"A":"a ação da amiodarona sobre a tireoide se dá tanto pelo excesso de iodo quanto pela inflamação\n(tireoidite).","B":"a maioria dos pacientes desenvolve hipotireoidismo ao longo do tratamento.","C":"mesmo em doses mais baixas de amiodarona, a incidência de distúrbios da tireoide é alta.","D":"o hipertireoidismo é a manifestação clínica mais comum e normalmente requer suspensão da\nmedicação."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-186481","number":"186481","sourceNumber":"186481","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"M.T.N., 36 anos, sexo feminino, casada, procura atendimento referindo episódios\nrecorrentes de palpitação, tremor de\nextremidades, insônia e perda ponderal. Nega uso de\nmedicamentos. Refere ter tido um parto normal há 4 meses. Nega outras comorbidades. Ao exame:\ntireoide discretamente aumentada de tamanho à palpação, sem nódulos, ausência de exoftalmia,\ndiscreto tremor de extremidades. Exames laboratoriais: TSH: 0,01 Ul/ml (valor de referência: 0,3 a\n4,2 mUl/ml), T4 livre: 1,9 ng/dl (valores de referência: 0,7 a 1,8 ng/dl), anticorpo antirreceptor\nde\nTSH (TRAB): 0,3 Ul/L (valor de referência: < 1,75 Ul/L). Captação do iodo radioativo mostra uma\nglândula com baixa captação de iodo. Diante do caso, marque a alternativa correta:","options":{"A":"O tratamento deve ser feito com propilitiouracil.","B":"A paciente tem um quadro clínico típico de doença de Graves.","C":"Nesses casos, geralmente o anticorpo antitireoperoxidase (anti-TPO) é positivo.","D":"O tratamento deve ser feito com iodo radioativo."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-186495","number":"186495","sourceNumber":"186495","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"O tratamento de hipotireoidismo subclínico ainda é assunto controverso. Aceita- se\ncomo indicações para o tratamento EXCETO:","options":{"A":"TSH (hormônio estimulador da tireoide) maior que 10 UI/L.","B":"Anticorpo anti-peroxidase positivo.","C":"Se gravidez.","D":"Insônia."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-187569","number":"187569","sourceNumber":"187569","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente submetida a tireoidectomia total por bócio volumoso evoluiu, no primeiro\npós-operatório, com quadro de parestesia peri-oral com sinal de Chvostek presente e espasmos\nmusculares. A causa provável e tratamento indicado para o quadro clínico apresentado são a","options":{"A":"hipocalcemia secundária a tireoidectomia e reposição com levotiroxina.","B":"hipocalcemia secundária a paratireoidectomia inadvertida e reposição com levotiroxina e cálcio\noral domiciliar.","C":"hipocalcemia secundária a paratireoidectomia inadvertida e reposição imediata de cálcio\nendovenoso.","D":"hipocalcemia secundária a tireoidectomia e reposição oral de cálcio e levotiroxina."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-187613","number":"187613","sourceNumber":"187613","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente de 60 anos, sexo feminino, foi submetida a tireoidectomia total por bócio\nmergulhante volumoso e cirurgia tecnicamente difícil. Após extubação paciente evoluiu com franca\ninsuficiência respiratória sendo necessária ventilação sem resposta e nova intubação com achado\nde paresia de prega vocal unilateral. Neste caso a provável causa é lesão de nervo.","options":{"A":"laríngeo inferior.","B":"laríngeo recorrente unilateral,","C":"vago.","D":"vago e laríngeo superior."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-187606","number":"187606","sourceNumber":"187606","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente adulto jovem, com diagnóstico prévio de hipertensão primária procurou\natendimento médico devido à queixa de\ntaquicardia, cefaleia e sudorese. Tendo em vista não ter\nmelhorado com o anti-hipertensivo prescrito no posto de saúde, insistiu em nova consulta médica\nonde foi realizada ultrassonografia com achado de tumoração em adrenal esquerda. Na suspeita de\nfeocromocitoma a conduta é","options":{"A":"suspender medicações e pesquisa de metanefrinas e catecolaminas na urina, tomografia de\nabdome.","B":"suspender medicações e pesquisa de metanefrinas e catecolaminas no soro, ressonância\nmagnética de abdome.","C":"manter medicações e solicitar pré operatório e tomografia de abdome.","D":"manter medicações e pesquisa de metanefrinas e catecolaminas no soro, ressonância\nmagnética de abdome."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-157027","number":"157027","sourceNumber":"157027","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente de 25 anos com irregularidade mestrual e prolactina sérica de 80 ng/ml NÃO\nnecessita inicialmente de qual medida?","options":{"A":"Pesquisa de adenoma hipofisário por ressonância nuclear magnética.","B":"Repetir o exame.","C":"Pesquisar causa medicamentosa.","D":"Solicitar TSH."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-158486","number":"158486","sourceNumber":"158486","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente masculino 35 anos, apresenta perda de peso, intolerância ao calor,\npalpitações, tremores e defecação excessiva há 6\nmeses, e há dois meses notou aumento volume\ndo pescoço e olhos discretamente ?saltados?. Qual o possível diagnóstico para este paciente?","options":{"A":"Síndrome de Cushing.","B":"Insuficiência adrenal.","C":"Doença de Graves.","D":"Feocromocitoma."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-150195","number":"150195","sourceNumber":"150195","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente do sexo masculino foi submetido a TC de crânio devido a cefaleia, sendo\nsugerido imagem em região hipofisária. Realizada\nRM de hipófise que evidenciou lesão de 0,5 cm à\ndireita da hipófise, sem extensão extra-hipofisária. Durante avaliação com endocrinologista, o\npaciente encontrava-se assintomático, com exame físico normal, sem antecedentes pessoais\npatológicos e sem uso de medicações. De acordo com as recomendações da Endocrino Society, o\nseguimento do paciente deverá ser feito com:","options":{"A":"Realização de campimetria visual manual ou computadorizada ao diagnóstico.","B":"Avaliação clínica e laboratorial de hiperfunção e hipofunção hipofisária ao diagnóstico.","C":"Realização de RMN de hipófise de seis em seis meses.","D":"Realização de avaliação da função hipofisária de seis em seis meses."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-150745","number":"150745","sourceNumber":"150745","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Para o tratamento da tireotoxicose por tireoidite granulomatosa subaguda, é mais\nindicada a seguinte opção terapêutica:","options":{"A":"Metimazol.","B":"Propiltiouracila.","C":"Propranolol.","D":"Ablação com iodo radioativo."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-156470","number":"156470","sourceNumber":"156470","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Marque a afirmativa correta:","options":{"A":"Na acromegalia existe deficiência do hormônio GH.","B":"No Diabetes Insipido existe secreção aumentada do hormônio antidiurético (ADH).","C":"Puberdade precoce é definida como surgimento dos caracteres sexuais secundários em idade\ninferior a 12 anos.","D":"No hipopituitarismo com deficiência de gonadotrofinas pode levar a oligomenorreia e\ninfertilidade."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-156497","number":"156497","sourceNumber":"156497","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Marque a afirmativa correta:","options":{"A":"Na doença de Addison a produção de glicocorticoides esta aumentada.","B":"O hiperaldosteronismo primário é condição clínica caracterizada por produção excessiva de\naldosterona pelo córtex suprarrenal.","C":"A Doença de Behcet está associada a tumor maligno da suprarrenal.","D":"Na hemocromatose o ferro corporal esta diminuído."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-157024","number":"157024","sourceNumber":"157024","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Um recém-nascido de 10 dias é atendido com quadro de icterícia. A mãe relata que ele\npermaneceu internado na maternidade durante 5 dias por ter apresentado hipoglicemia e icterícia.\nO peso e o comprimento ao nascer são 3.000 g e 49 cm, respectivamente. Ao exame físico,\nmostrou-se ativo, ictérico, com tônus adequado, micropênis e testículos tópicos. Assinale a\nalternativa correta, que apresenta o diagnóstico mais provável.","options":{"A":"Síndrome de Noonan.","B":"Hipotireoidismo congênito.","C":"Hipopituitarismo.","D":"Síndrome de Silver-Russe."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-157030","number":"157030","sourceNumber":"157030","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Um recém-nascido com 2 semanas de vida, mamando exclusivamente ao seio materno,\napresenta perda de peso, recusa alimentar, vômitos, desidratação com sódio = 120 mEq/L e\npotássio = 6,5 mEq/L, além de glicemia de 40 mg/dL. Qual é o diagnóstico mais provável?","options":{"A":"Filho de mãe diabética.","B":"Ingestão insuficiente de leite.","C":"Hiperplasia adrenal congênita.","D":"Estenose hipertrófica do piloro."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-150258","number":"150258","sourceNumber":"150258","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Recém-nascido submetido ao teste do pezinho, com 24 horas de vida, é levado à\nprimeira consulta pediátrica com o exame cujo\nresultado apresenta o seguinte valor: TSH 15 ?U/ml\n(valor de referência < 10 ?U/ml). Neste caso, a conduta deve ser:","options":{"A":"tratar o hipotireoidismo.","B":"repetir a coleta do TSH.","C":"dosar a tireoglobulina.","D":"realizar USG cervical."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-127094","number":"127094","sourceNumber":"127094","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Com relação às condutas no perioperatório de tireoidectomia em paciente com\ndiagnóstico de hipertireoidismo, assinale a afirmativa incorreta.","options":{"A":"Manter o uso de soluções iodadas por via oral no pré-operatório, pode reduzir o fluxo sanguíneo,\na friabilidade e o sangramento da tireoide no\nperioperatorio.","B":"Está contraindicado o uso de iodo por via oral no pré-operatório de tireoidectomia em paciente\ncom bócio nodular tóxico.","C":"Na presença de tireotoxicose, é necessário administrar drogas antitireoidianas,\nbetabloqueadores e glicocorticoides antes da tireoidectomia.","D":"Soluções iodadas e tionamida devem ser mantidas por, pelo menos, 5 dias após a\ntireoidectomia."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-127097","number":"127097","sourceNumber":"127097","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Todos os sinais e sintomas a seguir são compatíveis com hipertireoidismo, exceto:","options":{"A":"Menorragia.","B":"Ansiedade.","C":"Mixedema pré-tibial.","D":"Diarreia."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-128006","number":"128006","sourceNumber":"128006","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Dentre os achados clínicos abaixo, serão encontrados com maior probalidade num\npaciente que apresenta altos títulos de anticorpo antirreceptor de tireotrofina:","options":{"A":"Pele seca e macroglossia","B":"Obstipação e hipertensão diastólica","C":"Hipertensão sistólica e insônia","D":"Depressão e derrame pericárdico"},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-127675","number":"127675","sourceNumber":"127675","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente de 37 anos apresenta bócio difuso discreto, elevação de T4 livre, supressão\nde TSH e captação de radioiodo elevada na 2ª\nhora, mas normal da 24ª hora. Considerando o caso\nclínico:","options":{"A":"A tireotoxicose por tireoidite é o diagnóstico mais provável.","B":"O uso de antitireoidiano por 18 a 24 meses quase sempre leva à cura.","C":"O anticorpo para o receptor de TSH geralmente está elevado nessa doença.","D":"A contaminação por iodo deve ser descartada."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-138241","number":"138241","sourceNumber":"138241","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente do sexo feminino teve diagnóstico de tiroidite de Hashimoto aos 20 anos,\nquando foram detectados TSH = 20 mUI/L,\nanti-TPO e anti-Tg positivos. Durante a vida da paciente\nserá necessário adequar a dose de L-tiroxina para valores de TSH considerados ideias para cada\nperíodo. Qual valor de TSH está adequadamente correlacionado com o estágio de vida?","options":{"A":"Gravidez, primeiro trimestre - TSH <2,5 mUI/L.","B":"Gravidez, segundo trimestre - TSH <3,0 mUI/L.","C":"Adulta jovem - TSH entre 0,5-2,5 mUI/L.","D":"Idosa - TSH <2,5 mUI/L."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-127351","number":"127351","sourceNumber":"127351","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Quanto ao tratamento de arritmias cardíacas, eventualmente indicamos antiarrítmicos\nvia oral. Qual dos listados abaixo interage\nfortemente com a disfunção tireoidiana?","options":{"A":"Propafenona.","B":"Amiodarona.","C":"Propranolol.","D":"Digoxina."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-102507","number":"102507","sourceNumber":"102507","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Uma pré-escolar de 5 anos apresenta história de poliúria, polidipsia e naúseas. O\nexame físico revela a presença de desidratação\nintensa e taquidispneia importante. Levando em\nconta o provável diagnóstico desse caso, estará ocorrendo, nessa criança:","options":{"A":"Redução da quebra de triglicérides.","B":"Redução do catabolismo de aminoácidos.","C":"Baixa concentração intracelular de potássio.","D":"Elevação da incorporação periférica de glicose.","E":"Redução na concentração sérica de insulina e hiposmolaridade sérica."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-112360","number":"112360","sourceNumber":"112360","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente do sexo feminino, de 40 anos, traz Ultrassonografia (US) de tireoide\nmostrando nódulo de 20 mm em lobo direito,\nhipoecoico, com margens regulares e calcificações\ngrosseiras no seu interior, sem qualquer outra alteração no parênquima tireoidiano. Provas de\nfunção tireoidiana normais. Solicitada punção aspirativa com agulha fina guiada por US do nódulo\nde lobo direito, cujo resultado citológico foi: ?Bethesda I ? Amostra não diagnóstica?.\n\nQual conduta deve ser indicada para a paciente?","options":{"A":"Realizar tireoidectomia.","B":"Repetir a punção aspirativa com agulha fina, guiada por US dentro de 3-6 meses.","C":"Solicitar cintilografia com radioiodo.","D":"Seguir com US de tireoide."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-111401","number":"111401","sourceNumber":"111401","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"São causas de hipopotassemia, exceto:","options":{"A":"Doença de Addison.","B":"Vômitos e diarreias.","C":"Tratamento com Anfotericina B.","D":"Diurese osmótica.","E":"Insulinoterapia."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-111407","number":"111407","sourceNumber":"111407","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Qual tratamento é uma opção indicada na Doença de Plummer?","options":{"A":"Uso prolongado de drogas anti-convulsivantes","B":"Embolização arterial","C":"Vagotomia seletiva","D":"Tireoidectomia","E":"Dilatação uretral"},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-109193","number":"109193","sourceNumber":"109193","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Uma paciente recentemente diagnosticada com prolactinoma apresenta um irmão e\numa irmã acometidos pela mesma patologia. Na\ninvestigação etiológica, qual dos exames abaixo\nvocê NÃO solicitaria:","options":{"A":"Glicemia.","B":"PTH.","C":"Gastrina.","D":"Calcitonina."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-101157","number":"101157","sourceNumber":"101157","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Mulher de 27 anos, assintomática, descobriu nódulo na região cervical. Foi submetida à\nultrassonografia de tireoide, que evidenciou nódulo localizado no terço médio do lobo esquerdo. Era\núnico, sólido, heterogêneo, predominantemente hipoecogênico, com microcalcificações e\ncalcificações grosseiras, bem delimitado por fino halo hipoecogênico, medindo 2,3 x 1,8 x 1,5 cm.\n\nPara esta paciente, a conduta adequada é:","options":{"A":"Iniciar terapia de supressão com levotiroxina, com o objetivo de reduzir o tamanho do nódulo\ntireoidiano e minimizar o risco de malignização.","B":"Solicitar controle ultrassonográfico de tireoide em seis meses para avaliar a evolução do nódulo\ne redefinir a conduta.","C":"Indicar tireoidectomia total pelo alto risco de malignidade, dadas as características do nódulo.","D":"Solicitar Punção Aspirativa por Agulha Fina (PAAF), guiada por ultrassonografia, do nódulo\ntireoidiano."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-106729","number":"106729","sourceNumber":"106729","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente feminina, 34 anos de idade, procura assistência médica em função de\nnervosismo e choro frequentes, ?coração\ndisparado?, não tolera calor e tem sudorese aumentada.\nAo exame físico, apresenta frequência cardíaca de 102 bpm, pressão arterial 130 x 90 mmHg, pele\nquente e úmida, discreto espessamento da pele nas regiões tibiais. Mediante o caso clínico\ndescrito, escolha a alternativa correta acerca da principal hipótese diagnóstica e medidas\ncomplementares.","options":{"A":"Hiperparatiroidismo, dosar hormônios tireoidianos e iniciar levotiroxina.","B":"Síndrome do pânico, iniciar sertralina e encaminhar paciente para suporte de psicanálise.","C":"Feocromocitoma e solicitar tomografia de abdome.","D":"Hipertiroidismo, dosar hormônios tireoidianos e solicitar ultrassonografia de tireoide."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-111403","number":"111403","sourceNumber":"111403","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Que artéria, dentre as que irrigam a glândula tireoide, normalmente irriga o lobo\npiramidal?","options":{"A":"Tireoidiana IMA.","B":"Tireoidiana inferior.","C":"Tireoidiana media.","D":"Tireoidiana superior anterior.","E":"Tireoidiana superior posterior."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-110242","number":"110242","sourceNumber":"110242","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Mulher de 63 anos procura atendimento na unidade básica de saúde com queixa de\nastenia, inapetência, irritabilidade e sonolência excessiva há 3 meses. É hipertensa em uso regular\nde enalapril, sem outras comorbidades. Na investigação do quadro, apresentou TSH 6,5 mg/L (\nreferência 0,5 - 5,0 ), T4 livre 0,9 mg/L ( referência 0,8 - 1,8 ) e anti-TPO positivo. Em relação\nao\nquadro tireoideano, a conduta deve ser:","options":{"A":"Repetir TSH e T4 livre em dois meses para confirmar o diagnóstico.","B":"Solicitar cintilografia de tireoide e iniciar levotiroxina se não houver hipercaptação.","C":"Iniciar levotiroxina independentemente de exames adicionais.","D":"Solicitar ultrassonografia de tireoide e iniciar levotiroxina se não houver nódulos."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-110192","number":"110192","sourceNumber":"110192","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Em relação aos tumores neuroendócrinos, verifica-se que:","options":{"A":"A localização mais comum do tumor carcinoide é no duodeno.","B":"Os glucagonomas são tumores associados à dermatite intensa.","C":"O tumor relacionado com a tríade de Whipple é o vipoma.","D":"Os tumores carcinoides de origem gástrica associados à síndrome de Zollinger Elisson são\npertencentes ao grupo I."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-111391","number":"111391","sourceNumber":"111391","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Em relação à vitamina D, podemos afirmar:","options":{"A":"A vitamina D3, ou colecalciferol, é produzida por fungos.","B":"A vitamina D é metabolizada no rim, com a formação de 25 (OH)D.","C":"A 25 (OH)D é hidroxilada no intestino, formando a 1,25 (OH)2D.","D":"A 1,25 (OH)2D promove a absorção de cálcio e fósforo pelo intestino.","E":"A excreção da vitamina D é hepática, via sistema citocromo P450."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-109368","number":"109368","sourceNumber":"109368","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"A Hiperplasia Adrenal Congênita (HAC) engloba um grupo de síndromes que são\ncaracterizadas por defeitos hereditários em distintas etapas enzimáticas na biossíntese do cortisol,\ncom consequências potencialmente graves, principalmente nas formas perdedoras de sal, nas\ncrianças acometidas. Nesta doença,","options":{"A":"a hiponatremia e a hipercalemia são distúrbios que frequentemente levam ao óbito, em casos\nnão tratados.","B":"as crises de perda de sal manifestam-se entre o segundo e o sétimo dias de vida.","C":"a deficiência enzimática mais comum é a 11-hidroxilase.","D":"os pacientes acometidos com a forma clássica devem receber tratamento até a puberdade."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-103684","number":"103684","sourceNumber":"103684","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Sobre o tratamento da CAD, assinale a afirmativa CORRETA:","options":{"A":"Quando a glicemia for superior a 500 mg/dl, deve-se fazer uma dose de ataque de insulina\nregular (1UI/kg) visando redução rápida da glicemia.","B":"Quando a glicemia atinge 200 a 250 mg/dl, deve-se suspender a infusão de insulina regular\n(0,1UI/kg/h) e iniciar com insulina NPH (0,5UI/kg).","C":"Enquanto estiver recebendo a infusão de insulina regular (0,1UI/kg/h), o paciente não pode\nreceber alimentação via oral.","D":"A interrupção da infusão de insulina regular está condicionada à estabilização da glicemia,\nnormalização do anion GAP (reversão da acidose) e cetonemia negativa."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-89981","number":"89981","sourceNumber":"89981","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Não corrobora o diagnóstico de Doença de Addison:","options":{"A":"Eosinofilia.","B":"Hipercalcemia.","C":"Hiperglicemia.","D":"Hiperpotassemia.","E":"Hiponatremia."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-90030","number":"90030","sourceNumber":"90030","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Sobre o Feocromocitoma, podemos afirmar:","options":{"A":"Alta ocorrência em pacientes com neurofibromatose.","B":"Apesar de labilidade da pressão arterial, raramente ocorre alterações da frequência cardíaca.","C":"É uma causa muito incidente de hipertensão arterial.","D":"É uma neoplasia das células de Cushing.","E":"Quando familiar, são frequentemente bilaterais e extrassuprarrenais."},"answer":"E","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-78153","number":"78153","sourceNumber":"78153","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Qual a melhor opção para rastreio de síndrome de Cushing?","options":{"A":"ACTH plasmático (2 dosagens) e ressonância magnética de hipófise.","B":"Cortisol urinário livre (3 amostras) e ACTH plasmático.","C":"Cortisol urinário livre (3 amostras) ou cortisol salivar às 23 horas (3 amostras) ou teste de\nsupressão com 1 mg de dexametasona.","D":"Cortisol urinário livre (3 amostras) e teste da supressão com 8 mg de dexametasona."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-84595","number":"84595","sourceNumber":"84595","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Sobre o Adenoma Tóxico, marque a incorreta:","options":{"A":"Os nódulos solitários são tratados com iodo radiotivo.","B":"Em geral são nódulos solitários benignos.","C":"A cintilografia da tireoide mostra um nódulo ?frio? do lobo afetado com supressão completa do\nlobo não afetado.","D":"A investigação laboratorial mostra TSH suprimido e níveis de T3 acentuadamente elevados,\nfrequentemente com um T4 apenas moderadamente acentuado.","E":"As manifestações clínicas são semelhantes da\nTireotoxicose."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-83675","number":"83675","sourceNumber":"83675","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente de 85 anos, sexo masculino, assintomático, em exames de rotina teve valores\nde TSH: 8,5 mU/L (valor de referência: 0,4 a\n4,5 mU/L), T4 livre: 0,97 ng/dl (valor de referência: 0,7\na 1,5 ng/dl) confirmados em uma segunda dosagem. Ultrassonografia da tireoide mostrou nódulo\nde 0,4 cm, sem microcalcificações e Chammas I. Qual a conduta mais adequada?","options":{"A":"Iniciar levotiroxina 1,6 mcg/kg de peso.","B":"Iniciar levotiroxina 1,0 mcg/kg de peso.","C":"Iniciar tri-iodotironina 50 mcg/dia.","D":"Tratar com iodo radioativo.","E":"Acompanhamento com reavaliação laboratorial em 3 meses."},"answer":"E","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-85815","number":"85815","sourceNumber":"85815","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Em relação aos tumores endócrinos do pâncreas, assinale a alternativa CORRETA:","options":{"A":"A tríade de Whipple, caracterizada por sintomas de hipoglicemia, níveis séricos de glicose\nabaixo de 50 mg/dl e a melhora imediata dos\nsintomas após administração de glicose, é encontrada\nem pacientes com somatostatinoma, o tumor endócrino mais comum do pâncreas.","B":"A histologia é capaz de diferenciar gastrinoma benigno e maligno, não sendo necessária a\navalição da presença ou não de metásteses.","C":"A grande maioria dos glucagonomas são benignos. Os glucagonomas malignos são raros e\nocorrem em menos de 5% dos casos.","D":"A associação de hipergastrinemia e hipossecreção gástrica é altamente sugestiva de\ngastrinoma.","E":"A hipoglicemia é responsável pela maioria dos sintomas e sinais de pacientes com insulinoma e\né decorrente do excesso de insulina, que, por\nsua vez, inibe a produção hepática de glicose e\nestimula a utilização periférica de glicose pelos músculos e pelo tecido adiposo."},"answer":"E","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-83866","number":"83866","sourceNumber":"83866","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Doença que apresenta interpretação maligna à citopatologia de nódulo de tireoide.","options":{"A":"Bócio coloide.","B":"Carcinoma papilar.","C":"Cisto coloide.","D":"Neoplasia folicular.","E":"Tireoidite de Hashimoto."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-90015","number":"90015","sourceNumber":"90015","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Quanto à Acromegalia, é incorreto afirmar:","options":{"A":"É causada pela produção excessiva, prolongada e sustentada de hormônio do crescimento.","B":"O hormônio do crescimento em excesso pode ser decorrente de tumores hipofisários.","C":"Hiperidrose pode ser um achado clínico.","D":"Visceromegalia pode ser detectada por exames complementares.","E":"O nível sérico de IGF-1 está reduzido."},"answer":"E","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-84375","number":"84375","sourceNumber":"84375","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"O uso prolongado de corticoide pode ocasionar:","options":{"A":"Linfocitose.","B":"Neutropenia.","C":"Neutrofilia.","D":"Trombocitopenia.","E":"Anemia megaloblástica."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-85774","number":"85774","sourceNumber":"85774","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Antiarrítimico usado no tratamento da crise tireotóxica com o objetivo de impedir os\nefeitos periféricos do hormônio tireoidiano:","options":{"A":"amiodarona.","B":"adenosina.","C":"digoxina.","D":"propranolol.","E":"verapamil."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-85325","number":"85325","sourceNumber":"85325","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente do sexo feminino, com 28 anos de idade, chega à emergência com história de\ntorpor, confusão mental e fala lenta. Tem história de um episódio convulsivo há duas horas. Edema\nfacial com macroglossia. Hiporreflexia. Edema não depressível das extremidades. Hipotérmica.\n\nHistória de infecção urinária em tratamento há três dias. Acompanhante refere que a paciente teve\num \"parto complicado\" há oito anos, com sangramento importante. Exames: hiponatremia; RX de\ntórax: cardiomegalia; aumento de TGO/TGP; gasometria arterial: acidose respiratória. Qual a\nhipótese diagnóstica mais provável e qual a conduta mais adequada?","options":{"A":"Coma mixedematoso - levotiroxina hidrocortisona.","B":"Insuficiência renal aguda - diálise.","C":"Etilismo - vitamina B e glicose.","D":"Intoxicação exógena por \"chumbinho\" - atropina."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-84374","number":"84374","sourceNumber":"84374","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Considera-se hipomagnesemia neonatal quando os níveis plasmáticos de magnésio\nforem inferiores a:","options":{"A":"1,5 mg/dl.","B":"9 mg/dl.","C":"2,5 mg/dl.","D":"2 mg/dl.","E":"6 mg/dl."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-84442","number":"84442","sourceNumber":"84442","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Mulher de 65 anos de idade está em tratamento quimioterápico por causa de linfoma\nnão Hodgkin. Iniciou quadro de febre e confusão\nmental, precedida de astenia e artralgias há 1\nsemana. Foi admitida para internação em hospital, onde foi diagnosticada pneumonia multilobar e\niniciado antibioticoterapia endovenosa. História pregressa de depressão. No segundo dia de\nevolução, o residente de clínica médica solicitou testes de função tireoidiana: TSH: 0,15 mUI/ml\n(VR: 0,3-5,0); T4 livre: 0,7 µg/dl; (VR: 0,7-1,8); T3t: 30 ng/dl (VR: 40-180 ng/dl); anticorpo\nanti-TPO\nnegativo. Qual a principal hipótese diagnóstica e conduta para o caso, respectivamente?","options":{"A":"Nódulo tireoidiano pré-tóxico; solicitar ultrassom e cintilografia de tireoide.","B":"Síndrome de resistência ao hormônio tireoidiano; repetir os testes de função tireoidiana após 6 a\n8 semanas.","C":"Hipotireoidismo central; solicitar ressonância magnética de sela túrcica.","D":"Síndrome do T3 baixo ou do eutireóideo doente; tratar doença de base.","E":"Síndrome do T3 baixo ou do eutireóideo doente; iniciar levotiroxina em baixas doses devido ao\nestado de hipotireoidismo central funcional."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-84413","number":"84413","sourceNumber":"84413","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Os distúrbios eletrolíticos associados ao Diabetes Insípido nefrogênico são:","options":{"A":"Hipercalcemia e hipopotassemia.","B":"Hipocalcemia e hiperpotassemia.","C":"Hipocalcemia e hipopotassemia.","D":"Hipercalcemia e hiponatremia.","E":"Hipocalcemia e hipernatremia."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-69190","number":"69190","sourceNumber":"69190","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Nas hipercalcemias associadas a doenças granulomatosas, como tuberculose,\nsarcoidose ou ainda nos linfomas, o mecanismo fisiopatológico é:","options":{"A":"Secreção ectópica de PTH (paratormônio).","B":"Secreção de PTH-rP (peptídeo relacionado ao PTH).","C":"Aumento de conversão de 25-(OH)-vitamina D para 1,25-(OH)-vitamina D.","D":"Aumento da secreção de calcitonina.","E":"Mutação no receptor do sensor de cálcio (CaSR)."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-61245","number":"61245","sourceNumber":"61245","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Assinale a alternativa correta quanto à síndrome de Cushing:","options":{"A":"o cetoconazol inibe várias enzimas P450 e reduz efetivamente os níveis do cortisol quando\nadministrado 2 vezes ao dia (600 a 1.200 mg/d).","B":"deve-se evitar o tratamento cirúrgico, mantendo-se tratamento contínuo com baixas doses de\ncorticoide sintético, inibindo a produção endógena.","C":"irradiação hipofisária foi abandonada como terapia complementar à cirurgia.","D":"a remoção de ambas as suprarrenais corrige o hipercortisolismo sem necessidade de reposição\nde glico e mineralocorticoides (recoloca\ndepósitos teciduais em circulação).","E":"o mitotano suprime a hipersecreção de cortisol por ativar as enzimas responsáveis pela clivagem\ndas cadeias laterais de 11-beta-hidroxilase e\ndo colesterol, assim como destruir as células\nadrenocorticais."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-69204","number":"69204","sourceNumber":"69204","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente feminina, de 28 anos, relata ter percebido aparecimento de \"nodulação no\npescoço\" há 4 meses, de crescimento\nprogressivo e indolor. Ao se proceder ao exame, delimita-se,\npela palpação da tireoide, um nódulo firme, de 3 cm de diâmetro aproximadamente, indolor à\npalpação. Dado esse quadro, qual exame complementar você escolheria levando em consideração\nseu maior poder de elucidação diagnóstica, sabendo que o TSH da paciente está normal?","options":{"A":"Cintilografia de tireoide.","B":"Ultrassonografia de tireoide.","C":"Punção aspirativa com agulha fina.","D":"Dosagem de calcitonina e tireoglobulina.","E":"Dosagem de T3, T4 e TSH."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-62753","number":"62753","sourceNumber":"62753","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente com 70 anos, do sexo feminino, menopausa há 20 anos, não fez reposição\nhormonal e refere mãe com antecedente de\nfratura do colo do fêmur. É tabagista há 50 anos (20\ncigarros/dia), sedentária, com cifose dorsal aumentada, história de fratura do punho direito após\nqueda de própria altura há 15 anos e tratada com gesso, tem doença de Parkinson, sendo\ndeambuladora domiciliar. Refere que há 12 horas sofreu queda no banheiro de sua casa, sentada,\ncom trauma no quadril esquerdo, com dor e limitação, posição de rotação externa e encurtamento\ndo membro inferior esquerdo, com desvio rotacional e impossibilidade de deambulação. Veio de\nambulância do interior com imobilização provisória e dois exames feitos em sua cidade. Realizada\nhoje uma radiografia da bacia em anteroposterior, que evidencia fratura do colo do fêmur no quadril\nesquerdo, com desvio dos fragmentos e desmineralização óssea difusa e uma densitometria óssea\nde seis meses atrás com T-score na coluna lombar de - 1,8 e no colo do fêmur direito de -1,5. A\npaciente apresenta diagnóstico de:","options":{"A":"osteopenia e necessita tratamento específico para fragilidade óssea com cálcio e vitamina D.","B":"osteomalácea e necessita de tratamento específico para fragilidade óssea com cálcio, vitamina\nD e antirreabsortivos.","C":"osteoporose e necessita de tratamento específico para fragilidade óssea com cálcio e vitamina\nD.","D":"osteoporose estabelecida e necessita tratamento específico para fragilidade óssea com cálcio,\nvitamina D e antirreabsortivos."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-63234","number":"63234","sourceNumber":"63234","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"A forma MAIS COMUM de apresentação do hiperparatireoidismo primário é:","options":{"A":"calcificação de partes moles.","B":"fratura óssea espontânea.","C":"catarata.","D":"cálculo renal.","E":"hipercalcemia assintomática."},"answer":"E","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-63244","number":"63244","sourceNumber":"63244","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Patrícia, 25 anos, é admitida de emergência com pancreatite aguda. TC de abdome\nmostra aumento difuso do pâncreas, líquido entre\nalças, lesões líticas em C4 e crista ilíaca.\n\nDosagem de cálcio = 15 mg/dl. Na história patológica pregressa, apresentou fratura de tornozelo e\número. Assim, a hipótese diagnóstica e o exame a ser solicitado são:","options":{"A":"litíase biliar/CPRE.","B":"mieloma múltiplo/biópsia de medula óssea.","C":"câncer de ovário/laparoscopia.","D":"hipoparatireoidismo/PTH.","E":"hiperparatireoidismo primário/PTH."},"answer":"E","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-63249","number":"63249","sourceNumber":"63249","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Valéria, 52 anos, apresentou no último ano ganho ponderal de 4 kg e aumento da taxa\nde colesterol. Na revisão anual, o médico nota\npele seca e bradicardia, associada a queixa de\nconstipação. A hipótese diagnóstica é:","options":{"A":"hipotireoidismo.","B":"hipoparatireoidismo.","C":"menopausa.","D":"síndrome nefrótica.","E":"diabetes mellitus."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-61701","number":"61701","sourceNumber":"61701","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Recém-nascido de parto vaginal, 36 semanas de gestação, Apgar 9/9, peso: 2,150 g,\ncomprimento: 45 cm. Sua mãe não fez pré-natal e é portadora da doença de Graves não tratada.\nNesse caso, o recém-nascido provavelmente apresentará:","options":{"A":"Tireotoxicose.","B":"Hipotireoidismo.","C":"Bócio eutireóideo.","D":"Bócio hipotireóideo.","E":"Bócio descompensado."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-64596","number":"64596","sourceNumber":"64596","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Paciente do sexo feminino, 39 anos, com paratormônio (PTH): 70 pg/ml (VR: 10-65\npg/ml), calciúria < 100 mg/dia (VR: < 250\nmg/dia) e relação cálcio urinário/clearance de creatinina <\n0,01. Qual a hipótese diagnóstica mais provável?","options":{"A":"Neoplasia produtora de PTH.","B":"Hipercalcemia hipocalciúrica familiar.","C":"Hiperparatireoidismo primário.","D":"Hiperparatireoidismo secundário.","E":"Hiperparatireoidismo terciário."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-61243","number":"61243","sourceNumber":"61243","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Um adolescente de 12 anos vem para a consulta por estar apresentando, no último\nmês, quadro de agitação, dificuldade de\nconcentração e queda no rendimento escolar. Apresenta,\nao exame físico, sudorese, taquicardia, emagrecimento, mãos úmidas e quentes, tremores finos de\nextremidade e aumento de volume em região cervical anterior dolorosa à palpação. A principal\nhipótese diagnostica é:","options":{"A":"doença de graves.","B":"neuroblastoma.","C":"tireoidite supurativa aguda.","D":"carcinoma tireoidiano hiperfuncionante.","E":"síndrome de McCune-Albright."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-61748","number":"61748","sourceNumber":"61748","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Os adenomas hipofisários são tumores benignos com apresentação mais frequente:","options":{"A":"Endócrina, oftálmica e hipertensão intracraniana","B":"Hipertensão intracraniana, sinais focais e endócrina","C":"Endócrina, oftálmica, sinais de compressão do seio cavernoso","D":"Invasão do seio cavernoso, fístula liquórica, hidrocefalia","E":"Fístula liquórica, cefaleia, epilepsia"},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-61772","number":"61772","sourceNumber":"61772","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Com relação à deficiência de vitamina D, podemos afirmar que:","options":{"A":"Pode ser definida como níveis sanguíneos da 25(OH)D < 70 ng/ml.","B":"Pode interferir na força muscular.","C":"É mais comum em pessoas da raça branca e menos comum em pessoas da raça negra.","D":"O uso constante de protetor solar não interfere na síntese de vitamina D.","E":"A deficiência de vitamina D é assintomática e, por isso, não necessita nunca de reposição."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-63245","number":"63245","sourceNumber":"63245","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Sara, 22 anos, atleta, devido ao excesso de atividade física, apresenta alterações\nhormonais. Sobre tais alterações, assinale a alternativa correta.","options":{"A":"Diminuição do GH.","B":"Diminuição da prolactina.","C":"Elevação do ACTH.","D":"Elevação do FSH.","E":"Elevação do TSH."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-61814","number":"61814","sourceNumber":"61814","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Com relação aos distúrbios do cálcio, pode-se afirmar que:","options":{"A":"entre as causas de hipercalcemia dependente do PTH incluem-se o hiperparatireoidismo\nprimário, hipercalcemia secundária ao lítio,\nhiperparatireoidismo terciário e hipercalcemia\nhipocalciúrica familiar.","B":"a hipercalcemia da malignidade é a segunda causa mais comum de hipercalcemia em pacientes\ninternados, sendo mais frequentemente encontrada em carcinomas de pulmão e de mama.","C":"a interpretação laboratorial do cálcio depende da concentração sérica de albumina e do\nequilíbrio acidobásico, uma vez que a acidose\ndiminui o cálcio ionizado, precipitando sintomas de\nhipocalcemia.","D":"na avaliação clínica da hipocalcemia a irritabilidade neuromuscular, o sinal da Chvostek é mais\nespecífico do que o de Trousseau, embora ambos possam estar ausentes nos casos leves.","E":"o tratamento dos pacientes com hipocalcemia, mesmo na forma leve assintomática deve ser\nrealizado, inicialmente, com cálcio endovenoso, devido ao risco de convulsões e arritmias\ncardíacas."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-53564","number":"53564","sourceNumber":"53564","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Mulher, 25 anos, queixa-se de emagrecimento involutário, irritabilidade, insônia e\npalpitações há 30 dias. Apresenta aumento da glânudla tireoide à custa do lobo D, onde se palpa\nnódulo de 1cm, indolor. Há discreta retração palpebral bilateral, sem exoftalmia. Exames\nsubsidiários: T3 total e T4 livre aumentados, TSH suprimido. A captação do iodo radioativo pela\ntireoide em 24 horas é de 2%. O diagnóstico mais provável é:","options":{"A":"bócio difuso tóxico (doença de Graves).","B":"bócio nodular tóxico (doença de Plummer).","C":"tireotoxicose factícia por ingestão de T3.","D":"tireoidite granulomatosa subaguda.","E":"tireoidite silenciosa (\"hashitoxicose\")."},"answer":"E","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-53588","number":"53588","sourceNumber":"53588","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Mulher, 27 anos, refere anorexia, prostração e emagrecimento de 8 kg há 1 ano. Há 8\nmeses, apresenta náuseas, vômitos, tonturas posturais e dor abdominal. Amenorreica há seis\nmeses. Ao exame, está emagrecida e com nítida hipotensão postural. Há hiperpigmentação\ngeneralizada e redução de pelos axilares e pubianos. Que conjunto de manifestações laboratoriais\nespera-se encontrar nesta paciente?","options":{"A":"Hiponatremia - hipocalemia - hiperglicemia.","B":"Hiponatremia - hipercalemia - hiperglicemia.","C":"Hiponatremia - hipercalemia - hipoglicemia.","D":"Hipernatremia - hipercalemia - anemia normocrômica normocítica.","E":"Hiponatremia - hipercalemia - eosinopenia."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-48325","number":"48325","sourceNumber":"48325","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Quando, na Síndrome de Cushing, houver alcalose hipocalêmica importante, a causa\nda Síndrome deve ser:","options":{"A":"Iatrogênica;","B":"Tumor secretante não endócrino;","C":"Adenoma adrenal;","D":"Carcinoma adrenal;","E":"Nenhuma das alternativas anteriores."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-48328","number":"48328","sourceNumber":"48328","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Sueli, 25 anos, vem apresentando fraqueza muscular, irregularidade menstrual e\naumento de peso. Ao exame físico,\napresenta-se levemente hipertensa, obesa, estrias abdominais,\nacne e hirsutismo. A hipótese diagnóstica é:","options":{"A":"Hipoaldosteronismo hiporreninêmico.","B":"Insuficiência adrenal.","C":"Síndrome de Cushing.","D":"Aldosteronismo primário.","E":"Hipotireoidismo."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-48330","number":"48330","sourceNumber":"48330","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Em relação às doenças tireoidianas, podemos afirmar que:","options":{"A":"Carcinoma folicular da tireoide é o tumor mais frequente desta glândula","B":"Bócio endêmico não tóxico nem sempre implica a participação de fatores ambientais","C":"O hipotireoidismo primário deve sempre apresentar níveis aumentados de TSH sérico","D":"A crise tireotóxica pós-operatória é raramente prevenida pelo uso prévio de drogas\nantitireoidianas","E":"A tireoidite de Hashimoto, quando associada com hepatite crônica, apresenta aumento sérico\ndos anticorpos antimúsculo liso"},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-48538","number":"48538","sourceNumber":"48538","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"O hipertireoidismo, se manifesta por um conjunto de sinais e sintomas decorrentes da\nação sistêmica de hormônios tireoidianos em\nníveis elevados. Sobre esta doença podemos afirmar\nque:","options":{"A":"O Adenoma Tireoidiano Tóxico é mais comum em Homens, com frequência em torno de cinco\nvezes aumentada em relação ás Mulheres","B":"a doença de Basedow-Graves é a causa mais comum de tireotoxicose em pacientes acima de\n40 anos, 5 a 10 vezes mais frequente em\nMulheres do que em Homens, sem exoftalmia na maioria\ndos casos","C":"O Adenoma Hipofisário produtor de TSH é a forma clínica mais comum da doença de\nHipertireoidismo","D":"Tumores trofoblásticos (mola hidatiforme e coriocarcinoma) são causas frequentes de\nHipertireoidismo","E":"Associação positiva com sistema HLA, por exemplo, HLA DR3 na raça branca"},"answer":"E","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-48992","number":"48992","sourceNumber":"48992","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Com relação ao hipotiroidismo assinale a alternativa correta:","options":{"A":"Bradicardia, redução do debito cardíaco, hipofonese de bulhas e baixa voltagem no QRS são\nmanifestações do hipotiroidismo de longa data não tratado e geralmente não revertem com o\ntratamento.","B":"Hipotiroidismo deve sempre ser investigado em pacientes com dislipidemia, especificamente\nhipertrigliceridemia, pois esta e a alteração mais característica do hipotiroidismo no metabolismo\nlipídico.","C":"A levotiroxina deve ser suspensa nas gestantes pela falta de estudos sobre teratogenicidade.","D":"No hipotiroidismo o TSH e o primeiro hormônio a se alterar e o ultimo a normalizar após inicio do\ntratamento.","E":"Anticorpos anti-TPO e antitireoglobulina estão presentes na Tiroidite de Hashimoto, não sendo\nencontrados em pacientes com Doenças de Graves."},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-51076","number":"51076","sourceNumber":"51076","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Um bebê de um mês é levado à Unidade de Saúde da Família após parto normal\nrealizado em casa. A mãe refere que o bebê é\nconstipado e se alimenta pouco. Ao exame, o bebê\nencontra-se ictérico, com hipotonia muscular, fontanela posterior alargada e uma hérnia umbilical.\nO peso da criança está abaixo do percentil de 10% para a idade. Qual o diagnóstico mais provável?","options":{"A":"atresia biliar","B":"estenose de piloro","C":"sífilis congênita","D":"hipotireoidismo congênito","E":"deficiência de alfa-1-antitripsina"},"answer":"D","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-53576","number":"53576","sourceNumber":"53576","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Lactente, 4 meses, amamentada ao seio materno, apresenta dificuldade de sucção. É\nconstipada, não sustenta a cabeça, não sorri e dorme muito. Nasceu de parto domiciliar, não\nrealizou testes neonatais de triagem nem vacinas. O peso de nascimento foi em torno de 4 kg, teve\nicterícia na face e tronco durante todo o 1° mês de vida, mas não foi tratada. Ao exame, a pele é\nfria e seca, a boca entreaberta, a fontanela anterior ampla; está hipoativa, hipotônica, e apresenta\nhérnia umbilical de 2 cm de diâmetro. Qual a hipótese diagnóstica mais provável para esta criança?","options":{"A":"Encefalopatia bilirrubínica.","B":"Hipovitaminose B.","C":"Hipotireoidismo congênito.","D":"Síndrome de Gilbert.","E":"Hipovitaminose A."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-51087","number":"51087","sourceNumber":"51087","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Helena, 46 anos, é diagnosticada com hiperparatiroidismo e sua cirurgia estava\nmarcada. Enquanto aguardava pela cirurgia ela\ndesenvolveu fraqueza muscular, náuseas, vômitos,\npalpitações e confusão mental de início súbito, sendo trazida ao hospital por familiares . A conduta\nimediata apropriada para Helena é:","options":{"A":"calcitonina endovenosa","B":"soro fisiológico endovenoso","C":"indometacina oral","D":"potássio endovenoso","E":"exploração cirúrgica da paratiroide"},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-34044","number":"34044","sourceNumber":"34044","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Mulher de 35 anos, em tratamento por hiperprolactinemia há três anos, faz uso de\nbromocriptina 5 mg/dia. Apresentou na avaliação inicial prolactina: 82 ng/ml (VR: 2,8-29,2). À\népoca, negou alterações menstruais, galactorreia e diminuição\n\nda libido. Atualmente, a paciente permanece assintomática e com prolactina de 85 mg/ml. Neste\ncaso, qual a melhor conduta?","options":{"A":"Fazer a dosagem da prolactina por precipitação do soro com polietilenoglicol e confirmar\nmacroprolactina.","B":"Fazer a dosagem da prolactina por precipitação do\nsoro com polietilenoglicol e confirmar ?efeito gancho?.","C":"Aumentar a dose da bromocriptina para 10 mg/dia.","D":"Trocar a bromocriptina por cabergolina."},"answer":"A","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-35845","number":"35845","sourceNumber":"35845","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"É correto afirmar sobre Osteoporose, exceto:","options":{"A":"Osteoporose Pós-Menopausa geralmente surge nos primeiros 10 anos após menopausa e a\ndeficiência estrogênica é a anormalidade básica.","B":"Os principais determinantes do risco de Osteoporose são o pico de massa óssea e a velocidade\nde perda óssea, ambos influenciados por fatores\nGenéticos e Ambientais.","C":"Obesas, em comparação a mulheres magras, fazem um pico menor de massa óssea e a perda\nóssea é mais rápida.","D":"A determinação da massa óssea é o melhor indicador mensurável do padrão ósseo e é útil na\navaliação do risco de fraturas osteoporóticas.","E":"A vit. D (colecalciferol) desempenha um importante papel na absorção intestinal do cálcio e na\nmineralização do osso novo, e sua principal fonte é a pele."},"answer":"C","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-05-35864","number":"35864","sourceNumber":"35864","collectionBlock":"med:med-clinica-medica-med-clm-05","collectionLabel":"MED · MED CLM 05","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 05","subtopic":"","stem":"Em relação ao Hipertireoidismo por Doença de Graves, é correto afirmar, exceto:","options":{"A":"Clinicamente, é caracterizada por perda de peso, fraqueza, palpitações, dispneia, insônia e\ntremor de extremidades.","B":"O percentual de pacientes tratados com antitireoidianos (tionamidas) que atingem o\nEutireodismo é muito baixa.","C":"Exoftalmia, edema periorbitário, proptosis, diplopia e quemose são manifestações de\nOftalmopatia de Graves.","D":"Ao contrário do que acontece com o tratamento com drogas antitireoidianas, a Oftalmopatia\npode ser piorada com Iodoterapia.","E":"Em crianças, o tratamento de escolha é com drogas antitireoidianas."},"answer":"B","source":"Clinica médica/MED CLM 05/MED CLM 05.txt","sourceLabel":"MED · MED CLM 05","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 05","MED"],"answerSource":"inferred","commentDeferred":true}]};
